  FT["PH-H6113"] = {"id":"PH-H6113","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7631_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将武端市马金达描笼涯马金达小学的名称变更为Santiago B. Ecleo，Sr.，纪念小学的法案","en":"An Act Changing the Name of the Maguinda Elementary School in Barangay Maguinda, Butuan City, To Santiago B. Ecleo, Sr., Memorial Elementary School","orig":"An Act Changing the Name of the Maguinda Elementary School in Barangay Maguinda, Butuan City, To Santiago B. Ecleo, Sr., Memorial Elementary School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7631","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-07-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7631_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6113-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Maguinda Elementary School in Barangay Maguinda, Butuan City, is hereby changed to Santiago B. Ecleo, Sr., Memorial Elementary School."}},{"id":"PH-H6113-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Maguinda Elementary School in Barangay Maguinda, Butuan City, To Santiago B. Ecleo, Sr., Memorial Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6114"] = {"id":"PH-H6114","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7632_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将东达沃省Manay市镇Manay区医院床位由10张增至25张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Manay District Hospital in the Municipality of Manay, Province of Davao Oriental, From Ten (10) To Twenty-five (25) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Manay District Hospital in the Municipality of Manay, Province of Davao Oriental, From Ten (10) To Twenty-five (25) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7632","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-07-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7632_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6114-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Manay District Hospital in the Municipality of Manay, Province of Davao Oriental, is hereby increased from ten (10) to twenty-five (25) beds."}},{"id":"PH-H6114-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law."}},{"id":"PH-H6114-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Manay District Hospital in the Municipality of Manay, Province of Davao Oriental, From Ten (10) To Twenty-five (25) Beds, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6115"] = {"id":"PH-H6115","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7633_1992.html","fetchedAt":"2026-10-06","articleCount":23,"structureMode":"ARTICLE","title":{"zh":"对第 3259 号共和国法的修改","en":"An Act Amending Certain Sections of Republic Act No. 3259, As Amended, Entitled \"An Act Granting the International Communications Corporation A Franchise To Establish Radio Stations, For Domestic Telecommunications, Radiophone,\" Extending the Term of the Franchise By Twenty-five (25) Years From August 9,1996 As Provided in Republic Act No. 4905, and For Other Purposes","orig":"An Act Amending Certain Sections of Republic Act No. 3259, As Amended, Entitled \"An Act Granting the International Communications Corporation A Franchise To Establish Radio Stations, For Domestic Telecommunications, Radiophone,\" Extending the Term of the Franchise By Twenty-five (25) Years From August 9,1996 As Provided in Republic Act No. 4905, and For Other Purposes"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 7633","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-07-20","completenessNote":"全文，共 23 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7633_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 4 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6115-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section One of Republic Act No. 3259 is hereby amended to read as follows:\nSECTION. 1. Subject to the provisions of the Constitution and the provisions of laws, orders or issuances not inconsistent herewith, the International Communications Corporation, its successors or assigns, hereunder referred to as the grantee, is hereby granted the right, privilege and authority to construct, maintain and operate stations for telecommunications systems including radio, telegraph, telephone, facsimile, data, voice, audio and video services, lines, circuits, satellites and/or stations, wire and/or wireless for international and domestic public communications, with authority to receive and transmit information, messages, impressions, pictures, music, entertainment and advertising signals, throughout the Philippines and foreign countries, including ships at sea, airplanes and other conveyances, by means of electricity, electromagnetic waves, optics or any other kind of energy, force, variations or impulses, radiated through space or transmitted through any other medium.\""}},{"id":"PH-H6115-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section Four of Republic Act No. 3259, as amended by Republic Act No. 4905, is hereby further amended to read as follows:\n\""}},{"id":"PH-H6115-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The franchise of the grantee, as herein amended, is hereby extended by twenty-five (25) years from the expiration thereof on August 9, 1996.\""}},{"id":"PH-H6115-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall not begin any construction nor exercise any right or privilege under this franchise without first obtaining a certificate of public convenience and necessity from the National Telecommunications Commission or its legal successor of the form and character provided for under existing laws. The National Telecommunications Commission or its legal successor shall have the power to issue such certificate of public convenience and necessity whenever it shall, after due hearing, determine that such construction or such exercise of the right, privilege or franchise is necessary and proper for the public convenience, and the Commission shall have the power in so approving to impose such conditions as to construction, equipment, maintenance service or operation as the public convenience and interest may reasonably require."}},{"id":"PH-H6115-A4-d2","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The rates for the telecommunications services that the grantee shall offer to the public shall be subject to the approval of the National Telecommunications Commission or its legal successor."},"dupIndex":2},{"id":"PH-H6115-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public utilities offering to the stock exchanges at least thirty percent (30%) of its common stock within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock."}},{"id":"PH-H6115-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio spectrum without having been authorized by the Commission. The stations of the grantee shall be constructed and operated in a manner as win at most result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established in accordance with law of other telecommunications services grantees without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6115-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"All telecommunications lines and systems for telecommunications services owned, maintained, operated or managed by the grantee, its successors or assigns shall be operated and maintained at all times in a satisfactory manner, and it shall be the further duty of said grantee, its successors or assigns whenever required to do so by the National Telecommunications Commission or its legal successors to modify, improve and change such telecommunications system in such manner and to such extent as the progress of silence and improvements in the telecommunications services may make reasonable and proper."}},{"id":"PH-H6115-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6115-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The President of the Philippines, in times of war, rebellion, public peril calamity, emergency, disaster or disturbance of peace and order, may take over and operate the transmitting, receiving and switching stations Or authorize the temporary use and operation thereof by any department of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6115-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall keep an account of the gross receipts of its business and shall furnish the Commissioner on Audit and the Treasurer of the Philippines with a copy of such accounts not later than the thirty-first day of January of each year for the preceding year. All the books and accounts of the grantee pertaining to its business shall be subject to the official inspection of the Commission on Audit or its authorized representatives, and the audit and approval of such accounts shall be final and conclusive evidence as to the amount of said gross receipts, except that the grantee shall have the right to appeal to the courts under the terms and conditions provided in the laws of the Philippines."}},{"id":"PH-H6115-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the telephone or other telecommunications businesses transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Tide II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue.\nThe grantee shall submit a detailed annual report to the Congress of the Philippines with respect to its program, operations, accounts, and payment of taxes and compliance with the terms and conditions of its franchise."}},{"id":"PH-H6115-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The National Telecommunications Commission shall have the power, after due notice and hearing, to direct, authorize or order another holder of a certificate of public convenience and necessity or any qualified person or entity to temporarily operate and maintain the grantee's telecommunications services whenever the grantee's certificate is revoked or suspended by the Commission or in case the authorized temporary operator willfully discontinues or abandons his operations thereby causing irreparable damage and serious inconvenience to the public: Provided, That the Commission shall, in a formal order, prescribe the terms and conditions of the said temporary operation, the reasons for the designation of the temporary operator and the restoration to the grantee of said telecommunications service: Provided, further, That in no case shall such order be construed as a grant of a certificate of public convenience and necessity."}},{"id":"PH-H6115-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The National Telecommunications Commission is hereby authorized, after due notice and hearing, to order the grantee to allow interconnection of its facilities with other duly authorized telecommunications operators under such terms and conditions as the Commission may deem proper and reasonable in the interest of public good."}},{"id":"PH-H6115-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The grantee shall operate and maintain all its stations, lines, cables, systems and equipment for the transmission and reception of messages, signals and pulses in a satisfactory manner at all times and, whenever required by the National Telecommunications Commission in the interest of the public good and as far as practicable, modify, improve or change such stations, lines, cables, systems and equipment to keep abreast with the advancement in science and technology."}},{"id":"PH-H6115-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The grantee, its successors or assigns shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H6115-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise, or the rights and privileges acquired thereunder to any person, firm, company, partnership, corporation or other commercial or legal entity, nor merge with any other person, firm, company, partnership or corporation organized for the same purpose except where the grantee is the surviving corporation without the prior approval of the Congress of the Philippines.\nAny corporation to which this franchise may be sold, transferred or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, partnership, corporation or other commercial or legal entity to which this franchise is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, partnership, corporation or other commercial or legal entity."}},{"id":"PH-H6115-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"This franchise shall not be interpreted to mean as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6115-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Within sixty (60) days after effectivity of this Act, the grantee shall file with the National Telecommunications Commission its written acceptance of this Act and all the terms and conditions hereof and, in default of such acceptance, within the time so limited, this Act shall become null and void."}},{"id":"PH-H6115-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"The grantee shall comply with and be subject to the provisions of a general telecommunications policy law that may hereafter be enacted."}},{"id":"PH-H6115-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"AU the other provisions, terms and conditions contained in Republic Act No. 3259 which are inconsistent herewith are hereby repealed."}},{"id":"PH-H6115-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"This franchise is granted with the understanding and upon the condition that it shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the common good so requires."}},{"id":"PH-H6115-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p87"};
  FT["PH-H6116"] = {"id":"PH-H6116","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7634_1992.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授权将授予 Zoilo Dejaresco，Jr. 的保和省广播电视特许经营权转让给 Bohol Chronicle 广播公司，并将期限再延长二十五年的法案","en":"An Act Authorizing the Transfer and Assignment To the Bohol Chronicle Radio Corporation of the Franchise To Construct, Operate and Maintain Television and Radio Broadcasting Stations in the Province of Bohol Granted Under Republic Act Numbered Forty-seven Hundred and Ninety-two To Zoilo Dejaresco, Jr., and All the Properties and Rights Acquired Thereunder of Zoilo Dejaresco, Jr., and Renewing the Terms of the Said Franchise To Another Twenty-five (25) Years From the Date of Effectivity of This Act","orig":"An Act Authorizing the Transfer and Assignment To the Bohol Chronicle Radio Corporation of the Franchise To Construct, Operate and Maintain Television and Radio Broadcasting Stations in the Province of Bohol Granted Under Republic Act Numbered Forty-seven Hundred and Ninety-two To Zoilo Dejaresco, Jr., and All the Properties and Rights Acquired Thereunder of Zoilo Dejaresco, Jr., and Renewing the Terms of the Said Franchise To Another Twenty-five (25) Years From the Date of Effectivity of This Act"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7634","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-07-24","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7634_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6116-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Transfer and Assignment of the Franchise. – The transfer and assignment to the Bohol Chronicle Radio Corporation, a corporation organized and existing in accordance with the laws of the Philippines, of the franchise to construct, operate and maintain television and radio broadcasting stations in the Province of Bohol granted under Republic Act Numbered Forty-seven hundred and ninety-two to Zoilo Dejaresco, Jr., and all the properties and rights acquired thereunder by Zoilo Dejaresco, Jr., is hereby authorized and approved."}},{"id":"PH-H6116-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Incorporation of Other Provisions of Republic Act No. 4792. – All other provisions, terms and conditions contained in Republic Act No. 4792 which are still in force and are not affected by this Act are hereby made integral parts of this Act."}},{"id":"PH-H6116-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Parity Clause. – In the event any competing individual, partnership or corporation has received or shall receive from the Congress of the Philippines a similar franchise containing any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H6116-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law."}},{"id":"PH-H6116-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Prior Approval of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6116-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Responsibility to the Public. – The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language or speech, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6116-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Right of Government. - The President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may temporarily take over and operate the stations of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6116-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations which are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title 11 of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6116-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Self-regulation by and Undertaking of Grantee. – The grantee shall not require any previous censorship of any speech, play, act, scene or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act, scene or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act, scene or other matter: Provided, That the grantee, during any broadcast or telecast, shall cut off from the air the speech, play, act, scene or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6116-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6116-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6116-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Renewal of the Franchise. – The term of the franchise granted under Republic Act No. 4792 is hereby renewed to another twenty-five (25) years from the date of effectivity of this Act."}},{"id":"PH-H6116-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"General Broadcast Policy Law. – The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H6116-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Separability Clause . – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6116-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Repealability and Non-exclusivity Clause. – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6116-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of this franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6116-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Transfer and Assignment To the Bohol Chronicle Radio Corporation of the Franchise To Construct, Operate and Maintain Television and Radio Broadcasting Stations in the Province of Bohol Granted Under Republic Act Numbered Forty-seven Hundred and Ninety-two To Zoilo Dejaresco, Jr., and All the Properties and Rights Acquired Thereunder of Zoilo Dejaresco, Jr., and Renewing the Terms of the Said Franchise To Another Twenty-five (25) Years From the Date of Effectivity of This Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6117"] = {"id":"PH-H6117","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7635_1992.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"授予 Radio Sorsogon Network，Inc. 在 Bicol 大区建设、安装、运营和维护广播及电视站并为其他目的法案","en":"An Act Granting Radio Sorsogon Network, Inc., A Franchise To Construct, Install, Operate and Maintain Radio/Television Broadcasting Stations Within the Bicol Region and For Other Purposes","orig":"An Act Granting Radio Sorsogon Network, Inc., A Franchise To Construct, Install, Operate and Maintain Radio/Television Broadcasting Stations Within the Bicol Region and For Other Purposes"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7635","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-07-24","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7635_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6117-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Radio Sorsogon Network, Inc., hereunder referred to as the grantee, its successors or assigns a franchise to construct, install, operate and maintain for commercial purposes and in the public interest radio/television broadcasting stations in the Bicol Region with the corresponding technological auxiliaries or facilities, special broadcast and other program and distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H6117-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6117-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6117-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6117-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations of the grantee, to temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6117-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from the date of approval of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H6117-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing within sixty (60) days after approval of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H6117-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6117-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Self-regulation by and Undertaking of Grantee. - The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene, or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene, or other matter: Provided, That the grantee, during any broadcast and telecast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6117-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6117-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor shall the controlling interest in the grantee be transferred to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6117-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause . – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6117-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealability Clause. – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6117-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Effectivity Clause. – This Act shall take effect upon its approval."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Radio Sorsogon Network, Inc., A Franchise To Construct, Install, Operate and Maintain Radio/Television Broadcasting Stations Within the Bicol Region and For Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6118"] = {"id":"PH-H6118","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7636_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"废止第1700号共和国法（即《反颠覆法》）的法案","en":"An Act Repealing Republic Act Numbered One Thousand Seven Hundred, as Amended, otherwise known as the Anti-Subversion Act","orig":"An Act Repealing Republic Act Numbered One Thousand Seven Hundred, as Amended, otherwise known as the Anti-Subversion Act"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7636","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-09-24","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7636_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6118-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Republic Act Numbered One Thousand Seven Hundred (R.A. No. 1700), otherwise known as the Anti-Subversion Act, as revived by Executive Order Numbered One Hundred Sixty-Seven (E.O. No. 167) and subsequently amended by Executive Order Numbered Two Hundred Seventy-Six (E.O. No. 276) is hereby repealed."}},{"id":"PH-H6118-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act does not in any manner repeal, amend or modify the provisions of the Revised Penal Code."}},{"id":"PH-H6118-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Presidential Decrees Nos. 885, 1736, 1835 and 1975 remain repealed, and all other laws, presidential decrees, letters of instruction, and other issuances, orders, rules and regulations inconsistent with this Act are hereby likewise repealed."}},{"id":"PH-H6118-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in two (2) national newspapers of general circulation."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Repealing Republic Act Numbered One Thousand Seven Hundred, as Amended, otherwise known as the Anti-Subversion Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6119"] = {"id":"PH-H6119","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7637_1992.html","fetchedAt":"2026-10-06","articleCount":20,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Ten Billion Pesos for the Aid, Relief, Resettlement, Rehabilitation and Livelihood Services as well as Infrastructure Support for the Victims of the Eruption of Mt. Pinatubo, Creating the Mt. Pinatubo Assistance, Resettlement and Development Commission, and for Other Purposes","orig":"An Act Appropriating the Sum of Ten Billion Pesos for the Aid, Relief, Resettlement, Rehabilitation and Livelihood Services as well as Infrastructure Support for the Victims of the Eruption of Mt. Pinatubo, Creating the Mt. Pinatubo Assistance, Resettlement and Development Commission, and for Other Purposes"},"level":"law","status":"active","topics":["company"],"docNumber":"Republic Act No. 7637","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-09-24","completenessNote":"全文，共 20 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7637_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6119-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. – This Act shall be known as the \" Mt. Pinatubo Assistance, Resettlement and Development Fund. \""}},{"id":"PH-H6119-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. – It is hereby declared the policy of the State to assist the victims in the communities damaged or destroyed or adversely affected by the eruption of Mt. Pinatubo and its aftereffects by extending to them aid, relief, resettlement, rehabilitation or repair and reconstruction of infrastructure to the end that life may return to normalcy at the earliest possible time and the development of Central Luzon may be accelerated.\nIt is hereby further declared the policy of the State to restore the living conditions of the Aetas and other members of the cultural communities in the area to their productive pre-eruption conditions, with the settlement being chosen according to its suitability as permanent upland abodes thereby ensuring the improvement of these communities.\nCountless individuals, organizations and financial institutions here and abroad, as well as foreign governments, have spontaneously and unselfishly contributed their time, effort and resources which the State acknowledges with gratitude."}},{"id":"PH-H6119-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Statement of Objectives and Guidelines. – This Act is intended to help the victims of the eruption of Mt. Pinatubo and its aftereffects. It aims to provide additional funds for the immediate relief of the victims; to establish resettlement centers, homesites and townsites for displaced families; to provide livelihood and employment opportunities; to repair, reconstruct or replace government infrastructure damaged or destroyed by said disaster whenever economically, socially and technically advisable; and to construct new infrastructure facilities by the community.\nThe term \"victims\" when used for purposes of this Act refers to the following:\n(a) Individuals who have died or disappeared as a result of the aforementioned eruption;\n(b) Individuals who were displaced and/or who sustained injury or suffered death in the family as a result of the aforementioned eruption who need and deserve assistance; and\n(c) Individuals whose homes have been or are threatened to be destroyed or rendered uninhabitable and those who have lost permanently their livelihood as a direct result of the Mt. Pinatubo eruption who similarly need and deserve assistance."}},{"id":"PH-H6119-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Guidelines in the Allocation of Funds. – The government funds and resources herein appropriated shall be spent judiciously and effectively in consonance with the principle of providing the greatest good for the greatest number. Accordingly, the following guidelines shall be observed in allocating the funds made available under this Act;\n(a) In the construction or repair and reconstruction of government infrastructure and facilities, priority shall be given to resettlement centers, homesites and townsites, and such other projects as river system and drainage works, roads, bridges, communication and power lines, hospitals, school buildings, irrigation and water systems, and the like;\n(b) Aid, relief, resettlement, rehabilitation and livelihood services shall be equitably extended to all victims, irrespective of political or party affiliation, sex, creed, religious belief, or ethnic origin, giving emphasis to livelihood and employment opportunities;\n(c) Funds shall be allocated in the first year for the acquisition by appropriate government agencies of special equipment, such as amphibians and other equipment designed for use in the affected areas in an amount not to exceed Fifty million pesos (P50,000,000); and\n(d) No money shall be released without any identified program and project nor shall it be used to pay obligations incurred before the approval of this Act."}},{"id":"PH-H6119-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Appropriations Clause. – To carry out the purposes of this Act, the sum of Ten billion pesos (P10,000,000,000) is hereby appropriated out of any available funds in the National Treasury not otherwise appropriated.\nDisbursement of said Ten billion pesos (P10,000,000,000) shall be programmed as follows:\n(a) From the approval of this Act to December 31, 1993, the sum of Six billion five hundred million pesos (P6,500,000,000), at least Five billion pesos (P5,000,000,000) of which shall be for resettlement and livelihood projects and One billion five hundred million pesos (P1,500,000,000) shall be vital for infrastructure;\n(b) For the year 1994, the sum of Two billion pesos (P2,000,000,000); and\n(c) For the year 1995, the sum of One billion five hundred million pesos (P1,500,000,000).\nProvided, however, that undisbursed amounts at the end of any year shall be carried over to the succeeding year."}},{"id":"PH-H6119-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Creation of Mt. Pinatubo Assistance, Resettlement and Development Commission. – For purposes of this Act, there is hereby created the Mt. Pinatubo Assistance, Resettlement and Development Commission, hereinafter referred to as the Commission.\nIt shall be organized within thirty (30) days after the approval of this Act. It shall have a term of six (6) years from its organization: provided, that the President by proclamation may, within six (6) months prior to the expiration of the term, extend the period of its existence once for not more than three (3) years.\nSuch amount as may be necessary for the initial organization and/or operational expenses of the Commission shall be set aside from the amount herein appropriated.\nFor administrative purposes, the Commission shall be attached to the Office of the President."}},{"id":"PH-H6119-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Powers of the Commission. – To carry out its objectives under this Act, the Commission shall have the following powers:\n(a) To formulate policies and plans for the relief, rehabilitation, resettlement and livelihood services as well as infrastructure support in harmony with the other plans and policies of the National Government and other agencies such as the Bases Conversion and Development Authority;\n(b) To make a determination of the areas where the lahar flow may be diverted to spare communities and/or minimize damage to lives, habitation, infrastructure, agricultural and other resources;\n(c) To prioritize and coordinate the implementation of the various programs and projects of the Commission;\n(d) To sue and be sued in its name, and to adopt, alter and use a seal;\n(e) To enter into, make, perform and carry out contracts of every class, kind and description which are necessary to the realization of its purposes with any person, firm or corporation, private or public, and, upon consultation with the President, with foreign government entities, subject to the usual accounting and auditing requirements;\n(f) To apply for, receive and accept grants and donation of funds, equipment, materials and services needed for the development of the area, within and outside the Philippines;\n(g) To monitor the progress of the relief, rehabilitation, resettlement and livelihood as well as infrastructure support programs and projects;\n(h) To coordinate and consult with concerned national and local officials, both elective and appointive, as well as accredited non-government organizations (NGOs) in the prioritization and prosecution of the programs and projects;\n(i) To call upon any department, office, instrumentality, agency, or any political subdivision of the Government for such assistance as may be necessary for the attainment of the objectives of the Commission; and\n(j) In general, to perform such other powers as may be necessary and proper to carry out the purposes of this Act."}},{"id":"PH-H6119-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Composition of the Commission. – The Commission shall be composed of eleven (11) members to be appointed by the President: four (4) coming from the Cabinet, three (3) from the private sector, the Executive Director, and the Chairmen of the Bases Conversion and Development Authority, Subic Metropolitan Bay Authority, and Clark Development Authority as ex officio members. The members of the Commission shall serve for six (6) years unless sooner removed for cause. The President shall designate from among the members of the Commission the Chairman thereof."}},{"id":"PH-H6119-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Executive Director; Powers and Responsibilities. – The President shall appoint a professional manager as the Executive Director of the Commission, who shall serve as the chief executive officer. He shall serve until such time as the Commission is dissolved or unless sooner removed from office by the President. He shall have the following powers and functions:\n(a) Execute and administer the policies and decisions of the Commission;\n(b) Directly coordinate the activities of all agencies and instrumentalities of the Government in the planning and implementation of projects on site;\n(c) Monitor the programs and projects and evaluate the effects of execution by these agencies and instrumentalities and submit to the Commission periodic reports relating to the development of the areas; and\n(d) Perform such other functions as are inherently necessary in the operational management of the areas developed in accordance with the policies and guidelines formulated by the Commission."}},{"id":"PH-H6119-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Implementation. – The survey, construction or repair and reconstruction of damaged, destroyed, required or alternate government infrastructure and facilities shall be undertaken by the implementing government agencies concerned by public bidding, administration or through negotiated contracts, subject to the usual accounting and auditing rules and regulations. However, in case of negotiated contracts as of the approval of this Act can be awarded such contracts. Whenever suitable, labor-based technology shall be used in the implementation of the programs and projects.\nWith respect to aid, relief, resettlement, rehabilitation and livelihood services to individual beneficiaries, the Commission may seek the assistance and use the services of the Philippine National Red Cross and all other relief agencies and volunteer organizations with proven record in providing relief work.\nThe departments and agencies of the Government involved with the aid, relief, resettlement, rehabilitation and livelihood services as well as infrastructure support shall continue to be the implementing agencies of the Commission and shall submit to the Commission every quarter the data and information required under Section 12 hereof."}},{"id":"PH-H6119-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Preference for Local Residents. – Residents in the affected areas, especially the victims, shall be given preference in hiring or employment in the construction or repair and reconstruction of damaged or destroyed government infrastructure and facilities and other labor requirements in all other projects."}},{"id":"PH-H6119-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Report to Congress. – The Commission shall submit to the President and to Congress a detailed quarterly report on the funds allocated indicating the amount released, obligated and disbursed for:\n(a) Aid, relief, resettlement, rehabilitation and livelihood services, including the list of names of approved individual beneficiaries and contractors and the evaluation of the effectiveness of the delivery systems of such services; and\n(b) Construction or repair and reconstruction of infrastructure projects, including the list of contractors and projects being financed, and the accomplishments for the expended appropriations, including the percentage of completion.\nThe Commission shall cause to be disseminated in the community the list of beneficiaries and contractors mentioned above.\nThe Commission shall also submit as part of the quarterly report a list of local and foreign donors and the nature of their donations."}},{"id":"PH-H6119-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Joint Congressional Oversight Committee. – There is hereby created the Joint Congressional Oversight Committee to monitor the implementation of this Act. The Committee shall be composed of five (5) senators and five (5) representatives to be appointed by the Senate President and the Speaker of the House of Representatives, respectively. The Oversight Committee shall be co-chaired by a senator and a representative designated by the Senate President and the Speaker of the House of Representatives, respectively.\nThe mandate given to the Joint Congressional Oversight Committee under this Act shall be without prejudice to the performance of the duties and functions by the respective existing oversight committees of the Senate and the House of Representatives."}},{"id":"PH-H6119-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Prohibition Against Running for Public Office. – An officer or employee of the Commission shall not be qualified to be a candidate for public office for the election next following his resignation or separation. This prohibition does not apply to the Chairman and members of the Commission."}},{"id":"PH-H6119-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Punishable Acts. – Any person who takes advantage of the calamity by buying and selling relief goods which he knows or should be known to him as intended for donation, or misrepresenting the source of relief goods, or submitting or approving a false or inflated claim shall be prosecuted and, upon conviction, suffer a fine of not less than Fifty thousand pesos (P50,000) nor more than One million pesos (P1,000,000) or imprisonment for not less than six (6) years nor more than fifteen (15) years, or both, at the discretion of the court, including perpetual disqualification from public office if he is a public officer, and confiscation or forfeiture in favor of the Government of any prohibited interest. If the offender is a corporation, partnership or association, or other juridical entity, the penalty shall be imposed upon the officer or officers of the corporation, partnership, association, or entity responsible for the violation and, if such is an alien, he shall, in addition to the penalties prescribed, be deported without further proceedings after service of sentence."}},{"id":"PH-H6119-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Rules and Regulations. – The President shall, within ten (10) days after the organization of the Commission, issue the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H6119-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Transfer of Operating Funds, Records, Assets and Liabilities. – All operating funds, records, properties, other assets and liabilities of the Task Force on the Rehabilitation of Areas Affected by the Eruption of Mt. Pinatubo created under Presidential Memorandum Order No. 369, Series of 1991, as amended, are hereby transferred to the Commission."}},{"id":"PH-H6119-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Separability Clause. – If any provision of this Act shall be held unconstitutional or invalid, the other provisions not otherwise affected shall remain in full force and effect."}},{"id":"PH-H6119-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Repealing Clause. – Any law, decree, or rules and regulations which are inconsistent with or contrary to the provisions of this Act are hereby amended or repealed."}},{"id":"PH-H6119-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Effectivity Clause. – This Act shall take effect upon its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p87"};
  FT["PH-H6120"] = {"id":"PH-H6120","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7638_1992.html","fetchedAt":"2026-10-06","articleCount":28,"structureMode":"ARTICLE","title":{"zh":"《部电力》1992年法","en":"Department of Energy Act of 1992","orig":"Department of Energy Act of 1992 An Act Creating the Department of Energy Rationalizing the organization and Functions of Government Agencies Related to Energy and for Other Purposes"},"level":"law","status":"active","topics":["energy"],"docNumber":"Republic Act No. 7638","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-12-09","completenessNote":"全文，共 28 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7638_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6120-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. – This Act shall be known as the \" Department of Energy Act of 1992. \""}},{"id":"PH-H6120-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. – It is hereby declared the policy of the State: (a) to ensure a continuous, adequate, and economic supply of energy with the end in view of ultimately achieving self-reliance in the country’s energy requirements through the integrated and intensive exploration, production, management, and development of the country’s indigenous energy resources, and through the judicious conservation, renewal and efficient utilization of energy to keep pace with the country’s growth and economic development and taking into consideration the active participation of the private sector in the various areas of energy resource development; and (b) to rationalize, integrate, and coordinate the various programs of the Government towards self-sufficiency and enhanced productivity in power and energy without sacrificing ecological concerns."}},{"id":"PH-H6120-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. – (a) \"Energy projects\" shall mean activities or projects relative to the exploration, extraction, production, importation-exportation, processing, transportation, marketing, distribution, utilization, conservation, stockpiling, or storage of all forms of energy products and resources.\n(b) \"Board\" shall mean the Energy Regulatory Board."}},{"id":"PH-H6120-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Department of Energy. – To carry out the above-declared policy, there is hereby created the Department of Energy, hereinafter referred to as the Department, which shall prepare, integrate, coordinate, supervise, and control all plans, programs, projects, and activities of the Government relative to energy exploration, development, utilization, distribution, and conservation."}},{"id":"PH-H6120-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Powers and Functions. – The Department shall have the following powers and functions:\n(a) Formulate policies for the planning and implementation of a comprehensive program for the efficient supply and economical use of energy consistent with the approved national economic plan and with the policies on environmental protection and conservation and maintenance of ecological balance, and provide a mechanism for the integration, rationalization, and coordination of the various energy programs of the Government;\n(b) Develop and update the existing Philippine energy program which shall provide for an integrated and comprehensive exploration, development, utilization, distribution and conservation of energy resources, with preferential bias for environment-friendly, indigenous, and low-cost sources of energy. The program shall include a policy direction towards the privatization of government agencies related to energy, deregulation of the power and energy industry and reduction of dependency on oil-fired plants. Said program shall be updated within nine (9) months from its completion and not later than the fifteenth day of September every year thereafter;\n(c) Establish and administer programs for the exploration, transportation, marketing, distribution, utilization, conservation, stockpiling and storage of energy resources of all forms, whether conventional or nonconventional;\n(d) Exercise supervision and control over all government activities relative to energy projects in order to attain the goals embodied in Section 2 of this Act;\n(e) Regulate private sector activities as provided under existing laws: Provided, That the Department shall endeavor to provide for an environment conducive to free and active private sector participation and investment in all energy activities.\nAt the end of four (4) years from the effectivity of this Act, the Department shall, upon approval of the President, institute the programs and timetable of deregulation of appropriate energy projects and activities of the energy industry;\n(f) Assess the requirements of, determine priorities for, provide direction to, and disseminate information resulting from energy research and development programs for the optimal development of various forms of energy production and utilization technologies;\n(g) Formulate and implement programs, including a system of providing incentives and penalties, for the judicious and efficient use of energy in all energy-consuming sectors of the economy;\n(h) Formulate and implement a program for the accelerated development of nonconventional energy systems and the promotion and commercialization on its applications;\n(i) Devise ways and means of giving direct benefits to the province, city, or municipality, especially the community and people affected, and equitable and preferential benefit to the region that hosts the energy resource and/or the energy-generating facility: Provided, however, That the other provinces, cities, municipalities, or regions shall not be deprived of their energy requirements;\n(j) Encourage private enterprises engaged in energy projects, including corporations, cooperatives, and similar collective organizations, to broaden the base of their ownership and thereby encourage the widest public ownership of energy-oriented corporations;\n(k) Formulate such rules and regulations as may be necessary to implement the objectives of this Act; and\n(l) Exercise such other power as may be necessary or incidental to attain the objectives of this Act.\nTHE DEPARTMENT PROPER"}},{"id":"PH-H6120-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Composition. – The Department Proper shall be composed of the Office of the Secretary and the Offices of the Undersecretaries and Assistant Secretaries, and the bureaus and services of the Department."}},{"id":"PH-H6120-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Office of the Secretary. – The Office of the Secretary shall consist of the Secretary and his immediate staff."}},{"id":"PH-H6120-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"CHAPTER II"},"text":{"en":"The Secretary. – The Secretary shall be appointed by the President, subject to confirmation by the Commission on Appointments.\nNo officer, external auditor, accountant, or legal counsel of any private company or enterprises primarily engaged in the energy industry shall be eligible for appointment as Secretary within two (2) years from his retirement, resignation, or separation therefrom.\nThe Secretary shall have the following functions:\n(a) Establish policies and standards for the effective, efficient, and economical operation of the Department in accordance with the programs of the Government;\n(b) Exercise direct supervision and control over all functions and activities of the Department, as well as all its officers and personnel;\n(c) Devise a program of international information on the geological and contractual conditions obtaining in the Philippines for oil and gas exploration in order to advance the industry;\n(d) Create regional offices and such other service units and divisions as may be necessary;\n(e) Create regional or separate grids as may be necessary or beneficial; and\n(f) Perform such other functions as may be necessary or proper to attain the objectives of this Act.\nThe Secretary shall be an ex officio member of the Board of the National Economic and Development Authority (NEDA). He shall also be a member of the NEDA’s Committee on Infrastructure (INFRACOM) and the Investment Coordinating Council (ICC). For this purpose, the provisions of Executive Order No. 292, otherwise known as the Administrative Code of 1987, relative to the creation and organization of the NEDA and its component agencies and offices are hereby modified accordingly.\nThe Secretary shall also be a member of the body authorized to formulate, prescribe, or amend the necessary guidelines for the financing, construction, operation, and maintenance of the infrastructure projects by the private sector, under Republic Act No. 6957, otherwise known as the Build-Operate-Transfer Law."}},{"id":"PH-H6120-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"CHAPTER II"},"text":{"en":"The Undersecretaries. – The Secretary shall be assisted by three (3) Undersecretaries who shall be appointed by the President upon the recommendation of the Secretary. They shall have the powers and functions as provided for in Section 10, Chapter 2, Book IV of the Administrative Code of 1987.\nThe Office of the Undersecretaries shall consist of the Undersecretaries and their respective immediate staff."}},{"id":"PH-H6120-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Assistant Secretaries. – The Secretary shall also be assisted by three (3) Assistant Secretaries, one (1) for operations, one (1) for policy and programs, and another for administrative services. The Assistant Secretaries shall be appointed by the President upon the recommendation of the Secretary."}},{"id":"PH-H6120-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Qualifications. – No person shall be appointed Secretary, Undersecretary, or Assistant Secretary of the Department unless he is a citizen and resident of the Philippines, of good moral character, and of proven competence in any of the following fields: (a) energy or utility economics; (b) public administration; (c) physical or engineering sciences; (d) management; or (e) law."}},{"id":"PH-H6120-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Bureaus and Services. – Subject to the power of the Secretary, with the approval of the President, to reorganize, restructure, and redefine the functions of the bureaus and services for the effective discharge of the powers and functions of the Department under this Act, the Department shall have the following bureaus and services: Energy Resource Development Bureau; Energy Utilization Management Bureau; Energy Industry Administration Bureau; Energy Planning and Monitoring Bureau; and Administrative Support Services.\nThe bureaus and services shall have the following powers and functions:\n(a) Energy Resource Development Bureau – (1) Assist in the formulation and implementation of policies to develop and increase the domestic supply of local energy resources like fossil fuels, nuclear fuels, and geothermal resources;\n(2) Assist in the formulation of sectoral programs and plans relative to the exploration, development, and extraction of local energy resources and implement, monitor, and regularly review said program;\n(3) Conduct energy research and studies in support of the abovementioned activities;\n(4) Provide consultative training and advisory services to practitioners and institution sin the areas of regulated activities; and\n(5) Assist in the formulation of financial and fiscal policies, rules, guidelines, and requirements relative to the operation of service contractors and implement and enforce said policies.\n(b) Energy Utilization Management Bureau – (1) Assist in the formulation and implementation of policies for the efficient and economical transformation, conversion, processing, refining, marketing, distribution, transportation, and storage of petroleum, coal, natural gas, geothermal, and other nonconventional energy resources such as wind, solar, biomass, and others; and ensure their efficient and judicious utilization;\n(2) Monitor sectoral energy consumption and conduct energy audits, technical training, energy management advisory services, and technology application on efficient energy utilization;\n(3) Develop, promote and commercialize applications of biomass, solar, small hydro, wind, wood, and charcoal and other nonconventional energy systems including new and more efficient and economical transformation, conversion, processing, refining, marketing, distribution, transportation, and storage technologies for conventional energy resources;\n(4) Assist in the formulation of an integrated rural energy program to effectively address the needs of rural development and environmental programs and implement, monitor, and regularly review said program;\n(5) Assist in the formulation of an operational plan for the allocation of oil, fuel, and energy sources in the event of the declaration of critically low-energy supply provided for in Section 25 of this Act;\n(6) Provide information on energy technology and develop middle and long-term energy technology development in cooperation with the Department of Science and Technology;\n(7) Monitor the implementation of energy projects in coordination with the Department of Environment and Natural Resources to ensure compliance with prescribed environmental standards;\n(8) Recommend appropriate courses of action to resolve major issues may impede energy project siting or result in adverse environmental impact;\n(9) Require industrial, commercial, and transport establishments to collect or cause the collection of waste oil for recycling as fuel or lubricating oil; and\n(10) Develop and implement a continuing energy conservation program designed to optimize energy utilization, including a nationwide information campaign on energy conservation.\n(c) Energy Industry Administration Bureau – (1) Assist in the formulation of regulatory policies to encourage and guide the operations of both government and private entities involved in energy resource supply activities such as independent power production, electricity distribution, as well as the importation, exportation, stockpiling, storage, shipping, transportation, refinement, processing, marketing, and distribution of all forms of energy products, whether conventional or nonconventional;\n(2) Draw up plans to cope with contingencies of energy supply interruptions; and\n(3) Assist in the formulation of financial and fiscal policies, rules, guidelines, and requirements relative to the operations of entities involved in the supply of energy resources such as oil companies, petroleum product dealers, coal importing and distributing companies, natural gas distribution entities, independent power producers, and all other entities involved in conventional supply activities and implement and enforce said policies.\n(d) Energy Planning and Monitoring Bureau – (1) Assist in the development and updating of an integrated energy plan for the short, medium, and long-term periods to provide a comprehensive assessment on the demand scenarios and supply options as well as the impacts of energy policies on the economy, poverty, and environment;\n(2) Develop and maintain a centralized, comprehensive, and unified data and information program to ensure the efficient collection, evaluation, analysis, and dissemination of data and information on reserves of various energy resources, production, demand, development technology, and related economic and statistical information which are required for policy formulation, program planning and implementation;\n(3) Supervise, coordinate, and integrate the formulation, monitoring, and review of programs and plans for energy supply development such as power development, local energy resource development and production, and energy importation;\n(4) Regularly review and analyze past and current patterns of energy consumption vis-à-vis growth and development performance of the various economic sectors to evaluate current and foreseeable trends in energy demand; and conduct energy supply-demand balancing studies to define energy supply and utilization strategies, estimate the resources required, and assess the energy program’s economic, environmental, social, and political impact;\n(5) Assume the incorporation of national environmental goals in the formulation and implementation of energy programs, and to advance the goals of restoring, protecting, and enhancing environmental quality, and assuring public health and safety; and\n(6) Conduct studies on international energy issues that have a direct impact on negotiations involving energy resources and technologies.\n(e) Administrative Support Services – The Administrative Support Services shall be composed of the Office of the Legal counsel and the Financial and Management Services.\nThe Office of the Legal Counsel shall be responsible for providing legal advice and services on all policies, programs, and operational matters of the Department. It shall provide legal counseling services in cases where the Department is a party and shall also handle administrative cases against any personnel of the Department and submit recommendations pertaining to them.\nThe Financial and Management Services, which shall consist of the Human Resources Management Division, General Services Divisions, and the Financial Management Division, shall be responsible for providing the Department with services relative to personnel information, records, supplies, equipment, collection and disbursements, security, and custodial works. It shall also be responsible for providing the Department with staff advice and assistance on budgetary, financial, and management improvement matters.\nATTACHED AGENCIES AND CORPORATIONS"}},{"id":"PH-H6120-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Attached Agencies and Corporations. – The Philippine National Oil Company (PNOC), the National Power Corporation (NPC), and the National Electrification Administration (NEA) are hereby placed under the supervision of the Department, but shall continue to perform their respective functions insofar as they are not inconsistent with this Act. Their annual budget shall be submitted to Congress for approval. The Secretary shall, in a concurrent capacity, be the ex officio chairman of the respective boards of the PNOC, NPC, and NEA, unless otherwise directed by the President: Provided, That in no case shall the Secretary be the chief executive officer or chief operating officer of the said agencies or their subsidiaries, any law to the contrary notwithstanding.\nTo this end, Section 6, paragraph (3) of Presidential Decree No. 927 and Section 8 of Presidential Decree No. 334, providing that the Chairman of the PNOC shall be the president and chief executive officer thereof, are accordingly repealed.\nThe Secretary may recommend to the President the reorganization of the boards of directors of the PNOC, NPC, and NEA."}},{"id":"PH-H6120-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Council of Energy Advisers. – A council of advisers on energy affairs consisting of five (5) members and appointed from the industry, labor, and consumer sectors shall advise the President on the overall energy program, especially on private sector initiatives and proposals.\nThe President shall convene the council within thirty (30) days upon approval of this Act.\nTRANSITORY PROVISIONS"}},{"id":"PH-H6120-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Abolition of Agencies. – The Office of Energy Affairs and the Energy Coordinating Council are hereby abolished subject to Section 17 of this Act."}},{"id":"PH-H6120-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Transfer of Powers and Functions. – The powers and functions of the Energy Coordinating Council and the Office of Energy Affairs are hereby transferred to the Department.\nThe foregoing transfer of powers and functions shall include all applicable funds and appropriations, records, equipment, property, and personnel as may be necessary.\nThe same shall apply to agencies and government units which have not been abolished but whose functions have been transferred to the Department.\nAs the successor-in-office of the Office of Energy Affairs, the Department shall administer the activities of the Technology Transfer for Energy Management (TTEM) project. For this purpose, the Department shall continue the utilization of all funds, monies, interests, reflows, and properties outstanding and accruing from the TTEM project upon its termination for the following purposes:\n(a) To finance energy conservation projects of industrial and commercial establishments;\n(b) To monitor implemented sub-projects and document the actual energy savings generated; and\n(c) To disseminate information on implemented sub-projects through case studies and seminars/workshops so as to encourage replication by other industrial and commercial establishments."}},{"id":"PH-H6120-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Transfer of Rights, Assets, and Liabilities. – The Department shall, by virtue of this Act, be subrogated to all the rights and assume all the liabilities of the Office of Energy Affairs, the Energy Coordinating Council, and all other agencies, or government units whose functions and powers have been transferred to the Department, and all their funds, records, property, assets, equipment, and such personnel as necessary, including unexpended appropriations and/or allocations. All contracts and liabilities of said offices, agencies, and government units are hereby transferred to and assumed by the Department and shall be acted upon in accordance with the Auditing Code and other pertinent laws, rules, and regulations: Provided, That the officers and employees of said offices, agencies, and government units shall continue in a holdover capacity until such time as the new officers and employees of the Department shall have been duly appointed pursuant to the provisions of this Act."}},{"id":"PH-H6120-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Rationalization or Transfer of Functions of Attached or Related Agencies. – The non-price regulatory jurisdiction, power and functions of the Energy Regulatory Board as provided for in Section 3 of Executive Order No. 172 are hereby transferred to the Department.\nThe foregoing transfer of power and functions shall include all applicable funds and appropriations, equipment, property, and such personnel as may be necessary: Provided, That only each amount of funds and appropriations of the Board as well as only the personnel thereof which are completely or primarily involved in the exercise by said board of its non-price regulatory powers and functions shall be affected by such transfer.\nThe power of the NPC to determine, fix and prescribe the rates being charged to its customers under Section 4 of Republic Act No. 6395, as amended, as well as the power of electric cooperatives to fix rates under Section 16 (o), Chapter II of Presidential Decree No. 269, as amended, are hereby transferred to the Energy Regulatory Board. The Board shall exercise its new powers only after due notice and hearing and under the same nature provided for under Executive Order No. 172."}},{"id":"PH-H6120-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Structure and Staffing Pattern. – The organizational framework and staffing pattern of the Department shall be prescribed and approved by the Secretary within sixty (60) days after the approval of this Act and the authorized positions created therein shall be filled by regular appointments by the President or the Secretary as the case may be: Provided, That, in the filling of positions created, preference shall be given to the personnel of the Office of Energy Affairs, the Energy Coordinating Council, and the Energy Regulatory Board: Provided, however, That if such individuals possess the same qualifications, seniority shall be given priority."}},{"id":"PH-H6120-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Separation from Service. – Employees separated from the service as a result of this reorganization shall, within six (6) months from their separation from the service, receive the retirement benefits to which they may be entitled under existing laws, rules, and regulations.\nAPPROPRIATIONS"}},{"id":"PH-H6120-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Appropriations. – Such sums as may be necessary for the implementation of this Act shall be taken from the current fiscal year appropriations of the Office of Energy Affairs, the Office of Energy Affairs’ special fund created under Section 8 of Presidential Decree No. 910, and such amounts as the President of the Philippines may allocate from other resources in accordance with law: Provided, That the total amount shall not exceed Three hundred million pesos (P 300,000,000). Thereafter, the amount needed for the operation and maintenance of the Department shall be included in the annual General Appropriations Act.\nSubject to existing rules and regulations, the funds and monies collected or which the otherwise come into the possession of the Department and its bureaus from fees, surcharges, fines, and penalties which the Department and its bureaus may impose and collect under this Act, as well as an amount to be determined at the beginning of every calendar year representing twenty percent (20%) of the outstanding balance of the funds and monies forming part of the special fund under Section 8 of Presidential Decree No. 910, shall be disbursed for expenses necessary for the effective discharge of the powers and functions of the Department under this Act.\nMISCELLANEOUS PROVISIONS"}},{"id":"PH-H6120-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Disclosure and Divestment of Financial Interest. – Before assumption of office, the Secretary of the Department, the Undersecretaries, and the Assistant Secretaries shall submit to the Civil Service Commission a list of all companies, partnerships, or business enterprises, including nonprofit organizations, in which he or any immediate member of their families within the second degree of consanguinity or affinity have any form of financial interests or employment relationship, including consultancy: Provided, however, That all other forms of employment relationship held by the heads of the offices of the Department shall be immediately upon assumption of office.\nWithin thirty (30) days thereafter, complete divestments of financial interests in any institution, firm, or company which fall under the supervisory or regulatory jurisdiction of the Department shall be made: Provided, however, That in cases where confirmation of appointment by the Commission on Appointments is required, the divestment mandated herein shall be complied with within thirty (30) days after such confirmation.\nThe divestment prescribed in the preceding paragraph shall likewise apply to the member of the immediate family within the second degree of consanguinity having interest in any institution or activity which falls under the regulatory jurisdiction or supervision of the Department and the attached agencies."}},{"id":"PH-H6120-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Relationship with Other Government Departments. – The Department and its priority projects shall enjoy preferential treatment to the exploration, development, exploitation, and extraction of petroleum, coal, and other geothermal resources, and in the matter of providing technical support necessary for the establishment of power-generating plants.\nUpon request of the Department or any of its bureaus, all government agencies with functions relative to the approval of the projects of the Department or its duly authorized and endorsed entities, whether government or private, shall act upon and resolve the matter within ten (10) calendar days. Toward this end, the Secretary, with the approval of the President, may establish an interagency secretariat for the purpose of expediting the approval of said projects."}},{"id":"PH-H6120-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Visitorial Powers. – The Secretary of the Department or his representative shall have visitorial and examining authority over nongovernment entities with contracts for the exploration, development, or utilization of the natural resources for energy purposes in order to determine the share of the Government in the revenue or product thereof, and to ascertain all funds collectible and products due the Government, and that all such funds collectible and products due the Government have actually been collected or delivered.\nDuring such examination, the nongovernment entity concerned shall produce all the reports, records, books of accounts, and other papers that may be required.\nThe refusal by any such nongovernment entity to allow an examination of its books of accounts and pertinent records or its concealment of any material information concerning its financial status shall be a breach of its contract with the Government and shall constitute a legal ground for the cancellation thereof."}},{"id":"PH-H6120-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Contingency Powers. – In time of critically low-energy supply or imminent danger thereof, the President may, upon the determination and recommendation of the Secretary, issue a declaration of the same. Thereafter, the Secretary is hereby authorized to implement the fuel and energy allocation plan provided in Section 12 (b) (5) of this Act, and to formulate other measures for the conservation of energy including, but not limited to, power or fuel rationing, load curtailments, and restrictions on the use of government vehicles and resources."}},{"id":"PH-H6120-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Repealing Clause. – All laws, presidential decrees, executive orders, and rules and regulations, or parts thereof, inconsistent with the provisions of this Act are hereby repealed or modified accordingly.\nHowever, in no case are the provisions of Republic Act No. 6969 repealed, amended, or modified by the provisions of this Act."}},{"id":"PH-H6120-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Separability Clause. – If, for any reason, any section or provision of this Act is held unconstitutional or invalid, the other sections or provisions hereof shall not be affected thereby."}},{"id":"PH-H6120-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Effectivity Clause. – This Act shall take effect after its complete publication in at least two (2) national newspapers of general circulation.\nApproved: December 9, 1992"}}],"pack":"ph-p87"};
  FT["PH-H6121"] = {"id":"PH-H6121","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7639_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"规定从石油价格稳定基金中支付菲律宾共和国国家政府对国家电力公司资本股的部分认购款，为此修订经修正的第1956号总统令的法案","en":"An Act Providing for the Payment in Part of the Subscription of the National Government of the Republic of the Philippines to the Capital Stock of the National Power Corporation Out of the Oil Price Stabilization Fund, Amending for the Purpose Presidential Decree No. 1956, as Amended","orig":"An Act Providing for the Payment in Part of the Subscription of the National Government of the Republic of the Philippines to the Capital Stock of the National Power Corporation Out of the Oil Price Stabilization Fund, Amending for the Purpose Presidential Decree No. 1956, as Amended"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 7639","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-12-09","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7639_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6121-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The subscription of the Government of the Republic of the Philippines to the capital stock of the National Power Corporation, as provided for in Republic Act No. 6395, otherwise known as the Revised Charter of the National Power Corporation, as amended by Presidential Decree Nos. 758, 1360, and 1443, shall be paid in part out of the Oil Price Stabilization Fund in the amount of Three billion pesos (P 3,000,000,000) in accordance with Section 2 of this Act."}},{"id":"PH-H6121-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 8 of Presidential Decree No. 1956, as amended by Executive Order No. 137, is hereby further amended to read as follows:\n\"SEC. 8. There is hereby created a Trust Account in the books of accounts of the Office of Energy Affairs to be designated as the Oil Price Stabilization Fund (OPSF) for the purpose of minimizing frequent price changes brought about by the exchange rate adjustments and/or changes in world market prices of crude oil and imported petroleum products. The Oil Price Stabilization Fund (OPSF) may be sourced from any of the following:\n\"(a) Any increase in the tax collection as a result of the lifting of tax exemptions of government corporations, as may be determined by the Department of Finance in consultation with the Energy Regulatory Board;\n\"(b) Any additional amount to be imposed on petroleum products to augment the resources of the Fund through an appropriate order that may be issued by the Energy Regulatory Board requiring payment of persons or companies engaged in the business of importing, manufacturing and/or marketing petroleum products;\n\"(c) Any resulting peso cost differentials in case the actual peso costs paid by oil companies in the importation of crude oil and petroleum products is less than the peso costs computed using the reference foreign exchange rate as fixed by the Energy Regulatory Board.\n\"The Fund herein created shall be used for the following:\n\"(1) To reimburse the oil companies for cost increases in crude oil and imported petroleum products resulting from exchange rate adjustment and/or from the increase in world market prices of crude oil;\n\"(2) To reimburse the oil companies for possible cost underrecovery incurred as a result of the reduction of domestic prices of petroleum products. The magnitude of the underrecovery, if any, shall be determined by the Department of Finance. Cost underrecovery shall include the following:\n\"(i) Reduction in oil company take ads directed by the Energy Regulatory Board without the corresponding reduction in the landed cost of oil inventories in the possession of the oil companies at the time of the price change;\n\"(ii) Reduction in internal specific taxes as a result of the foregoing government-mandated price reductions; and \"(3) To cover the payment in part of the subscription of the Government of the Republic of the Philippines to the capital stock of the National Power Corporation in the amount of Three billion pesos (P 3,000,000,000). Said amount shall be released to the National Power Corporation upon the effectivity of this Act: Provided, That such amount shall be released only if, on the said date, the OPSF terminal balance shall not be less than Three billion pesos (P 3,000,000,000), as certified by the Office of Energy Affairs: Provided, further, That the National Power Corporation shall utilize the said payments on its capital stock to finance its capital expenditures for energy projects only.\n\"The Oil Price Stabilization Fund (OPSF) shall be administered by the Office of Energy Affairs.\""}},{"id":"PH-H6121-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All laws inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6121-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its publication in two (2) national newspapers of general circulation."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Payment in Part of the Subscription of the National Government of the Republic of the Philippines to the Capital Stock of the National Power Corporation Out of the Oil Price Stabilization Fund, Amending for the Purpose Presidential Decree No. 1956, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6122"] = {"id":"PH-H6122","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7640_1992.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"组建立法与行政发展咨询委员会的法案","en":"An Act Constituting the Legislative-Executive Development Advisory Council","orig":"An Act Constituting the Legislative-Executive Development Advisory Council"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7640","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-12-09","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7640_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6122-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy. – It is the policy of the State to formulate after consultations with appropriate public agencies, the private sector, and local government units socioeconomic development programs taking into account the requirements of conservation and ecology and in accordance with its constitutional mandate to promote a more equitable distribution of opportunities, income, and wealth; a sustained increase in the amount of goods and services produced by the nation for the benefit of the people; an expanding productivity as the key to raising the quality of life for all, especially the under privileged.\nThe State shall promote industrialization and full employment based on sound agricultural development and agrarian reform, through industries that make full and efficient use of human and natural resources, and which are competitive in both domestic and foreign markets. However, the State shall protect Filipino enterprises against unfair foreign competition and trade practices.\nThe Legislative-Executive Development Advisory Council shall constitute an effective advisory and consultative mechanism to ensure consistency in coordinating executive development planning and congressional budgeting."}},{"id":"PH-H6122-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Legislative-Executive Development Advisory Council. – Pursuant to the foregoing policy, there is hereby constituted a consultative and advisory body to be known as the Legislative-Executive Development Advisory Council, hereinafter referred to as the Council. It shall be composed of twenty (20) members with the President as Chairman and the following as members: the Vice President, the President of the Senate, the Speaker of the House of Representatives, seven (7) members of the Cabinet to be designated by the President, three (3) members of the House of Representatives to be designated by the Speaker of the House of Representatives at least one (1) of whom shall come from the dominant minority party, and the following to be appointed by the President: a representative of the local government units, a representative of the youth, and a representative of the private sector from any or a combination of the following: business, cooperatives, agriculture, and labor.\nMembership in the Council of the members of the legislature shall be an extension of their legislative functions. Membership in the Council of the members of the Cabinet shall be in an ex officio capacity.\nThe Chairman and members of the Council who are government officials shall serve in the Council without any additional emoluments, allowances, or pay, by virtue of and in connection with the positions they have been elected to or appointed to, as the case may be.\nThe Council may form its own subcommittees as may be needed and may call on any government agency or resource persons for assistance."}},{"id":"PH-H6122-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Functions of the Council. – The Council shall serve as a consultative and advisory body to the President as the head of the national economic and planning agency for further consultations and advice on certain programs and policies essential to the realization of the goals of the national economy with the following functions:\na) determine and recommend socioeconomic development goals in pursuance of established policies which shall guide the formulation and implementation of the national development plan;\nb) provide policy advice to the President on vital issues affecting the socioeconomic development of the country;\nc) direct the study of measures to ensure that the regional development plans and programs are integrated into the national development plan;\nd) receive, and in appropriate cases, require reports on, and study measures to improve, the implementation of official development assistance from multilateral and bilateral entities;\ne) assess effectiveness of implementation of the national development plan;\nf) integrate environmental concepts, principles and practices into the national development plan for a balanced and cohesive approach to national development;\ng) review the relationship of the legislative agenda to the national development plan to ensure the integration of both;\nh) study and recommend to the President and to Congress sources of revenue as well as measures to reduce unnecessary expenditures to the end that the resources of the Government will be used to the optimum."}},{"id":"PH-H6122-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Secretariat. – The Council shall have the National Economic and Development Authority secretariat as the principal secretariat in providing staff support to the Council, assisted by personnel from the Presidential Management Staff and the economic planning staff of both the Senate and the House of Representatives."}},{"id":"PH-H6122-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Meetings of the Council. – The Council shall meet at least once every quarter, but may be convened by its Chairman to such special meetings as may be necessary. The members of the Council shall be duly notified of any meeting in advance. The first meeting of the Council shall take place within one (1) month from the effectivity of this Act, at a time and place to be designated by the Chairman."}},{"id":"PH-H6122-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Priority Concerns. – The Council shall give special attention to measures which will:\na) involve concerned private sector, relevant non-government groups and people's organizations in the processes of economic planning by national agencies and by regional, provincial, and other local development councils, as well as in monitoring the implementation of development projects.\nb) bring about effective integration of the priority development programs and projects proposed by regional, provincial and other local development councils into the national development plan, within the constraints of the national budget;\nc) accelerate the study and formulation of projects and programs, which will answer priority needs of the people for livelihood and social services, and which may be funded from national revenues and/or grants and concessional loans from external sources;\nd) hasten the utilization of grants and concessional loans for priority development projects and programs, while also improving the efficiency of project implementation; and\ne) recommend measures that would strengthen mechanism for monitoring the implementation of development projects and programs, and for promoting efficiency of execution and timeliness of completion."}},{"id":"PH-H6122-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The Council shall render reports after every meeting to all Senators and Congressmen who are not members of the Council, particularly the progress and action taken on priority concerns embodied in Section 6 hereof."}},{"id":"PH-H6122-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Implementing Rules and Regulations. – Within sixty (60) days from the approval of this Act, the Council shall promulgate all the necessary rules and regulations to carry out the provisions of this Act."}},{"id":"PH-H6122-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Appropriations. – The amount of Three million pesos (P3,000,000.00) is hereby authorized out of the funds of the National Treasury not otherwise appropriated for the operating and capital expenditures of the Council for the Fiscal Year 1993. Thereafter, the necessary appropriations shall be provided in the Annual General Appropriations Act."}},{"id":"PH-H6122-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Separability Clause. – In case any provision hereof is declared unconstitutional, the other provisions not so declared and affected shall remain in force and effect."}},{"id":"PH-H6122-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Repealing Clause. – All laws and executive orders which are inconsistent with the provisions of this Act are hereby repealed or amended accordingly."}},{"id":"PH-H6122-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Constituting the Legislative-Executive Development Advisory Council","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6123"] = {"id":"PH-H6123","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7641_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"对《劳动就业法典》的修改","en":"An Act Amending Article 287 of Presidential Decree No. 442, as amended, otherwise known as the Labor Code of the Philippines, by Providing for Retirement Pay to Qualified Private Sector Employees in the Absence of any Retirement Plan in the Establishment","orig":"An Act Amending Article 287 of Presidential Decree No. 442, as amended, otherwise known as the Labor Code of the Philippines, by Providing for Retirement Pay to Qualified Private Sector Employees in the Absence of any Retirement Plan in the Establishment"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 7641","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-12-09","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7641_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6123-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Article 287 of Presidential Decree No. 442, as amended, otherwise known as the Labor Code of the Philippines, is hereby amended to read as follows:\n\"Art. 287. Retirement . – Any employee may be retired upon reaching the retirement age established in the collective bargaining agreement or other applicable employment contract.\n\"In case of retirement, the employee shall be entitled to receive such retirement benefits as he may have earned under existing laws and any collective bargaining agreement and other agreements: Provided , however , That an employee's retirement benefits under any collective bargaining and other agreements shall not be less than those provided herein.\n\"In the absence of a retirement plan or agreement providing for retirement benefits of employees in the establishment, an employee upon reaching the age of sixty (60) years or more, but not beyond sixty-five (65) years which is hereby declared the compulsory retirement age, who has served at least five (5) years in the said establishment, may retire and shall be entitled to retirement pay equivalent to at least one-half (1/2) month salary for every year of service, a fraction of at least six (6) months being considered as one whole year.\n\"Unless the parties provide for broader inclusions, the term one-half (1/2) month salary shall mean fifteen (15) days plus one-twelfth (1/12) of the 13th month pay and the cash equivalent of not more than five (5) days of service incentive leaves.\n\"Retail, service and agricultural establishments or operations employing not more than (10) employees or workers are exempted from the coverage of this provision.\n\"Violation of this provision is hereby declared unlawful and subject to the penal provisions provided under Article 288 of this Code.\""}},{"id":"PH-H6123-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Nothing in this Act shall deprive any employee of benefits to which he may be entitled under existing laws or company policies or practices."}},{"id":"PH-H6123-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in at least two (2) national newspapers of general circulation, whichever comes earlier."}}],"pack":"ph-p87"};
  FT["PH-H6124"] = {"id":"PH-H6124","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7642_1992.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"加重逃税处罚，为此修订经修正的国家国内税收法典相关条款的法案","en":"An Act Increasing the Penalties for Tax Evasion, Amending for this Purpose the Pertinent Sections of the National Internal Revenue Code, as Amended","orig":"An Act Increasing the Penalties for Tax Evasion, Amending for this Purpose the Pertinent Sections of the National Internal Revenue Code, as Amended"},"level":"law","status":"active","topics":["tax","criminal"],"docNumber":"Republic Act No. 7642","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-12-28","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7642_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6124-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"A new paragraph (c) is hereby added to Section 252 of the National Internal Revenue Code, as amended, to read as follows:\n\"(c) The fines to be imposed for any violation of the provisions of this Code shall not be lower than the fines imposed herein or twice the amount of taxes, interests, and surcharges due from the taxpayer, whichever is higher.\""}},{"id":"PH-H6124-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 253 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Sec. 253. Attempt to evade or defeat tax. - Any person who willfully attempts in any manner to evade or defeat any tax imposed under this Code or the payment thereof shall, in addition to other penalties provided by law, upon conviction thereof, be fined not less than Thirty thousand pesos but not more than One hundred thousand pesos and suffer imprisonment of not less than two years but not more than four years.\""}},{"id":"PH-H6124-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The second paragraph of Section 254 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Any person who attempts to make it appear for any reason that he or another has in fact filed a return or statement, or actually files a return or statement and subsequently withdraws the same return or statement after securing the official receiving seal or stamp of receipt of an internal revenue office wherein the same was actually filed shall, upon conviction therefor, be fined not less than Ten thousand pesos but not more than Twenty thousand pesos and suffer imprisonment of not less than one year but not more than three years.\""}},{"id":"PH-H6124-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 255 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Sec. 255. Penal liability of corporations. - Any corporation, association, or general co-partnership liable for any of the acts or omissions penalized under this Code, in addition to the penalties imposed herein upon the responsible corporate officers, partners, or employees, shall, upon conviction for each act or omission, be fined not less than Fifty thousand pesos but not more than One hundred thousand pesos.\""}},{"id":"PH-H6124-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 256 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Sec. 256. Penal liability for making false entries, records, or reports. - (a) Any independent certified public accountant engaged to examine and audit books of accounts of taxpayers under subparagraph (a) of Section 232 and any person under his direction who:\n\"(1) Willfully falsifies any report or statement bearing on any examination or audit, or renders a report, including exhibits, statements, schedules, or other forms of accountancy work which has not been verified by him personally or under his supervision or by a member of his firm or by a member of his staff in accordance with sound auditing practices; or \"(2) Certifies financial statements of a business enterprise containing an essential misstatement of facts or omission in respect of the transactions, taxable income, deduction, and exemption of his client; or \"(b) Any person who:\n\"(1) Not being an independent certified public accountant according to subparagraph (B) of Section 232, examines and audits books of accounts of taxpayers; or \"(2) Offers to sign and certify financial statements without audit; or \"(3) Offers any taxpayer the use of accounting bookkeeping records for internal revenue purposes not in conformity with the requirements prescribed in this Code or regulations promulgated thereunder; or \"(4) Knowingly makes any false entry or enters any false or fictitious name in the books of accounts or records mentioned in the preceding paragraph; or \"(5) Keeps two or more sets of such records or books of accounts; or \"(6) In any way commits an act or omission, in violation of the provisions of this section; or \"(7) Fails to keep the books of accounts or records mentioned in Section 232 in a native language, English, or Spanish, or to make a true and complete translation as required in Section 234 of this Code, or whose books of accounts or records kept in a native language, English, or Spanish, and found to be at material variance with books or records kept by him in another language, shall, upon conviction for each act or omission, be punished by a fine of not less than Thirty thousand pesos but not more than Fifty thousand pesos and suffer imprisonment of not less than two years but not more than six years.\""}},{"id":"PH-H6124-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section 257 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Sec. 257. Unlawful pursuit of business. - Any person who carries on any business for which a private tax is imposed without paying the tax as required by law shall, upon conviction for each act or omission, be fined not less than Five thousand pesos but not more than Twenty thousand pesos and suffer imprisonment of not less than six months but not more than two years: Provided, That, in the case of a person engaged in the business of distilling, rectifying, repacking, compounding, or manufacturing any article subject to excise tax, he shall, upon conviction for each act or omission, be fined not less than Thirty thousand pesos but not more than Fifty thousand pesos and suffer imprisonment of not less than two years but not more than four years.\""}},{"id":"PH-H6124-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section 258 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Sec. 258. Illegal collection of foreign payments. - Any person who knowingly undertakes the collection of foreign payments as provided under Section 60 of this Code without having obtained a license therefor, or without complying with its implementing regulations, shall, upon conviction for each act or omission, be fined not less than Twenty thousand pesos but not more than Fifty thousand pesos and suffer imprisonment of not less than one year but not more than two years.\""}},{"id":"PH-H6124-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section 262 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Sec. 262. Unlawful possession or removal of articles subject to excise tax without payment of the tax. - Any person who owns and/or is found in possession of imported articles subject to excise tax, the tax on which has not been paid in accordance with law, or any person who owns and/or is found in possession of imported tax-exempt articles other than those to whom they are legally issued shall be punished by:\n\"(1) A fine of not less than One thousand pesos but not more than Two thousand pesos and suffer imprisonment of not less than sixty days but not more than one hundred days if the appraised value, to be determined in the manner prescribed in the Tariff and Customs Code, including duties and taxes, of the articles does not exceed One thousand pesos;\n\"(2) A fine of not less than Ten thousand pesos but not more than Twenty thousand pesos and suffer imprisonment of not less than two years but not more than four years in the appraised value, to be determined in the manner prescribed in the Tariff and Customs Code, including duties and taxes, of the articles exceed One thousand pesos but does not exceed Fifty thousand pesos;\n\"(3) A fine of not less than Thirty thousand pesos but not more than Sixty thousand pesos and suffer imprisonment of not less than four years but not more than six years if the appraised value, to be determined in the manner prescribed in the Tariff and Customs Code, including the duties and taxes, of the articles is more than Fifty thousand pesos but does not exceed One hundred fifty thousand pesos; or \"(4) A fine of not less than Fifty thousand pesos but not more than One hundred thousand pesos and suffer imprisonment of not less than ten years but not more than twelve years if the appraised value, to be determined in the manner prescribed in the Tariff and Customs Code, including duties and taxes, of the articles exceed One hundred fifty thousand pesos.\n\"Any person who is found in possession of locally manufactured article subject to excise tax, the tax on which has not been paid in accordance with law, or any person who is found in possession of such articles which are exempt from excise tax other than those to whom the same is lawfully issued shall be punished with a fine of not less than ten times the amount of excise tax due on the articles found but less than Five hundred pesos and suffer imprisonment of not less than two years but not more than four years.\n\"Any manufacturer, owner, or person in charge of any article subject to excise tax who removes or allows or causes the unlawful removal of any such articles from the place of production or bonded warehouse, upon which the articles subject to excise tax has not been paid at the time in manner required, and any person who knowingly aids or abets in the removal of such articles as aforesaid, or conceals the same after illegal removal shall, for the first offense, be punished with a fine of not less than ten times the amount of excise tax due on the articles but not less than one year. but not more than two years.\n\"The mere unexplained possession of articles subject to excise tax, the tax on which has not been paid in accordance with law, shall be punished under this section.\""}},{"id":"PH-H6124-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Paragraph (a) Section 263 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"(a) Any person who, being required under Section 238 to issue receipts or sales or commercial invoices, fails or refuses to issue such receipts or invoices, issues receipts or invoices that do not truly reflect and/or contain all the information required to be shown therein or uses multiple or double receipts or invoices shall, upon conviction for each act or omission, be fined not less than One thousand pesos, but not more than Fifty thousand pesos and suffer imprisonment of not less than two years but not more than four years.\""}},{"id":"PH-H6124-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section 264 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Sec. 264. Offenses relating to stamps. - Any person who commits any of the acts enumerated hereunder shall, upon conviction thereof, be fined not less than Twenty thousand pesos but not more than Fifty thousand pesos and suffer imprisonment of not less than four years but not more than eight years:\n\"(1) Makes, imports, sells, or uses, or possesses without express authority from the Commissioner any die for printing or making stamps, labels, tags, or playing cards;\n\"(2) Erases the cancellation marks of any stamp previously used or alters the written figures or letters or cancellation marks on internal revenue stamps;\n\"(3) Possesses false, counterfeit, restored, or altered stamps, labels, or tags or causes the commission of any such offense by another;\n\"(4) Sells or offers for sale any box or package containing articles subject to excise tax with false, spurious, or counterfeit stamps or labels or sells from any such fraudulent box, package, or container as aforesaid; or \"(5) Gives away or accepts from another or sells, buys, or uses containers on which the stamps are not completely destroyed.\""}},{"id":"PH-H6124-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section 265 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Sec. 265. Failure to obey summons. - Any person who, being duly summoned to appear to testify, or to appear and produce books of accounts, records, memoranda, or other papers, or to furnish information as required under the pertinent provisions of this Code, neglects to appear or to produce such books of accounts, records, memoranda, or other papers, or to furnish such information, shall, upon conviction, be fined not less than Five thousand pesos but not more than Ten thousand pesos and suffer imprisonment of not less than one year but not more than two years.\""}},{"id":"PH-H6124-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section 268 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Sec. 268. Violations committed by government enforcement officers. - Every official, agent, or employee of the Bureau of Internal Revenue or any other agency of the Government charged with the enforcement of the provisions of this Code who is guilty of any of the offenses hereinbelow specified shall, upon conviction for each act or omission, be fined not less than Fifty thousand pesos but not more than One hundred thousand pesos and suffer imprisonment of not less than ten years but not more than fifteen years and shall likewise suffer an additional penalty of perpetual disqualification to hold public office, to vote, and to participate in any public election:\n\"(1) Those guilty of extortion or willful oppression through the use of his office;\n\"(2) Those who knowingly demand other or greater sums than are authorized by law or receive any fees, compensation, or reward, except as by law prescribed, for the performance of any duty;\n\"(3) Those who willfully neglect to give receipts, as by law required, for any sums collected in the performance of duty or who willfully neglect to perform any other duties enjoined by law;\n\"(4) Those who conspire or collude with another or others to defraud the revenues or otherwise violate the provisions of this Code;\n\"(5) Those who by neglect or design permit the violation of the law by any other person;\n\"(6) Those who make or sign any false entry or entities in any books, or make or sign any false certificate or return;\n\"(7) Those who allow or conspire or collude with another to allow the unauthorized retrieval, withdrawal, or recall of any return, statement, or declaration after the same has been officially received by the Bureau of Internal Revenue;\n\"(8) Those who, having knowledge or information of a violation of this Code or of any fraud committed on the revenues collectible by the Bureau of Internal Revenue, fail to report such knowledge or information to their superior officer or to report as otherwise required by law; and \"(9) Those who, without the authority of law, demand or accept or attempt to collect, directly or indirectly, as payment or otherwise any sum of money or other thing of value for the compromise, adjustment, or settlement of any charge or complaint for any violation or alleged violation of this Code.\""}},{"id":"PH-H6124-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"There is hereby created the Congressional Oversight Committee composed of the Chairmen of the Committees on Ways and Means of both Houses of Congress as Co-Chairman and three other members each from said committees. The Oversight Committee shall convene within two years after the approval of this Act to review its implementation and recommend amendments thereto."}},{"id":"PH-H6124-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The Secretary of Finance shall, upon the recommendation of the Commissioner of Internal Revenue, promulgate the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H6124-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"All laws, decrees, orders, rules and regulations, and other issuances inconsistent with the provisions of this Act are hereby repealed or amended accordingly."}},{"id":"PH-H6124-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Penalties for Tax Evasion, Amending for this Purpose the Pertinent Sections of the National Internal Revenue Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6125"] = {"id":"PH-H6125","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7643_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授权国内税收局长要求按月缴纳增值税，并允许地方政府单位分享增值税收入，为此修订《国家国内税收法典》若干条款的法案","en":"An Act to Empower the Commissioner of Internal Revenue to Require the Payment of the Value-Added Tax Every Month and to Allow Local Government Units to Share in VAT Revenue, Amending for this Purpose Certain Sections of the National Internal Revenue Code","orig":"An Act to Empower the Commissioner of Internal Revenue to Require the Payment of the Value-Added Tax Every Month and to Allow Local Government Units to Share in VAT Revenue, Amending for this Purpose Certain Sections of the National Internal Revenue Code"},"level":"law","status":"active","topics":["tax","administrative"],"docNumber":"Republic Act No. 7643","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-12-28","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7643_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6125-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 110 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Sec. 110. Return and payment of value-added tax. (a) In general. - Every person liable to pay the value-added tax imposed under this title shall file a quarterly return of the amount of his gross sales or receipts within twenty (20) days following the close of each taxable quarter prescribed for each taxpayer: Provided , That any person whose registration has been cancelled in accordance with Section 107 hereof, shall file a return and pay the tax due thereon within twenty (20) days from the date of cancellation of registration. Only one consolidated return shall be filed by the taxpayer for his principal place of business of head office and all branches.\n\"(b) Where to file the return and pay the tax. - The return shall be filed with and the tax paid to a bank duly accredited by the Commissioner located within the revenue district where the taxpayer is registered or required to register: Provided , however , That VAT-registered persons shall pay the value-added tax on a monthly basis: Provided, further, That in case no accredited bank is located within the revenue district, the return shall be filed with and the tax paid to the revenue district officer, collection agent, or duly authorized treasurer of the municipality where the place of business is located in the order mentioned.\""}},{"id":"PH-H6125-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Sec. 282 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Sec. 282. Disposition of national internal revenue. - National internal revenue collected and not applied as hereinabove provided or otherwise specially disposed of by law shall accrue to the National Treasury and shall be available for the general purposes of the Government, with the exception of the amounts set apart by way of allotment as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991.\n\"In addition to the internal revenue allotment as provided for in the preceding paragraph, fifty percent (50%) of the national taxes collected under Sections 100, 102, 112, 113, and 114 of this Code in excess of the increase in collections for the immediately preceding year shall be distributed as follows: (a) Twenty percent (20%) shall accrue to the city or municipality where such taxes are collected and shall be allocated in accordance with Section 150 of Republic Act No. 7160, otherwise known as the Local Government Code of 1991; and (b) Eighty percent (80%) shall accrue to the National Government.\""}},{"id":"PH-H6125-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All laws, decrees, orders, rules and regulations, and other issuances inconsistent with this Act are hereby repealed or amended accordingly."}},{"id":"PH-H6125-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect after fifteen (15) days following its complete publication in the Official Gazette or in at least two (2) national newspapers of general circulation, whichever comes earlier."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Empower the Commissioner of Internal Revenue to Require the Payment of the Value-Added Tax Every Month and to Allow Local Government Units to Share in VAT Revenue, Amending for this Purpose Certain Sections of the National Internal Revenue Code","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6126"] = {"id":"PH-H6126","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7644_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"进一步延长某些住宅单元的租金管制期，为此修订Batas Pambansa Blg. 877（即《规定某些住宅单元租金稳定与管制并为其他目的》，经修正）的法案","en":"An Act Further Extending the Rent Control Period for Certain Residential Units, Amending thereby Batas Pambansa Blg. 877, Entitled \"An Act Providing for the Stabilization and Regulation of Rentals of Certain Residential Units and for Other Purposes,\" as Amended","orig":"An Act Further Extending the Rent Control Period for Certain Residential Units, Amending thereby Batas Pambansa Blg. 877, Entitled \"An Act Providing for the Stabilization and Regulation of Rentals of Certain Residential Units and for Other Purposes,\" as Amended"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7644","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-12-28","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7644_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6126-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The effectivity of Batas Pambansa Blg. 877, entitled: \"An Act Providing for the Stabilization and Regulation of Rentals of Certain Residential Units and for Other Purposes,\" as amended, is hereby extended for five (5) years from January 1, 1993 to December 31, 1997: Provided, That the allowable maximum increase for the five-year period shall not be more than the rates herein provided: period maximum increase January 1, 1993 - December 31, 1993 Twenty percent (20%) January 1, 1994 - December 31, 1994 Twenty percent (20%) January 1, 1995 - December 31, 1995 Twenty percent (20%) January 1, 1996 - December 31, 1996 Twenty percent (20%) January 1, 1997 - December 31, 1997 Twenty percent (20%) Provided , further , That the basis for the maximum increase herein authorized for the five-year period shall be the actual monthly rental as of December 31, 1992: Provided, finally, That the increases authorized herein shall be cumulative and compounded."}},{"id":"PH-H6126-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect on January 1, 1993 following its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Further Extending the Rent Control Period for Certain Residential Units, Amending thereby Batas Pambansa Blg. 877, Entitled \"An Act Providing for the Stabilization and Regulation of Rentals of Certain Residential Units and for Other Purposes,\" as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6127"] = {"id":"PH-H6127","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7646_1993.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"授权国内税收局长规定大型纳税人缴纳国内税收的地点，为此修订经修正的《国家国内税收法典》若干条款","en":"An Act Authorizing the Commissioner of Internal Revenue to Prescribe the Place for Payment of Internal Revenue Taxes By Large Taxpayers, Amending for This Purpose Certain Provisions of the National Internal Revenue Code, as Amended","orig":"An Act Authorizing the Commissioner of Internal Revenue to Prescribe the Place for Payment of Internal Revenue Taxes By Large Taxpayers, Amending for This Purpose Certain Provisions of the National Internal Revenue Code, as Amended"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 7646","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-02-24","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7646_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6127-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Paragraph (j) of Section 4 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n“(j) The manner in which internal revenue taxes such as income tax including withholding tax, estate and donor’s taxes, value-added tax, other percentage taxes, excise taxes, and documentary stamp taxes shall be paid through the collection officers of the Bureau of Internal Revenue or through duly accredited banks which are hereby deputized to receive payments of such taxes and the returns, papers, and statements that may be filed by the taxpayers in connection with the payment of the tax: Provided, however, That, notwithstanding the other provisions of this Code prescribing the place of filing of returns and payment of taxes, the Commissioner may by regulations require that the tax returns, papers, and statements and taxes of large taxpayers be filed and paid, respectively, through collection officers or through duly accredited banks: Provided, further, That the Commissioner can exercise this power within six (6) years from the approval of this Act or the completion of its comprehensive computerization program, whichever comes earlier: Provided, finally, That separate venues for the Luzon, Visayas, and Mindanao areas may be designated for the filing of tax returns and payment of taxes by said large taxpayers.\n\"For purposes of this section, 'large taxpayer' means a taxpayer who satisfies any of the following criteria:\n\"(1) Value-added tax (VAT) - Business establishment with VAT paid or payable of at least one hundred thousand pesos for any quarter of the preceding taxable year;\n\"(2) Excise tax - Business establishment with excise tax paid or payable of at least one million pesos for the preceding taxable year;\n\"(3) Corporate income tax - Business establishment with annual income tax paid or payable of at least one million pesos for the preceding taxable year; and \"(4) Withholding tax - Business establishment with withholding tax payment or remittance of at least one million pesos for the preceding taxable year.\n\" Provided, however, That the Secretary of Finance, upon recommendation of the Commissioner of Internal Revenue, may modify or add to the above criteria for determining a large taxpayer after considering such factors as inflation, volume of business, wage and employment levels, and similar economic factors.\n\"The penalties prescribed under Section 248 of this Code shall be imposed on any violation of the regulation issued by the Commissioner of Internal Revenue prescribing the place of filing of returns and payments of taxes by large taxpayers.\""}},{"id":"PH-H6127-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Paragraph (b) of Section 5 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"(b) Receipts for payment made. - It shall be the duty of the Commissioner or his duly authorized representative or a duly accredited bank to whom any payment of any taxes is made under the provisions of this Code to acknowledge the payment of such tax, expressing the amount paid and the particular account for which such payment was made in a form and manner prescribed therefor by the Commissioner.\""}},{"id":"PH-H6127-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 204(1) of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 204. Authority of the Commissioner to compromise, abate, and refund / credit taxes. - The Commissioner may - \"(1) Compromise the payment of any internal revenue tax when- \"(a) A reasonable doubt as to the validity of the claim against the taxpayer exists; or \"(b) The financial position of the taxpayer demonstrates a clear inability to pay the assessed tax: Provided, however, That final assessments issued against large taxpayers as defined under Section 4 of this Code shall not be compromised for less than fifty percent (50%). Any such compromise involving said taxpayers lower than fifty percent (50%) shall be subject to the approval of the Secretary of Finance.\""}},{"id":"PH-H6127-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Finance, upon recommendation of the Commissioner of Internal Revenue, shall promulgate the necessary rules and regulations for the effective implementation of the provisions of this Act."}},{"id":"PH-H6127-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All laws, decrees, orders, rules and regulations, and other issuances inconsistent with this Act are hereby repealed or amended accordingly."}},{"id":"PH-H6127-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, February 24, 1993."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Commissioner of Internal Revenue to Prescribe the Place for Payment of Internal Revenue Taxes By Large Taxpayers, Amending for This Purpose Certain Provisions of the National Internal Revenue Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6128"] = {"id":"PH-H6128","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7647_1993.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"规定棉兰老穆斯林自治区区长、副区长与区立法议会议员定期选举日期并为其他目的法案","en":"An Act Providing for the Date of Regular Elections for Regional Governor, Regional Vice-Governor and Members of the Regional Legislative Assembly of the Autonomous Region in Muslim Mindanao and for Other Purposes","orig":"An Act Providing for the Date of Regular Elections for Regional Governor, Regional Vice-Governor and Members of the Regional Legislative Assembly of the Autonomous Region in Muslim Mindanao and for Other Purposes"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 7647","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-03-05","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7647_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6128-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The regular elections for regional governor, regional vice-governor, and members of the Regional Legislative Assembly for the Autonomous Region in Muslim Mindanao, shall be held on the second Monday after the Muslim month of Ramadhan immediately preceding the end of the term of office of such officials except the second regular election in 1993 which shall be held on the 25th of March, 1993: Provided, That if no candidate shall have been duly elected and qualified on March 31, 1993, the incumbent regional governor and vice-governor shall continue in office in a holdover capacity until their successors shall have been duly elected and qualified, subject to Article VIII, Section 11 of Republic Act No. 6734: Provided, further, That while acting in a holdover capacity, the regional governor and vice-governor shall not disburse public funds except for personnel and administrative matters, make appointments, including promotions, transfer and/or assignments of personnel and shall be subject to all the restrictions and/or prohibitions mandated by Section 261 of the Omnibus Election Code more particularly, but not limited to, paragraphs (g); (h); (k); (m); (o); (r); (u); (v); (w); and (x), of said section."}},{"id":"PH-H6128-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"(a.) Board of Canvassers. — There shall be a board of canvassers in the Autonomous Region in Muslim Mindanao for the purpose of the elections in the Autonomous Region in Muslim Mindanao and a provincial board of canvassers in each province therein as follows:\n1. Regional Board of Canvassers. The regional board of canvassers shall canvass the certificates of canvass, which shall be accompanied by the statement of votes by precincts, prepared and submitted to it by the provincial board of canvassers for the positions of regional governor and vice-governor and on the basis thereof, proclaim as elected, the candidates for regional governor and vice-governor who obtained the highest number of votes in the entire autonomous region.\nThe regional board of canvassers shall be composed of a ranking lawyer of the Commission on Elections (COMELEC) as chairman, a representative likewise of equivalent rank in the Department of Justice as vice-chairman, in the Department of Education, Culture and Sports as member-secretary. However, in case of non-availability, absence or disqualification due to relationship or incapacity for any cause, the COMELEC shall appoint other representatives from the different agencies of the government, as substitutes.\n2. The Provincial Board of Canvassers. The provincial board of canvassers shall canvass the election returns, copy for the provincial board of canvassers or any other authentic copy of such election returns, and on the basis thereof, proclaim as elected, the first three (3) candidates for assemblyman of the Autonomous Region in Muslim Mindanao receiving the highest number of votes in each legislative district of the province.\nThe provincial board of canvassers shall be composed of the provincial election supervisor of the province concerned or a ranking lawyer of the COMELEC as chairman, the provincial prosecutor as vice-chairman, and the division superintendent of schools as member-secretary. However, in case of non-availability, absence or disqualification due to relationship or incapacity for any cause, the COMELEC shall appoint such lawyers of the Commission as substitutes.\nb. Number of Copies of Election Returns, Their Preparation and Their Distribution. — The board of election inspectors shall prepare in writing the election returns in their respective polling places, or in any other place authorized by the COMELEC, in the number of copies herein provided and in the form to be prescribed by the COMELEC.\nThe copies of the election returns shall be distributed as follows:\ni. The first copy shall be delivered to the provincial board of canvassers; ii. The second copy, to the regional board of canvassers; iii. The third copy, to the COMELEC; iv. The fourth copy shall be deposited inside the compartment of the ballot box for valid ballots;\nv. The fifth copy, to be known as advance election returns, shall be delivered to the city or municipal treasurer who, in the presence of the election registrar or his authorized representative, shall immediately and publicly open the same and post the votes therein in an election tally board sufficiently large to enable the public to read them, built on a public place preferably within the immediate vicinity of the city hall or municipal building; and vi. The sixth and seventh copies, to be known as party copies, shall be furnished the duly authorized representatives in the municipalities concerned of the two (2) major political parties or coalition/alliance of parties presenting candidates in this election."}},{"id":"PH-H6128-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Pre-proclamation Cases. — No pre-proclamation cases shall be allowed on matters relating to the preparation, transmission, receipt, custody, and appreciation of election returns or the certificates of canvass, as the case may be. However, this does not preclude the authority of the appropriate canvassing body, motu proprio or upon written complaint of an interested person to correct manifest errors in the certificate of canvass or election returns before it.\nQuestions affecting the composition or proceeding of the board of canvassers may be initiated in the board or directly with the COMELEC in accordance with Section 19 of Republic Act No. 7166.\nAny objection on the election returns before the provincial board of canvassers or certificate of canvass before the regional board of canvassers, shall be specifically noted in the minutes of their respective proceedings."}},{"id":"PH-H6128-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Separability Clause . — If for any reason, any section or provision of this Act or any portion thereof, or the application of such section, provision or portion is declared invalid or unconstitutional, the remainder thereof shall not be affected by such declaration."}},{"id":"PH-H6128-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Applicability of the Omnibus Election Code of the Philippines and other Statutes — All provisions of the Omnibus Election Code, Republic Act Nos. 6646 and 7166 and other election laws not inconsistent with the provisions of this Act shall apply to the election herein provided.\nThe COMELEC shall promulgate the necessary rules and regulations for the implementation of this Act."}},{"id":"PH-H6128-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Transitory Provisions. — All prior acts, resolutions, and issuances of the COMELEC made in connection with the second regular election in the Autonomous Region in Muslim Mindanao under this Act, including the deputation of government agencies and instrumentalities, registration of voters, appointment of election officials and boards of election inspectors, and filing of certificates of candidacy, are hereby confirmed valid and subsisting."}},{"id":"PH-H6128-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Effectivity Clause. — This Act shall take effect upon its approval.\nApproved, March 5, 1993."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Date of Regular Elections for Regional Governor, Regional Vice-Governor and Members of the Regional Legislative Assembly of the Autonomous Region in Muslim Mindanao and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6129"] = {"id":"PH-H6129","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7648_1993.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"规定有效应对电力危机所必需且适当的紧急相关措施并为其他目的法案","en":"An Act Prescribing Urgent Related Measures Necessary and Proper to Effectively Address the Electric Power Crisis and for Other Purposes","orig":"An Act Prescribing Urgent Related Measures Necessary and Proper to Effectively Address the Electric Power Crisis and for Other Purposes"},"level":"law","status":"active","topics":["energy"],"docNumber":"Republic Act No. 7648","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-04-05","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7648_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6129-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title . - This Act shall be known as the \"Electric Power Crisis Act of 1993.\""}},{"id":"PH-H6129-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy . - It is hereby declared the policy of the State to adopt adequate and effective measures to address the electric power crisis that has disrupted the country's economic and social life and assumed the nature and magnitude of a public calamity."}},{"id":"PH-H6129-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Negotiated Contracts. - Pursuant to the above declared policy and in the public interest and whenever it is advantageous to the Government, the President may enter into negotiated contracts for the construction, repair, rehabilitation, improvement or maintenance of power plants, projects and facilities, subject to the following requirements:\na. In order to inform competitive contractors, the list of projects to be undertaken under this Act, together with their description, the budgetary estimates involved and other salient features, shall be published in a newspaper of general circulation thirty (30) days after the effectivity of this Act;\nb. Upon perfection of the contract, the terms and conditions of the same, with the name and qualifications of the contractor, shall likewise be published in a newspaper of general circulation two (2) weeks before the signing of the contract;\nc. The contracts shall be awarded only to contractors with:\ni. proven competence and experience in similar projects; ii. competent key personnel and sufficient and reliable equipment; and iii. sound financial capacity; and\nd. All the awarded projects shall be subject to existing government auditing rules and regulations governing negotiated contracts."}},{"id":"PH-H6129-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Return on Rate Base. - Further pursuant to the above-declared policy, the President is hereby authorized, whenever it is necessary for the national welfare and in the public interest, to fix the rate of return on rate base of the National Power Corporation (NAPOCOR) to not more than twelve percentum (12%) of the rate base as defined in Section 4 of Republic Act No. 6395, as amended. Any increase in power rates shall take effect only upon approval of the Energy Regulatory Board (ERB), after due notice and hearing: Provided, That any increase in power rates by the NAPOCOR to its customers within the year 1993 shall not exceed an average of eighteen centavos (P0.18) per kilowatt-hour: Provided, further, That any increase in power rates shall not be passed on to households consuming not more than one hundred (100) kilowatt-hours per month for five (5) years following the effectivity of this Act: Provided, furthermore, That the existing subsidy enjoyed by households consuming less than three hundred (300) kilowatt-hours per month shall continue to be in effect: Provided, finally, That no power rate increase whatsoever shall be imposed by the NAPOCOR in provinces producing geothermal power of not less than one hundred megawatts (100 MW) of actual capacity for one (1) year following the effectivity of this Act.\nWhen the petition appears to be sufficient in form and in substance, the ERB, during the pendency of the case, may issue a provisional authority to increase the power rates, in whole or in part, which increase shall last for a period of sixty (60) days, and may be extended for another sixty (60) days: Provided, That the ERB can issue such provisional authority only during the effectivity of this Act."}},{"id":"PH-H6129-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Reorganization of the National Power Corporation. - The President is hereby empowered to reorganize the NAPOCOR, to make it more effective, innovative, and responsive to the power crisis. For this purpose, the President may abolish or create offices; split, group, or merge positions; transfer functions, equipment, properties, records and personnel; institute drastic cost-cutting measures; and take such other related actions necessary to carry out the purpose herein declared. Nothing in this Section shall result in the diminution of the present salaries and benefits of the personnel of the NAPOCOR: Provided, That any official or employee of the NAPOCOR who may be phased out by reason of the reorganization authorized herein shall be entitled to such benefits as may be determined by the Board of Directors of the NAPOCOR, with the approval of the President.\nThe President may upgrade the compensation of the personnel of the NAPOCOR at rates comparable to those prevailing in privately-owned power utilities to take effect upon approval by Congress of the NAPOCOR's budget for 1994."}},{"id":"PH-H6129-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Subsidy. - The Philippine Amusement and Gaming Corporation (PAGCOR) shall set aside ten percentum (10%) of its annual aggregate gross earnings for the next five (5) years as subsidy to the NAPOCOR: Provided, That such percentage allocation shall be based on gross revenue after deducting the five percentum (5%) franchise tax and the fifty percentum (50%) income share of the National Government."}},{"id":"PH-H6129-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Duration of Grant of Powers. - The authority granted to the President under this Act shall subsist, be valid and effective for a period of one (1) year from the effectivity of this Act, unless sooner withdrawn by a resolution of Congress, without prejudice to rights and benefits that may have been vested, and culpabilities and liabilities that may have been incurred."}},{"id":"PH-H6129-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Oversight Committees. - There is hereby created an Oversight Committee in each House of Congress to be composed of five (5) members each, as may be designated by the Senate President and the Speaker of the House of Representatives, to monitor the implementation of this Act and the exercise of the authority granted thereunder.\nThe Oversight Committees shall submit periodic reports, evaluations and recommendations to the Senate and the House of Representatives."}},{"id":"PH-H6129-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Report to Congress. - The President shall submit a quarterly report to Congress on the implementation of this Act."}},{"id":"PH-H6129-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Separability Clause . - If for any reason any provision of this Act is declared unconstitutional or invalid, other parts or provisions hereof which are not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H6129-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Repealing Clause . - All laws, decrees, orders, rules and regulations, or portions thereof, inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6129-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Effectivity Clause. - This Act shall take effect on the day following its publication in at least two (2) national newspapers of general circulation.\nApproved, April 5, 1993."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Prescribing Urgent Related Measures Necessary and Proper to Effectively Address the Electric Power Crisis and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6130"] = {"id":"PH-H6130","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7649_1993.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"要求政府或其任何政治分区、机关或机构（包括政府拥有或控制的公司）在采购货物时按毛付款额百分之三（3%）、在承包商提供服务时按毛收入百分之六（6%）扣缴增值税的法案","en":"An Act Requiring the Government or Any of Its Political Subdivisions, Instrumentalities or Agencies Including Government-Owned or Controlled Corporations (Goccs) to Deduct and Withhold the Value-Added Tax Due At the Rate of Three Percent (3%) on Gross Payment for the Purchase of Goods and Six Percent (6%) on Gross Receipts for Services Rendered By Contractors","orig":"An Act Requiring the Government or Any of Its Political Subdivisions, Instrumentalities or Agencies Including Government-Owned or Controlled Corporations (Goccs) to Deduct and Withhold the Value-Added Tax Due At the Rate of Three Percent (3%) on Gross Payment for the Purchase of Goods and Six Percent (6%) on Gross Receipts for Services Rendered By Contractors"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 7649","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-04-06","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7649_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6130-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 110 of the National Internal Revenue Code, as amended by Republic Act No. 7643, is hereby further amended by adding a new paragraph (c) thereunder to read as follows:\n\"(c) Withholding of Creditable Value-Added Tax. - The Government or any of its political subdivisions, instrumentalities or agencies, including government-owned or controlled corporations (GOCCs) shall, before making payment on account of its purchase of goods from sellers and services rendered by contractors which are subject to the value-added tax imposed in Sections 100 and 102 of this Code, deduct and withhold the value-added tax due at the rate of three percent (3%) of the gross payment for the purchase of goods and six percent (6%) on gross receipts for services rendered by contractors on every release or installment payment which shall be creditable against the value-added tax liability of the seller or contractor.\n\"The value-added tax withheld under this section shall be remitted within ten (10) days following the end of the month the withholding was made.\""}},{"id":"PH-H6130-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Finance shall, upon the recommendation of the Commissioner of Internal Revenue, promulgate the necessary rules and regulations for the effective implementation of the provisions of this Act."}},{"id":"PH-H6130-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All laws, decrees, orders, rules and regulations, and other issuances inconsistent with this Act are hereby repealed or amended accordingly."}},{"id":"PH-H6130-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in at least two (2) national newspapers of general circulation, whichever comes earlier.\nApproved, April 6, 1993."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Requiring the Government or Any of Its Political Subdivisions, Instrumentalities or Agencies Including Government-Owned or Controlled Corporations (Goccs) to Deduct and Withhold the Value-Added Tax Due At the Rate of Three Percent (3%) on Gross Payment for the Purchase of Goods and Six Percent (6%) on Gross Receipts for Services Rendered By Contractors","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6131"] = {"id":"PH-H6131","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7650_1993.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"废止Section 1404 修改 Sections 1401 1403 关税海关法典","en":"An Act Repealing Section 1404 and Amending Sections 1401 and 1403 of the Tariff and Customs Code of the Philippines, as Amended, Relative to the Physical Examination of Imported Articles","orig":"An Act Repealing Section 1404 and Amending Sections 1401 and 1403 of the Tariff and Customs Code of the Philippines, as Amended, Relative to the Physical Examination of Imported Articles"},"level":"law","status":"active","topics":["tax","trade"],"docNumber":"Republic Act No. 7650","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-04-06","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7650_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6131-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 1401 of the Tariff and Customs Code of the Philippines, as amended, is hereby further amended to read as follows:\n\"Section 1401. Conditions for Examination. - For the protection of government revenue and public interest and to prevent the entry into the country of smuggled or contraband goods, the Commissioner shall, in consultation with the Oversight Committee and subject to the approval of the Secretary of Finance, promulgate the rules and regulations that shall prescribe the procedure in accordance with which examination shall be undertaken on the importation and the required quantity or percentage thereof: Provided, That the imported articles shall in any case be subject to the regular physical examination when:\n\"(1) The government surveyor's seal on the container has been tampered with or broken or the container shows signs of having been opened or having its identity changed;\n\"(2) The container is leaking or damaged;\n\"(3) The number, weight, and nature of packages indicated in the customs entry declaration and supporting documents differ from that in the manifest;\n\"(4) The shipment is covered by alert/hold orders issued pursuant to existing orders;\n\"(5) The importer disagrees with the findings as contained in the government surveyor's report; or \"(6) The articles are imported through air freight where the Commissioner or Collector has knowledge that there is a variance between the declared and true quantity, measurement, weight, and tariff classification.\""}},{"id":"PH-H6131-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 1403 of the Tariff and Customs Code of the Philippines, as amended, is hereby further amended to read as follows:\n\"Section 1403. Duties of Customs Officer Tasked to Examine, Classify, and Appraise Imported Articles. - The customs officer tasked to examine, classify, and appraise imported articles shall determine whether the packages designated for examination and their contents are in accordance with the declaration in the entry, invoice and other pertinent documents and shall make return in such a manner as to indicate whether the articles have been truly and correctly declared in the entry as regard their quantity, measurement, weight, and tariff classification and not imported contrary to law. He shall submit samples to the laboratory for analysis when feasible to do so and when such analysis is necessary for the proper classification, appraisal, and/or admission into the Philippines of imported articles.\n\"Likewise, the customs officer shall determine the unit of quantity in which they are usually bought and sold and appraise the imported articles in accordance with Section 201 of this Code.\n\"Failure on the part of the customs officer to comply with his duties shall subject him to the penalties prescribed under Section 3604 of this Code.\""}},{"id":"PH-H6131-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"An Oversight Committee is hereby created which shall be composed of the Chairmen of the Committees on Ways and Means of the Senate and of the House of Representatives and four (4) additional members from each House to be designated by the Senate President and the Speaker of the House of Representatives, respectively.\nThe Oversight Committee shall monitor and ensure the proper implementation of this Act."}},{"id":"PH-H6131-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Nothing in the preceding section shall authorize the removal of any examiner and appraiser whose functions are merged under the position of customs officer."}},{"id":"PH-H6131-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 1404 of the Tariff and Customs Code of the Philippines, as amended, is hereby repealed."}},{"id":"PH-H6131-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Secretary of Finance shall, upon the recommendation of the Commissioner of Customs, promulgate the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H6131-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"All laws, decrees, orders, rules and regulations, and other issuances inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6131-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, April 6, 1993."}}],"pack":"ph-p87"};
  FT["PH-H6132"] = {"id":"PH-H6132","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7651_1993.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"振兴并强化海关局，为此修订经修正的《菲律宾关税与海关法典》若干条的法案","en":"An Act to Revitalize and Strengthen the Bureau of Customs, Amending for the Purpose Certain Sections of the Tariff and Customs Code of the Philippines, as Amended","orig":"An Act to Revitalize and Strengthen the Bureau of Customs, Amending for the Purpose Certain Sections of the Tariff and Customs Code of the Philippines, as Amended"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 7651","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-06-04","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7651_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6132-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections 1210,1301,1801,1802,2301,2313, 2503,2601, and 3407 of the Tariff and Customs Code, as amended, are hereby further amended to read as follows:\n\"Section 1210. Disposition of Imported Articles Remaining on Vessel after Time for Unlading. — Imported articles remaining on board any vessel after the expiration of the said period for discharge, and not reported for transshipment to another port, may be unladen by the customs authorities and stored at the vessel's expense.\n\"Unless prevented by causes beyond the vessel's control, such as port congestion, strikes, riots or civil commotions, failures of vessel's gear, bad weather, and similar causes, articles so stored shall be entered within thirty (30) days, which shall not be extendible, from the date of discharge of the last package from the vessel or aircraft and shall be claimed within fifteen (15) days, which shall not likewise be extendible from the date of posting of the notice to claim in conspicuous places in the Bureau of Customs. If not entered or not claimed, it shall be disposed of in accordance with the provisions of this Code.\"\n\"Section 1301. Persons Authorized to Make Import Entry. — Imported articles must be entered in the customhouse at the port of entry within thirty (30) days, which shall not be extendible, from the date of discharge of the last package from the vessel or aircraft either (a) by the importer, being holder of the bill of lading, (b) by a duly licensed customs broker acting under authority from a holder of the bill or (c) by a person duly empowered to act as agent or attorney-in-fact for each holder: Provided, That where the entry is filed by a party other than the importer, said importer shall himself be required to declare under oath and under the penalties of falsification or perjury that the declarations and statements contained in the entry are true and correct: Provided, further, That such statements under oath shall constitute prima facie evidence of knowledge and consent of the importer of violation against applicable provisions of this Code when the importation is found to be unlawful.\"\n\"Section 1801. Abandonment, Kinds and Effects of. — An imported article is deemed abandoned under any of the following circumstances:\n\"(a) When the owner, importer or consignee of the imported article expressly signifies in writing to the Collector of Customs his intention to abandon; or \"(b) When the owner, importer, consignee or interested party after due notice, fails to file an entry within thirty (30) days, which shall not be extendible, from the date of discharge of the last package from the vessel or aircraft, or having filed such entry, fails to claim his importation within fifteen (15) days, which shall not likewise be extendible, from the date of posting of the notice to claim such importation.\n\"Any person who abandons an article or who fails to claim his importation as provided for in the preceding paragraph shall be deemed to have renounced all his interests and property rights therein.\"\n\"Section 1802. Abandonment of Imported Articles. — An abandoned article shall ipso facto be deemed the property of the Government and shall be disposed of in accordance with the provisions of this Code.\n\"Nothing in this section shall be construed as relieving the owner or importer from any criminal liability which may arise from any violation of law committed in connection with the importation of the abandoned article.\n\"Any official or employee of the Bureau of Customs or of other government agencies who, having knowledge of the existence of an abandoned article or having control or custody of such abandoned article, fails to report to the Collector within twenty-four (24) hours from the time the article is deemed abandoned, shall be punished with the penalties prescribed in Paragraph 1, Section 3604 of this Code.\"\n\"Section 2301. Warrant for Detention of Property-Cash Bond. — Upon making any seizure, the Collector shall issue a warrant for the detention of the property; and if the owner or importer desires to secure the release of the property for legitimate use, the Collector shall, with the approval of the Commissioner of Customs, surrender it upon the filing of a cash bond, in an amount to be fixed by him, conditioned upon the payment of the appraised value of the article and/or any fine, expenses and costs which may be adjudged in the case: Provided, That such importation shall not be released under any bond when there is aprima facie evidence of fraud in the importation of the article: Provided, further, That articles the importation of which is prohibited by law shall not be released under any circumstance whatsoever: Provided, finally, That nothing in this section shall be construed as relieving the owner or importer from any criminal liability which may arise from any violation of law committed in connection with the importation of the article.\"\n\"Section 2313. Review by Commissioner. — The person aggrieved by the decision or action of the Collector in any matter presented upon protest or by his action in any case of seizure may, within fifteen (15) days after notification in writing by the Collector of his action or decision, file a written notice to the Collector with a copy furnished to the Commissioner of his intention to appeal the action or decision of the Collector to the Commissioner. Thereupon the Collector shall forthwith transmit all the records of the proceedings to the Commissioner, who shall approve, modify or reverse the action or decision of the Collector and take such steps and make such orders as may be necessary to give effect to his decision: Provided, That when an appeal is filed beyond the period herein prescribed, the same shall be deemed dismissed.\n\"If in any seizure proceeding, the Collector renders a decision adverse to the Government, such decision shall be automatically reviewed by the Commissioner and the records of the case elevated within five (5) days from the promulgation of the decision of the Collector. The Commissioner shall render a decision on the automatic appeal within thirty (30) days from receipt of the records of the case. If the Collector's decision is reversed by the Commissioner, the decision of the Commissioner shall be final and executory. However, if the Collector's decision is affirmed, or if within thirty (30) days from receipt of the records of the case by the Commissioner no decision is rendered or the decision involves imported articles whose published value is Five million pesos (₱5,000,000) or more, such decision shall be deemed automatically appealed to the Secretary of Finance and the records of the proceedings shall be elevated within five (5) days from the promulgation of the decision of the Commissioner or of the Collector under appeal, as the case may be: Provided, further, That if the decision of the Commissioner or of the Collector under appeal, as the case may be, is affirmed by the Secretary of Finance, or if within thirty (30) days from receipt of the records of the proceedings by the Secretary of Finance, no decision is rendered, the decision of the Secretary of Finance, or of the Commissioner, or of the Collector under appeal, as the case may be, shall become final and executory.\n\"In any seizure proceeding, the release of imported articles shall not be allowed unless and until a decision of the Collector has been confirmed in writing by the Commissioner of Customs.\"\n\"Section 2503. Undervaluation, Misclassification and Misdeclaration in Entry. — When the dutiable value of the imported articles shall be so declared and entered that the duties, based on the declaration of the importer on the face of the entry, would be less by ten percent (10%) than should be legally collected, or when the imported articles shall be so described and entered that the duties based on the importer's description on the face of the entry would be less by ten percent (10%) than should be legally collected based on the tariff classification, or when the dutiable weight, measurement or quantity of imported articles is found upon examination to exceed by ten percent (10%) or more than the entered weight, measurement or quantity, a surcharge shall be collected from the importer in an amount of not less than the difference between the full duty and the estimated duty based upon the declaration of the importer, nor more than twice of such difference: Provided, That an undervaluation, misdeclaration in weight, measurement or quantity of more than thirty percent (30%) between the value, weight, measurement, or quantity declared in the entry, and the actual value, weight, quantity, or measurement shall constitute a prima facie evidence of fraud penalized under Section 2530 of this Code: Provided, further, That any misdeclared or undeclared imported articles/items found upon examination shall ipso facto be forfeited in favor of the Government to be disposed of pursuant to the provisions of this Code.\n\"When the undervaluation, misdescription, misclassification or misdeclaration in the import entry is intentional, the importer shall be subject to the penal provision under Section 3602 of this Code.\"\n\"Section 2601. Property Subject to Sale. — Property in customs custody shall be subject to sale under the conditions hereinafter provided:\n\"a. Abandoned articles;\n\"b. Articles entered under warehousing entry not withdrawn nor the duties and taxes paid thereon within the period prescribed under Section 1908 of this Code;\n\"c. Seized property, other than contraband, after liability to sale shall have been established by proper administrative or judicial proceedings in conformity with the provisions of this Code; and \"d. Any article subject to a valid lien for customs duties, taxes or other charges collectible by the Bureau of Customs, after the expiration of the period allowed for the satisfaction of the same.\n\"Section 3407. Issuance, Revocation and Suspension of Certificate. — A candidate who has passed the customs brokers' examination shall be entitled to the issuance of a certificate as a customs broker: Provided, That (1) persons who qualified as customs broker in accordance with customs regulations existing before the adoption of this Code; (2) Commissioner of Customs who has acted as ex officio Chairman of the Board of Examiners for Customs Brokers and the Tariff Commissioner who has acted as members of the said board; and (3) Collectors of Customs who have served as such in any of the collection districts for a period of at least five (5) years, who desire to have a certificate issued to them may apply for the issuance of such certificate, upon payment of the fees required under Paragraph (b) of Section Thirty-four hundred and five of this Code.\n\"A customs broker's certificate shall show, among other things, the full name of the registrant, shall have a serial number and shall be signed by all the members of the Board of the Commissioner of Civil Service, and shall bear the official seal of the Board.\n\"A complaint for the suspension or revocation of the certificate of a customs broker shall be filed with the Board of Examiners for Customs Brokers which shall investigate the case and shall submit its findings and recommendations to the Commissioner of Civil Service and shall immediately furnish the respondent customs broker with a copy of his decision.\n\"Any person who files an entry or facilitates the processing or release of any shipment shall be liable for smuggling if the ostensible owner, importer, or consignee and/or the ostensible given address of the owner, importer, or consignee is fictitious and the shipment is found to be unlawful. If the violator is a customs broker, his license shall also be revoked by the Commissioner of Customs.\""}},{"id":"PH-H6132-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 1803 of the Tariff and Customs Code, as amended, is hereby repealed."}},{"id":"PH-H6132-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Finance shall, upon the recommendation of the Commissioner of Customs, promulgate the rules and regulations necessary for the effective implementation of this Act."}},{"id":"PH-H6132-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Separability Clause . — If any part or parts of this Act should, for any reason be held to be invalid or unconstitutional, the remaining parts thereof shall remain in full force and effect."}},{"id":"PH-H6132-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Repealing Clause . — All laws, decrees, executive orders, rules and regulations and other issuances inconsistent with this Act are hereby repealed or amended accordingly."}},{"id":"PH-H6132-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Effectivity Clause. — This Act shall take effect after fifteen (15) days from the date of publication in the Official Gazette or in at least two (2) national newspapers of general circulation, whichever comes earlier.\nApproved, June 4, 1993."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Revitalize and Strengthen the Bureau of Customs, Amending for the Purpose Certain Sections of the Tariff and Customs Code of the Philippines, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6133"] = {"id":"PH-H6133","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7652_1993.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"允许外国投资者长期租赁私人土地的法案","en":"An Act Allowing the Long-Term Lease of Private Lands By Foreign Investors","orig":"An Act Allowing the Long-Term Lease of Private Lands By Foreign Investors"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7652","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-06-04","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7652_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6133-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . — This Act shall be known as the \"Investors' Lease Act.\""}},{"id":"PH-H6133-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy . — It is hereby declared the policy of the State to encourage foreign investments consistent with the constitutional mandate to conserve and develop our own patrimony. Towards this end, the State hereby adopts a flexible and dynamic policy on the granting of long-term lease on private lands to foreign investors for the establishment of industrial estates, factories, assembly or processing plants, agro-industrial enterprises, land development for industrial, or commercial use, tourism, and other similar priority productive endeavors."}},{"id":"PH-H6133-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definitions. — For purposes of this Act, unless the context indicates otherwise, the term:\n1. \"Investing in the Philippines\" shall mean making an equity investment in the Philippines through actual remittance of foreign exchange or transfer of assets, whether in the form of capital goods, patents, formulae, or other technological rights or processes, upon registration with the Securities and Exchange Commission; and\n2. \"Withdrawal of approved investment\" shall mean either: (a) the failure to operate the investment project for any three (3) consecutive years; or (b) outright abandonment of the investment project at any time during the approved lease period: Provided, That failure to pay lease rental for three (3) consecutive months coupled with the failure to operate the investment project for the same period shall be deemed an outright abandonment of the project."}},{"id":"PH-H6133-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Coverage . — Any foreign investor investing in the Philippines shall be allowed to lease private lands in accordance with the laws of the Republic of the Philippines subject to the following conditions:\n1. No lease contract shall be for a period exceeding fifty (50) years, renewable once for a period of not more than twenty- five (25) years;\n2. The leased area shall be used solely for the purpose of the investment upon the mutual agreement of the parties;\n3. The leased premises shall comprise such area as may reasonably be required for the purpose of the investment subject however to the Comprehensive Agrarian Reform Law and the Local Government Code.\nThe leasehold right acquired under long-term lease contracts entered into pursuant to this Act may be sold, transferred, or assigned: Provided, That when the buyer, transferee, or assignee is a foreigner or a foreign-owned enterprise, the conditions and limitations in respect to the use of the leased property as provided for under this Act shall continue to apply."}},{"id":"PH-H6133-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Limitations. —\n1. Foreign individuals, corporations, associations, or partnerships not otherwise investing in the Philippines as defined herein shall continue to be covered by Presidential Decree No. 471 and other existing laws on lease of lands to foreigners.\n2. Withdrawal of the approved investment in the Philippines within the period of the lease agreement entered into under this Act, or use of the leased area for the purpose other than that authorized, shall warrant the ipso facto termination of the lease agreement without prejudice to the right of the lessor to be compensated for the damages he may have suffered thereby.\n3. Any lease agreement under this Act which is renewable at the option of the lessee subject to the same terms and conditions of the original contract shall be interpreted to mean as renewable upon the mutual agreement of the parties.\n4. In addition to the conditions for the renewal of a lease agreement after the period of fifty (50) years as provided herein, the foreign lessee shall show that it has made social and economic contributions to the country.\n5. In the case of tourism projects, lease of private lands by foreign investors qualified herein shall be limited to projects with an investment of not less than Five million ($5M) US dollars, seventy percent (70%) of which shall be infused in said project within three years from the signing of the lease contract."}},{"id":"PH-H6133-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Termination of Lease Contract. — The Secretary of Trade and Industry shall terminate any lease contract entered into under the provisions of this Act, if the investment project is not initiated within three (3) years from the signing of the lease contract."}},{"id":"PH-H6133-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Penal Provision. — Any contract or agreement made or executed in violation of any of the following prohibited acts shall be null and void ab initio and both contracting parties shall be punished by a fine of not less than One hundred thousand pesos (₱100,000) nor more than One million pesos (₱1,000,000), or imprisonment of six (6) months to six (6) years, or both, at the discretion of the court:\n1. Any provision in the lease agreement stipulating a lease period in excess of that provided in paragraph (1) of Section 4;\n2. Use of the leased premises for the purpose contrary to existing laws of the land, public order, public policy, morals, or good customs;\n3. Any agreement or agreements resulting in the lease of land in excess of the area approved by the DTI: Provided, That, where the excess of the totality of the area leased is due to the acts of the lessee, the lessee shall be held solely liable therefor: Provided, further, That, in the case of corporations, associations, or partnerships, the president, manager, director, trustee, or officers responsible for the violation hereof shall bear the criminal liability."}},{"id":"PH-H6133-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Separability Clause . — In case any provision of this Act or the application of such provision is deemed unconstitutional, the remaining provisions of this Act or the application of such provisions shall not be affected thereby."}},{"id":"PH-H6133-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Repealing Clause . — All acts, rules and regulations contrary to or inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6133-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Effectivity Clause. — This Act shall take effect immediately upon its approval.\nApproved, June 4, 1993."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Allowing the Long-Term Lease of Private Lands By Foreign Investors","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6134"] = {"id":"PH-H6134","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7653_1993.html","fetchedAt":"2026-10-06","articleCount":138,"structureMode":"ARTICLE","title":{"zh":"新中央银行法","en":"The New Central Bank Act","orig":"The New Central Bank Act"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 7653","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-06-14","completenessNote":"全文，共 138 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7653_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6134-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy. - The State shall maintain a central monetary authority that shall function and operate as an independent and accountable body corporate in the discharge of its mandated responsibilities concerning money, banking and credit. In line with this policy, and considering its unique functions and responsibilities, the central monetary authority established under this Act, while being a government-owned corporation, shall enjoy fiscal and administrative autonomy."}},{"id":"PH-H6134-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Creation of the Bangko Sentral. - There is hereby established an independent central monetary authority, which shall be a body corporate known as the Bangko Sentral ng Pilipinas, hereafter referred to as the Bangko Sentral.\nThe capital of the Bangko Sentral shall be Fifty billion pesos (P50,000,000,000), to be fully subscribed by the Government of the Republic, hereafter referred to as the Government, Ten billion pesos (P10,000,000,000) of which shall be fully paid for by the Government upon the effectivity of this Act and the balance to be paid for within a period of two (2) years from the effectivity of this Act in such manner and form as the Government, through the Secretary of Finance and the Secretary of Budget and Management, may thereafter determine."}},{"id":"PH-H6134-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Responsibility and Primary Objective. - The Bangko Sentral shall provide policy directions in the areas of money, banking, and credit. It shall have supervision over the operations of banks and exercise such regulatory powers as provided in this Act and other pertinent laws over the operations of finance companies and non-bank financial institutions performing quasi-banking functions, hereafter referred to as quasi-banks, and institutions performing similar functions.\nThe primary objective of the Bangko Sentral is to maintain price stability conducive to a balanced and sustainable growth of the economy. It shall also promote and maintain monetary stability and the convertibility of the peso."}},{"id":"PH-H6134-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Place of Business. - The Bangko Sentral shall have its principal place of business in Metro Manila, but may maintain branches, agencies and correspondents in such other places as the proper conduct of its business may require."}},{"id":"PH-H6134-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Corporate Powers. - The Bangko Sentral is hereby authorized to adopt, alter, and use a corporate seal which shall be judicially noticed; to enter into contracts; to lease or own real and personal property, and to sell or otherwise dispose of the same; to sue and be sued; and otherwise to do and perform any and all things that may be necessary or proper to carry out the purposes of this Act.\nThe Bangko Sentral may acquire and hold such assets and incur such liabilities in connection with its operations authorized by the provisions of this Act, or as are essential to the proper conduct of such operations.\nThe Bangko Sentral may compromise, condone or release, in whole or in part, any claim of or settled liability to the Bangko Sentral, regardless of the amount involved, under such terms and conditions as may be prescribed by the Monetary Board to protect the interests of the Bangko Sentral.\nTHE MONETARY BOARD"}},{"id":"PH-H6134-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Composition of the Monetary Board. - The powers and functions of the Bangko Sentral shall be exercised by the Bangko Sentral Monetary Board, hereafter referred to as the Monetary Board, composed of seven (7) members appointed by the President of the Philippines for a term of six (6) years.\nThe seven (7) members are:\n(a) the Governor of the Bangko Sentral, who shall be the Chairman of the Monetary Board. The Governor of the Bangko Sentral shall be head of a department and his appointment shall be subject to confirmation by the Commission on Appointments. Whenever the Governor is unable to attend a meeting of the Board, he shall designate a Deputy Governor to act as his alternate: Provided, That in such event, the Monetary Board shall designate one of its members as acting Chairman;\n(b) a member of the Cabinet to be designated by the President of the Philippines. Whenever the designated Cabinet Member is unable to attend a meeting of the Board, he shall designate an Undersecretary in his Department to attend as his alternate; and\n(c) five (5) members who shall come from the private sector, all of whom shall serve full-time: Provided, however, That of the members first appointed under the provisions of this subsection, three (3) shall have a term of six (6) years, and the other two (2), three (3) years.\nNo member of the Monetary Board may be reappointed more than once."}},{"id":"PH-H6134-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Vacancies. - Any vacancy in the Monetary Board created by the death, resignation, or removal of any member shall be filled by the appointment of a new member to complete the unexpired period of the term of the member concerned."}},{"id":"PH-H6134-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Qualifications. - The members of the Monetary Board must be natural-born citizens of the Philippines, at least thirty-five (35) years of age, with the exception of the Governor who should at least be forty (40) years of age, of good moral character, of unquestionable integrity, of known probity and patriotism, and with recognized competence in social and economic disciplines."}},{"id":"PH-H6134-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Disqualifications. - In addition to the disqualifications imposed by Republic Act No. 6713, a member of the Monetary Board is disqualified from being a director, officer, employee, consultant, lawyer, agent or stockholder of any bank, quasi-bank or any other institution which is subject to supervision or examination by the Bangko Sentral, in which case such member shall resign from, and divest himself of any and all interests in such institution before assumption of office as member of the Monetary Board.\nThe members of the Monetary Board coming from the private sector shall not hold any other public office or public employment during their tenure.\nNo person shall be a member of the Monetary Board if he has been connected directly with any multilateral banking or financial institution or has a substantial interest in any private bank in the Philippines, within one (1) year prior to his appointment; likewise, no member of the Monetary Board shall be employed in any such institution within two (2) years after the expiration of his term except when he serves as an official representative of the Philippine Government to such institution."}},{"id":"PH-H6134-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Removal. - The President may remove any member of the Monetary Board for any of the following reasons:\n(a) If the member is subsequently disqualified under the provisions of Section 8 of this Act; or\n(b) If he is physically or mentally incapacitated that he cannot properly discharge his duties and responsibilities and such incapacity has lasted for more than six (6) months; or\n(c) If the member is guilty of acts or operations which are of fraudulent or illegal character or which are manifestly opposed to the aims and interests of the Bangko Sentral; or\n(d) If the member no longer possesses the qualifications specified in Section 8 of this Act."}},{"id":"PH-H6134-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Meetings. - The Monetary Board shall meet at least once a week. The Board may be called to a meeting by the Governor of the Bangko Sentral or by two (2) other members of the Board.\nThe presence of four (4) members shall constitute a quorum: Provided, That in all cases the Governor or his duly designated alternate shall be among the four (4).\nUnless otherwise provided in this Act, all decisions of the Monetary Board shall require the concurrence of at least four (4) members.\nThe Bangko Sentral shall maintain and preserve a complete record of the proceedings and deliberations of the Monetary Board, including the tapes and transcripts of the stenographic notes, either in their original form or in microfilm."}},{"id":"PH-H6134-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Attendance of the Deputy Governors. - The Deputy Governors may attend the meetings of the Monetary Board with the right to be heard."}},{"id":"PH-H6134-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Salary. - The salary of the Governor and the members of the Monetary Board from the private sector shall be fixed by the President of the Philippines at a sum commensurate to the importance and responsibility attached to the position."}},{"id":"PH-H6134-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Withdrawal of Persons Having a Personal Interest. - In addition to the requirements of Republic Act No. 6713, any member of the Monetary Board with personal or pecuniary interest in any matter in the agenda of the Monetary Board shall disclose his interest to the Board and shall retire from the meeting when the matter is taken up. The decision taken on the matter shall be made public. The minutes shall reflect the disclosure made and the retirement of the member concerned from the meeting."}},{"id":"PH-H6134-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Exercise of Authority. - In the exercise of its authority, the Monetary Board shall:\n(a) issue rules and regulations it considers necessary for the effective discharge of the responsibilities and exercise of the powers vested upon the Monetary Board and the Bangko Sentral. The rules and regulations issued shall be reported to the President and the Congress within fifteen (15) days from the date of their issuance;\n(b) direct the management, operations, and administration of the Bangko Sentral, reorganize its personnel, and issue such rules and regulations as it may deem necessary or convenient for this purpose. The legal units of the Bangko Sentral shall be under the exclusive supervision and control of the Monetary Board;\n(c) establish a human resource management system which shall govern the selection, hiring, appointment, transfer, promotion, or dismissal of all personnel. Such system shall aim to establish professionalism and excellence at all levels of the Bangko Sentral in accordance with sound principles of management.\nA compensation structure, based on job evaluation studies and wage surveys and subject to the Board's approval, shall be instituted as an integral component of the Bangko Sentral's human resource development program: Provided, That the Monetary Board shall make its own system conform as closely as possible with the principles provided for under Republic Act No. 6758: Provided, however, That compensation and wage structure of employees whose positions fall under salary grade 19 and below shall be in accordance with the rates prescribed under Republic Act No. 6758.\nOn the recommendation of the Governor, appoint, fix the remunerations and other emoluments, and remove personnel of the Bangko Sentral, subject to pertinent civil service laws: Provided, That the Monetary Board shall have exclusive and final authority to promote, transfer, assign, or reassign personnel of the Bangko Sentral and these personnel actions are deemed made in the interest of the service and not disciplinary: Provided, further, That the Monetary Board may delegate such authority to the Governor under such guidelines as it may determine.\n(d) adopt an annual budget for and authorize such expenditures by the Bangko Sentral as are in the interest of the effective administration and operations of the Bangko Sentral in accordance with applicable laws and regulations; and\n(e) indemnify its members and other officials of the Bangko Sentral, including personnel of the departments performing supervision and examination functions against all costs and expenses reasonably incurred by such persons in connection with any civil or criminal action, suit or proceedings to which he may be, or is, made a party by reason of the performance of his functions or duties, unless he is finally adjudged in such action or proceeding to be liable for negligence or misconduct.\nIn the event of a settlement or compromise, indemnification shall be provided only in connection with such matters covered by the settlement as to which the Bangko Sentral is advised by external counsel that the person to be indemnified did not commit any negligence or misconduct.\nThe costs and expenses incurred in defending the aforementioned action, suit or proceeding may be paid by the Bangko Sentral in advance of the final disposition of such action, suit or proceeding upon receipt of an undertaking by or on behalf of the member, officer, or employee to repay the amount advanced should it ultimately be determined by the Monetary Board that he is not entitled to be indemnified as provided in this subsection."}},{"id":"PH-H6134-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Responsibility. - Members of the Monetary Board, officials, examiners, and employees of the Bangko Sentral who willfully violate this Act or who are guilty of negligence, abuses or acts of malfeasance or misfeasance or fail to exercise extraordinary diligence in the performance of his duties shall be held liable for any loss or injury suffered by the Bangko Sentral or other banking institutions as a result of such violation, negligence, abuse, malfeasance, misfeasance or failure to exercise extraordinary diligence.\nSimilar responsibility shall apply to members, officers, and employees of the Bangko Sentral for: (1) the disclosure of any information of a confidential nature, or any information on the discussions or resolutions of the Monetary Board, or about the confidential operations of the Bangko Sentral, unless the disclosure is in connection with the performance of official functions with the Bangko Sentral, or is with prior authorization of the Monetary Board or the Governor; or (2) the use of such information for personal gain or to the detriment of the Government, the Bangko Sentral or third parties: Provided, however, That any data or information required to be submitted to the President and/or the Congress, or to be published under the provisions of this Act shall not be considered confidential.\nTHE GOVERNOR AND DEPUTY GOVERNORS OF THE BANGKO SENTRAL"}},{"id":"PH-H6134-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Powers and Duties of the Governor. - The Governor shall be the chief executive officer of the Bangko Sentral. His powers and duties shall be to:\n(a) prepare the agenda for the meetings of the Monetary Board and to submit for the consideration of the Board the policies and measures which he believes to be necessary to carry out the purposes and provisions of this Act;\n(b) execute and administer the policies and measures approved by the Monetary Board;\n(c) direct and supervise the operations and internal administration of the Bangko Sentral. The Governor may delegate certain of his administrative responsibilities to other officers or may assign specific tasks or responsibilities to any full-time member of the Monetary Board without additional remuneration or allowance whenever he may deem fit or subject to such rules and regulations as the Monetary Board may prescribe;\n(d) appoint and fix the remunerations and other emoluments of personnel below the rank of a department head in accordance with the position and compensation plans approved by the Monetary Board, as well as to impose disciplinary measures upon personnel of the Bangko Sentral, subject to the provisions of Section 15(c) of this Act: Provided, That removal of personnel shall be with the approval of the Monetary Board;\n(e) render opinions, decisions, or rulings, which shall be final and executory until reversed or modified by the Monetary Board, on matters regarding application or enforcement of laws pertaining to institutions supervised by the Bangko Sentral and laws pertaining to quasi-banks, as well as regulations, policies or instructions issued by the Monetary Board, and the implementation thereof; and\n(f) exercise such other powers as may be vested in him by the Monetary Board."}},{"id":"PH-H6134-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Representation of the Monetary Board and the Bangko Sentral. - The Governor of the Bangko Sentral shall be the principal representative of the Monetary Board and of the Bangko Sentral and, in such capacity and in accordance with the instructions of the Monetary Board, he shall be empowered to:\n(a) represent the Monetary Board and the Bangko Sentral in all dealings with other offices, agencies and instrumentalities of the Government and all other persons or entities, public or private, whether domestic, foreign or international;\n(b) sign contracts entered into by the Bangko Sentral, notes and securities issued by the Bangko Sentral, all reports, balance sheets, profit and loss statements, correspondence and other documents of the Bangko Sentral.\nThe signature of the Governor may be in facsimile whenever appropriate;\n(c) represent the Bangko Sentral, either personally or through counsel, including private counsel, as may be authorized by the Monetary Board, in any legal proceedings, action or specialized legal studies; and\n(d) delegate his power to represent the Bangko Sentral, as provided in subsections (a), (b) and (c) of this section, to other officers upon his own responsibility: Provided, however, That in order to preserve the integrity and the prestige of his office, the Governor of the Bangko Sentral may choose not to participate in preliminary discussions with any multilateral banking or financial institution on any negotiations for the Government within or outside the Philippines. During the negotiations, he may instead be represented by a permanent negotiator."}},{"id":"PH-H6134-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Authority of the Governor in Emergencies. - In case of emergencies where time is sufficient to call a meeting of the Monetary Board, the Governor of the Bangko Sentral, with the concurrence of two (2) other members of the Monetary Board, may decide any matter or take any action within the authority of the Board.\nThe Governor shall submit a report to the President and Congress within seventy-two (72) hours after the action has been taken.\nAt the soonest possible time, the Governor shall call a meeting of the Monetary Board to submit his action for ratification."}},{"id":"PH-H6134-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Outside Interests of the Governor and the Full-time Members of the Board. - The Governor of the Bangko Sentral and the full-time members of the Board shall limit their professional activities to those pertaining directly to their positions with the Bangko Sentral. Accordingly, they may not accept any other employment, whether public or private, remunerated or ad honorem, with the exception of positions in eleemosynary, civic, cultural or religious organizations or whenever, by designation of the President, the Governor or the full-time member is tasked to represent the interest of the Government or other government agencies in matters connected with or affecting the economy or the financial system of the country."}},{"id":"PH-H6134-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Deputy Governors. - The Governor of the Bangko Sentral, with the approval of the Monetary Board, shall appoint not more than three (3) Deputy Governors who shall perform duties as may be assigned to them by the Governor and the Board.\nIn the absence of the Governor, a Deputy Governor designated by the Governor shall act as chief executive of the Bangko Sentral and shall exercise the powers and perform the duties of the Governor. Whenever the Government is unable to attend meetings of government boards or councils in which he is an ex officio member pursuant to provisions of special laws, a Deputy Governor as may be designated by the Governor shall be vested with authority to participate and exercise the right to vote in such meetings.\nOPERATIONS OF THE BANGKO SENTRAL"}},{"id":"PH-H6134-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Research and Statistics. - The Bangko Sentral shall prepare data and conduct economic research for the guidance of the Monetary Board in the formulation and implementation of its policies. Such data shall include, among others, forecasts of the balance of payments of the Philippines, statistics on the monthly movement of the monetary aggregates and of prices and other statistical series and economic studies useful for the formulation and analysis of monetary, banking, credit and exchange policies."}},{"id":"PH-H6134-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Authority to Obtain Data and Information. - The Bangko Sentral shall have the authority to request from government offices and instrumentalities, or government-owned or controlled corporations, any data which it may require for the proper discharge of its functions and responsibilities. The Bangko Sentral through the Governor or in his absence, a duly authorized representative shall have the power to issue a subpoena for the production of the books and records for the aforesaid purpose. Those who refuse the subpoena without justifiable cause, or who refuse to supply the bank with data requested or required, shall be subject to punishment for contempt in accordance with the provisions of the Rules of Court.\nData on individual firms, other than banks, gathered by the Department of Economic Research and other departments or units of the Bangko Sentral shall not be made available to any person or entity outside of the Bangko Sentral whether public or private except under order of the court or under such conditions as may be prescribed by the Monetary Board: Provided, however, That the collective data on firms may be released to interested persons or entities: Provided, finally, That in the case of data on banks, the provisions of Section 27 of this Act shall apply."}},{"id":"PH-H6134-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Training of Technical Personnel. - The Bangko Sentral shall promote and sponsor the training of technical personnel in the field of money and banking. Toward this end, the Bangko Sentral is hereby authorized to defray the costs of study, at home or abroad, of qualified employees of the Bangko Sentral, of promising university graduates or of any other qualified persons who shall be determined by proper competitive examinations. The Monetary Board shall prescribe rules and regulations to govern the training program of the Bangko Sentral."}},{"id":"PH-H6134-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Supervision and Examination. - The Bangko Sentral shall have supervision over, and conduct periodic or special examinations of, banking institutions and quasi-banks, including their subsidiaries and affiliates engaged in allied activities.\nFor purposes of this section, a subsidiary means a corporation more than fifty percent (50%) of the voting stock of which is owned by a bank or quasi-bank and an affiliate means a corporation the voting stock of which, to the extent of fifty percent (50%) or less, is owned by a bank or quasi-bank or which is related or linked to such institution or intermediary through common stockholders or such other factors as may be determined by the Monetary Board.\nThe department heads and the examiners of the supervising and/or examining departments are hereby authorized to administer oaths to any director, officer, or employee of any institution under their respective supervision or subject to their examination and to compel the presentation of all books, documents, papers or records necessary in their judgment to ascertain the facts relative to the true condition of any institution as well as the books and records of persons and entities relative to or in connection with the operations, activities or transactions of the institution under examination, subject to the provision of existing laws protecting or safeguarding the secrecy or confidentiality of bank deposits as well as investments of private persons, natural or juridical, in debt instruments issued by the Government.\nNo restraining order or injunction shall be issued by the court enjoining the Bangko Sentral from examining any institution subject to supervision or examination by the Bangko Sentral, unless there is convincing proof that the action of the Bangko Sentral is plainly arbitrary and made in bad faith and the petitioner or plaintiff files with the clerk or judge of the court in which the action is pending a bond executed in favor of the Bangko Sentral, in an amount to be fixed by the court. The provisions of Rule 58 of the New Rules of Court insofar as they are applicable and not inconsistent with the provisions of this section shall govern the issuance and dissolution of the restraining order or injunction contemplated in this section."}},{"id":"PH-H6134-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Bank Deposits and Investments. - Any director, officer or stockholder who, together with his related interest, contracts a loan or any form of financial accommodation from: (1) his bank; or (2) from a bank (a) which is a subsidiary of a bank holding company of which both his bank and the lending bank are subsidiaries or (b) in which a controlling proportion of the shares is owned by the same interest that owns a controlling proportion of the shares of his bank, in excess of five percent (5%) of the capital and surplus of the bank, or in the maximum amount permitted by law, whichever is lower, shall be required by the lending bank to waive the secrecy of his deposits of whatever nature in all banks in the Philippines. Any information obtained from an examination of his deposits shall be held strictly confidential and may be used by the examiners only in connection with their supervisory and examination responsibility or by the Bangko Sentral in an appropriate legal action it has initiated involving the deposit account."}},{"id":"PH-H6134-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Prohibitions. - In addition to the prohibitions found in Republic Act Nos. 3019 and 6713, personnel of the Bangko Sentral are hereby prohibited from:\n(a) being an officer, director, lawyer or agent, employee, consultant or stockholder, directly or indirectly, of any institution subject to supervision or examination by the Bangko Sentral, except non-stock savings and loan associations and provident funds organized exclusively for employees of the Bangko Sentral, and except as otherwise provided in this Act;\n(b) directly or indirectly requesting or receiving any gift, present or pecuniary or material benefit for himself or another, from any institution subject to supervision or examination by the Bangko Sentral;\n(c) revealing in any manner, except under orders of the court, the Congress or any government office or agency authorized by law, or under such conditions as may be prescribed by the Monetary Board, information relating to the condition or business of any institution. This prohibition shall not be held to apply to the giving of information to the Monetary Board or the Governor of the Bangko Sentral, or to any person authorized by either of them, in writing, to receive such information; and\n(d) borrowing from any institution subject to supervision or examination by the Bangko Sentral shall be prohibited unless said borrowings are adequately secured, fully disclosed to the Monetary Board, and shall be subject to such further rules and regulations as the Monetary Board may prescribe: Provided, however, That personnel of the supervising and examining departments are prohibited from borrowing from a bank under their supervision or examination."}},{"id":"PH-H6134-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Examination and Fees. - The supervising and examining department head, personally or by deputy, shall examine the books of every banking institution once in every twelve (12) months, and at such other times as the Monetary Board by an affirmative vote of five (5) members, may deem expedient and to make a report on the same to the Monetary Board: Provided, That there shall be an interval of at least twelve (12) months between annual examinations.\nThe bank concerned shall afford to the head of the appropriate supervising and examining departments and to his authorized deputies full opportunity to examine its books, cash and available assets and general condition at any time during banking hours when requested to do so by the Bangko Sentral: Provided, however, That none of the reports and other papers relative to such examinations shall be open to inspection by the public except insofar as such publicity is incidental to the proceedings hereinafter authorized or is necessary for the prosecution of violations in connection with the business of such institutions.\nBanking and quasi-banking institutions which are subject to examination by the Bangko Sentral shall pay to the Bangko Sentral, within the first thirty (30) days of each year, an annual fee in an amount equal to a percentage as may be prescribed by the Monetary Board of its average total assets during the preceding year as shown on its end-of-month balance sheets, after deducting cash on hand and amounts due from banks, including the Bangko Sentral and banks abroad."}},{"id":"PH-H6134-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Appointment of Conservator. - Whenever, on the basis of a report submitted by the appropriate supervising or examining department, the Monetary Board finds that a bank or a quasi-bank is in a state of continuing inability or unwillingness to maintain a condition of liquidity deemed adequate to protect the interest of depositors and creditors, the Monetary Board may appoint a conservator with such powers as the Monetary Board shall deem necessary to take charge of the assets, liabilities, and the management thereof, reorganize the management, collect all monies and debts due said institution, and exercise all powers necessary to restore its viability. The conservator shall report and be responsible to the Monetary Board and shall have the power to overrule or revoke the actions of the previous management and board of directors of the bank or quasi-bank.\nThe conservator should be competent and knowledgeable in bank operations and management. The conservatorship shall not exceed one (1) year.\nThe conservator shall receive remuneration to be fixed by the Monetary Board in an amount not to exceed two-thirds (2/3) of the salary of the president of the institution in one (1) year, payable in twelve (12) equal monthly payments: Provided, That, if at any time within one-year period, the conservatorship is terminated on the ground that the institution can operate on its own, the conservator shall receive the balance of the remuneration which he would have received up to the end of the year; but if the conservatorship is terminated on other grounds, the conservator shall not be entitled to such remaining balance. The Monetary Board may appoint a conservator connected with the Bangko Sentral, in which case he shall not be entitled to receive any remuneration or emolument from the Bangko Sentral during the conservatorship. The expenses attendant to the conservatorship shall be borne by the bank or quasi-bank concerned.\nThe Monetary Board shall terminate the conservatorship when it is satisfied that the institution can continue to operate on its own and the conservatorship is no longer necessary. The conservatorship shall likewise be terminated should the Monetary Board, on the basis of the report of the conservator or of its own findings, determine that the continuance in business of the institution would involve probable loss to its depositors or creditors, in which case the provisions of Section 30 shall apply."}},{"id":"PH-H6134-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Proceedings in Receivership and Liquidation. - Whenever, upon report of the head of the supervising or examining department, the Monetary Board finds that a bank or quasi-bank:\n(a) is unable to pay its liabilities as they become due in the ordinary course of business: Provided, That this shall not include inability to pay caused by extraordinary demands induced by financial panic in the banking community;\n(b) has insufficient realizable assets, as determined by the Bangko Sentral, to meet its liabilities; or\n(c) cannot continue in business without involving probable losses to its depositors or creditors; or\n(d) has willfully violated a cease and desist order under Section 37 that has become final, involving acts or transactions which amount to fraud or a dissipation of the assets of the institution; in which cases, the Monetary Board may summarily and without need for prior hearing forbid the institution from doing business in the Philippines and designate the Philippine Deposit Insurance Corporation as receiver of the banking institution.\nFor a quasi-bank, any person of recognized competence in banking or finance may be designed as receiver.\nThe receiver shall immediately gather and take charge of all the assets and liabilities of the institution, administer the same for the benefit of its creditors, and exercise the general powers of a receiver under the Revised Rules of Court but shall not, with the exception of administrative expenditures, pay or commit any act that will involve the transfer or disposition of any asset of the institution: Provided, That the receiver may deposit or place the funds of the institution in non-speculative investments. The receiver shall determine as soon as possible, but not later than ninety (90) days from take over, whether the institution may be rehabilitated or otherwise placed in such a condition so that it may be permitted to resume business with safety to its depositors and creditors and the general public: Provided, That any determination for the resumption of business of the institution shall be subject to prior approval of the Monetary Board.\nIf the receiver determines that the institution cannot be rehabilitated or permitted to resume business in accordance with the next preceding paragraph, the Monetary Board shall notify in writing the board of directors of its findings and direct the receiver to proceed with the liquidation of the institution. The receiver shall:\n(1) file ex parte with the proper regional trial court, and without requirement of prior notice or any other action, a petition for assistance in the liquidation of the institution pursuant to a liquidation plan adopted by the Philippine Deposit Insurance Corporation for general application to all closed banks. In case of quasi-banks, the liquidation plan shall be adopted by the Monetary Board. Upon acquiring jurisdiction, the court shall, upon motion by the receiver after due notice, adjudicate disputed claims against the institution, assist the enforcement of individual liabilities of the stockholders, directors and officers, and decide on other issues as may be material to implement the liquidation plan adopted. The receiver shall pay the cost of the proceedings from the assets of the institution.\n(2) convert the assets of the institutions to money, dispose of the same to creditors and other parties, for the purpose of paying the debts of such institution in accordance with the rules on concurrence and preference of credit under the Civil Code of the Philippines and he may, in the name of the institution, and with the assistance of counsel as he may retain, institute such actions as may be necessary to collect and recover accounts and assets of, or defend any action against, the institution. The assets of an institution under receivership or liquidation shall be deemed in custodia legis in the hands of the receiver and shall, from the moment the institution was placed under such receivership or liquidation, be exempt from any order of garnishment, levy, attachment, or execution.\nThe actions of the Monetary Board taken under this section or under Section 29 of this Act shall be final and executory, and may not be restrained or set aside by the court except on petition for certiorari on the ground that the action taken was in excess of jurisdiction or with such grave abuse of discretion as to amount to lack or excess of jurisdiction. The petition for certiorari may only be filed by the stockholders of record representing the majority of the capital stock within ten (10) days from receipt by the board of directors of the institution of the order directing receivership, liquidation or conservatorship.\nThe designation of a conservator under Section 29 of this Act or the appointment of a receiver under this section shall be vested exclusively with the Monetary Board. Furthermore, the designation of a conservator is not a precondition to the designation of a receiver."}},{"id":"PH-H6134-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Distribution of Assets. - In case of liquidation of a bank or quasi-bank, after payment of the cost of proceedings, including reasonable expenses and fees of the receiver to be allowed by the court, the receiver shall pay the debts of such institution, under order of the court, in accordance with the rules on concurrence and preference of credit as provided in the Civil Code."}},{"id":"PH-H6134-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Disposition of Revenues and Earnings. - All revenues and earnings realized by the receiver in winding up the affairs and administering the assets of any bank or quasi-bank within the purview of this Act shall be used to pay the costs, fees and expenses mentioned in the preceding section, salaries of such personnel whose employment is rendered necessary in the discharge of the liquidation together with other additional expenses caused thereby. The balance of revenues and earnings, after the payment of all said expenses, shall form part of the assets available for payment to creditors."}},{"id":"PH-H6134-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Disposition of Banking Franchise. - The Bangko Sentral may, if public interest so requires, award to an institution, upon such terms and conditions as the Monetary Board may approve, the banking franchise of a bank under liquidation to operate in the area where said bank or its branches were previously operating: Provided, That whatever proceeds may be realized from such award shall be subject to the appropriate exclusive disposition of the Monetary Board."}},{"id":"PH-H6134-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Refusal to Make Reports or Permit Examination. - Any officer, owner, agent, manager, director or officer-in-charge of any institution subject to the supervision or examination by the Bangko Sentral within the purview of this Act who, being required in writing by the Monetary Board or by the head of the supervising and examining department willfully refuses to file the required report or permit any lawful examination into the affairs of such institution shall be punished by a fine of not less than Fifty thousand pesos (P50,000) nor more than One hundred thousand pesos (P100,000) or by imprisonment of not less than one (1) year nor more than five (5) years, or both, in the discretion of the court."}},{"id":"PH-H6134-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"False Statement. - The willful making of a false or misleading statement on a material fact to the Monetary Board or to the examiners of the Bangko Sentral shall be punished by a fine of not less than One hundred thousand pesos (P100,000) nor more than Two hundred thousand pesos (P200,000), or by imprisonment of not more than (5) years, or both, at the discretion of the court."}},{"id":"PH-H6134-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Proceedings Upon Violation of This Act and Other Banking Laws, Rules, Regulations, Orders or Instructions. - Whenever a bank or quasi-bank, or whenever any person or entity willfully violates this Act or other pertinent banking laws being enforced or implemented by the Bangko Sentral or any order, instruction, rule or regulation issued by the Monetary Board, the person or persons responsible for such violation shall unless otherwise provided in this Act be punished by a fine of not less than Fifty thousand pesos (P50,000) nor more than Two hundred thousand pesos (P200,000) or by imprisonment of not less than two (2) years nor more than ten (10) years, or both, at the discretion of the court.\nWhenever a bank or quasi-bank persists in carrying on its business in an unlawful or unsafe manner, the Board may, without prejudice to the penalties provided in the preceding paragraph of this section and the administrative sanctions provided in Section 37 of this Act, take action under Section 30 of this Act."}},{"id":"PH-H6134-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Administrative Sanctions on Banks and Quasi-banks. - Without prejudice to the criminal sanctions against the culpable persons provided in Sections 34, 35, and 36 of this Act, the Monetary Board may, at its discretion, impose upon any bank or quasi-bank, their directors and/or officers, for any willful violation of its charter or by-laws, willful delay in the submission of reports or publications thereof as required by law, rules and regulations; any refusal to permit examination into the affairs of the institution; any willful making of a false or misleading statement to the Board or the appropriate supervising and examining department or its examiners; any willful failure or refusal to comply with, or violation of, any banking law or any order, instruction or regulation issued by the Monetary Board, or any order, instruction or ruling by the Governor; or any commission of irregularities, and/or conducting business in an unsafe or unsound manner as may be determined by the Monetary Board, the following administrative sanctions, whenever applicable:\n(a) fines in amounts as may be determined by the Monetary Board to be appropriate, but in no case to exceed Thirty thousand pesos (P30,000) a day for each violation, taking into consideration the attendant circumstances, such as the nature and gravity of the violation or irregularity and the size of the bank or quasi-bank;\n(b) suspension of rediscounting privileges or access to Bangko Sentral credit facilities;\n(c) suspension of lending or foreign exchange operations or authority to accept new deposits or make new investments;\n(d) suspension of interbank clearing privileges; and/or\n(e) revocation of quasi-banking license.\nResignation or termination from office shall not exempt such director or officer from administrative or criminal sanctions.\nThe Monetary Board may, whenever warranted by circumstances, preventively suspend any director or officer of a bank or quasi-bank pending an investigation: Provided, That should the case be not finally decided by the Bangko Sentral within a period of one hundred twenty (120) days after the date of suspension, said director or officer shall be reinstated in his position: Provided, further, That when the delay in the disposition of the case is due to the fault, negligence or petition of the director or officer, the period of delay shall not be counted in computing the period of suspension herein provided.\nThe above administrative sanctions need not be applied in the order of their severity.\nWhether or not there is an administrative proceeding, if the institution and/or the directors and/or officers concerned continue with or otherwise persist in the commission of the indicated practice or violation, the Monetary Board may issue an order requiring the institution and/or the directors and/or officers concerned to cease and desist from the indicated practice or violation, and may further order that immediate action be taken to correct the conditions resulting from such practice or violation. The cease and desist order shall be immediately effective upon service on the respondents.\nThe respondents shall be afforded an opportunity to defend their action in a hearing before the Monetary Board or any committee chaired by any Monetary Board member created for the purpose, upon request made by the respondents within five (5) days from their receipt of the order. If no such hearing is requested within said period, the order shall be final. If a hearing is conducted, all issues shall be determined on the basis of records, after which the Monetary Board may either reconsider or make final its order.\nThe Governor is hereby authorized, at his discretion, to impose upon banking institutions, for any failure to comply with the requirements of law, Monetary Board regulations and policies, and/or instructions issued by the Monetary Board or by the Governor, fines not in excess of Ten thousand pesos (P10,000) a day for each violation, the imposition of which shall be final and executory until reversed, modified or lifted by the Monetary Board on appeal."}},{"id":"PH-H6134-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Operating Departments of the Bangko Sentral. - The Monetary Board shall, in accordance with its authority under this Act, determine and provide for such operating departments and other offices, including a public information office, of the Bangko Sentral as it deems convenient for the proper and efficient conduct of the operations and the accomplishment of the objectives of the Bangko Sentral. The functions and duties of such operating departments and other offices shall be determined by the Monetary Board.\nREPORTS AND PUBLICATIONS"}},{"id":"PH-H6134-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Reports and Publications. - The Bangko Sentral shall publish a general balance sheet showing the volume and composition of its assets and liabilities as of the last working day of the month within sixty (60) days after the end of each month except for the month of December, which shall be submitted within ninety (90) days after the end hereof.\nThe Monetary Board shall publish and submit the following reports to the President and to the Congress:\n(a) not later than ninety (90) days after the end of each quarter, an analysis of economic and financial developments, including the condition of net international reserves and monetary aggregates;\n(b) within ninety (90) days after the end of the year, the preceding year's budget and profit and loss statement of the Bangko Sentral showing in reasonable detail the result of its operations;\n(c) one hundred twenty (120) days after the end of each semester, a review of the state of the financial system; and\n(d) as soon as practicable, abnormal movements in monetary aggregates and the general price level, and, not later than seventy-two (72) hours after they are taken, remedial measures in response to such abnormal movements."}},{"id":"PH-H6134-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Annual Report. - Before the end of March of each year, the Bangko Sentral shall publish and submit to the President and the Congress an annual report on the condition of the Bangko Sentral including a review of the policies and measures adopted by the Monetary Board during the past year and an analysis of the economic and financial circumstances which gave rise to said policies and measures.\nThe annual report shall also include a statement of the financial condition of the Bangko Sentral and a statistical appendix which shall present, as a minimum, the following data:\n(a) the monthly movement of monetary aggregates and their components;\n(b) the monthly movement of purchases and sales of foreign exchange and of the international reserves of the Bangko Sentral;\n(c) the balance of payments of the Philippines;\n(d) monthly indices of consumer prices and of import and export prices;\n(e) the monthly movement, in summary form, of exports and imports, by volume and value;\n(f) the monthly movement of the accounts of the Bangko Sentral and of other banks;\n(g) the principal data on government receipts and expenditures and on the status of the public debt, both domestic and foreign; and\n(h) the texts of the major legal and administrative measures adopted by the Government and the Monetary Board during the year which relate to the functions or operations of the Bangko Sentral or of the financial system.\nThe Bangko Sentral shall publish another version of the annual report in terms understandable to the layman.\nFailure to comply with the reportorial requirements pursuant to this article without justifiable reason as may be determined by the Monetary Board shall cause the withholding of the salary of the personnel concerned until the requirements are complied with."}},{"id":"PH-H6134-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Signatures on Statements. - The balance sheets and other financial statements of the Bangko Sentral shall be signed by the officers responsible for their preparation, by the Governor, and by the auditor of the Bangko Sentral.\nPROFITS, LOSSES, AND SPECIAL ACCOUNTS"}},{"id":"PH-H6134-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Fiscal Year. - The fiscal year of the Bangko Sentral shall begin on January first and end on December thirty-first of each year."}},{"id":"PH-H6134-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Computation of Profits and Losses. - Within the first thirty (30) days following the end of each year, the Bangko Sentral shall determine its net profits or losses. In the calculation of net profits, the Bangko Sentral shall make adequate allowance or establish adequate reserves for bad and doubtful accounts."}},{"id":"PH-H6134-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Distribution of Net Profits. - Within the first sixty (60) days following the end of each fiscal year, the Monetary Board shall determine and carry out the distribution of the net profits, in accordance with the following rule:\nFifty percent (50%) of the net profits shall be carried to surplus and the remaining fifty percent (50%) shall revert back to the National Treasury, except as otherwise provided in the transitory provisions of this Act."}},{"id":"PH-H6134-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Revaluation Profits and Losses. - Profits or losses arising from any revaluation of the Bangko Sentral's net assets or liabilities in gold or foreign currencies with respect to the Philippine peso shall not be included in the computation of the annual profits and losses of the Bangko Sentral. Any profits or losses arising in this manner shall be offset by any amounts which, as a consequence of such revaluations, are owed by the Philippines to any international or regional intergovernmental financial institution of which the Philippines is a member or are owed by these institutions to the Philippines. Any remaining profit or loss shall be carried in a special frozen account which shall be named \"Revaluation of International Reserve\" and the net balance of which shall appear either among the liabilities or among the assets of the Bangko Sentral, depending on whether the revaluations have produced net profits or net losses.\nThe Revaluation of International Reserve account shall be neither credited nor debited for any purposes other than those specifically authorized in this section."}},{"id":"PH-H6134-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Suspense Accounts. - Sections 43 and 43-A of Republic Act No. 265, as amended, creating the Monetary Adjustment Account (MAA) and the Exchange Stabilization Adjustment Account (ESAA), respectively, are hereby repealed. Amounts outstanding as of the effective date of this Act based on these accounts shall continue to be for the account of the Central Bank and shall be governed by the transitory provisions of this Act.\nThe Revaluation of International Reserve (RIR) account as of the effective date of this Act of the Central Bank shall continue to be for the account of the same entity and shall be governed by the provisions of Section 44 of Republic Act No. 265, as amended, until otherwise provided for in accordance with the transitory provisions of this Act.\nTHE AUDITOR"}},{"id":"PH-H6134-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Appointment and Personnel. - The Chairman of the Commission on Audit shall act as the ex officio auditor of the Bangko Sentral and, as such, he is empowered and authorized to appoint a representative who shall be the auditor of the Bangko Sentral and, in accordance with law, fix his salary, and to appoint and fix salaries and number of personnel to assist said representative in his work. The salaries and other emoluments shall be paid by the Commission. The auditor of the Bangko Sentral and personnel under him may be removed only by the Chairman of the Commission.\nThe representative of the Chairman of the Commission must be a certified public accountant with at least ten (10) years experience as such. No relative of any member of the Monetary Board or the Chairman of the Commission within the sixth degree of consanguinity or affinity shall be appointed such representative.\nTHE UNIT OF MONETARY VALUE"}},{"id":"PH-H6134-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"ARTICLE I"},"text":{"en":"The Peso. - The unit of monetary value in the Philippines is the \"peso,\" which is represented by the sign \"P.\"\nThe peso is divided into one hundred (100) equal parts called \"centavos,\" which are represented by the sign \"c.\"\nISSUE OF MEANS OF PAYMENT\nA. CURRENCY"}},{"id":"PH-H6134-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Definition of Currency. - The word \"currency\" is hereby defined, for purposes of this Act, as meaning all Philippine notes and coins issued or circulating in accordance with the provisions of this Act."}},{"id":"PH-H6134-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Exclusive Issue Power. - The Bangko Sentral shall have the sole power and authority to issue currency, within the territory of the Philippines. No other person or entity, public or private, may put into circulation notes, coins or any other object or document which, in the opinion of the Monetary Board, might circulate as currency, nor reproduce or imitate the facsimiles of Bangko Sentral notes without prior authority from the Bangko Sentral.\nThe Monetary Board may issue such regulations as it may deem advisable in order to prevent the circulation of foreign currency or of currency substitutes as well as to prevent the reproduction of facsimiles of Bangko Sentral notes.\nThe Bangko Sentral shall have the authority to investigate, make arrests, conduct searches and seizures in accordance with law, for the purpose of maintaining the integrity of the currency.\nViolation of this provision or any regulation issued by the Bangko Sentral pursuant thereto shall constitute an offense punishable by imprisonment of not less than five (5) years but not more than ten (10) years. In case the Revised Penal Code provides for a greater penalty, then that penalty shall be imposed."}},{"id":"PH-H6134-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Liability for Notes and Coins. - Notes and coins issued by the Bangko Sentral shall be liabilities of the Bangko Sentral and may be issued only against, and in amounts not exceeding, the assets of the Bangko Sentral. Said notes and coins shall be a first and paramount lien on all assets of the Bangko Sentral.\nThe Bangko Sentral's holdings of its own notes and coins shall not be considered as part of its currency issue and, accordingly, shall not form part of the assets or liabilities of the Bangko Sentral."}},{"id":"PH-H6134-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Legal Tender Power. - All notes and coins issued by the Bangko Sentral shall be fully guaranteed by the Government of the Republic of the Philippines and shall be legal tender in the Philippines for all debts, both public and private: Provided, however, That, unless otherwise fixed by the Monetary Board, coins shall be legal tender in amounts not exceeding Fifty pesos (P50.00) for denominations of Twenty-five centavos and above, and in amounts not exceeding Twenty pesos (P20.00) for denominations of Ten centavos or less."}},{"id":"PH-H6134-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Characteristics of the Currency. - The Monetary Board, with the approval of the President of the Philippines, shall prescribe the denominations, dimensions, designs, inscriptions and other characteristics of notes issued by the Bangko Sentral: Provided, however, That said notes shall state that they are liabilities of the Bangko Sentral and are fully guaranteed by the Government of the Republic of the Philippines. Said notes shall bear the signatures, in facsimile, of the President of the Philippines and of the Governor of the Bangko Sentral.\nSimilarly, the Monetary Board, with the approval of the President of the Philippines, shall prescribe the weight, fineness, designs, denominations and other characteristics of the coins issued by the Bangko Sentral. In the minting of coins, the Monetary Board shall give full consideration to the availability of suitable metals and to their relative prices and cost of minting."}},{"id":"PH-H6134-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Printing of Notes and Mining of Coins. - The Monetary Board shall prescribe the amounts of notes and coins to be printed and minted, respectively, and the conditions to which the printing of notes and the minting of coins shall be subject. The Monetary Board shall have the authority to contract institutions, mints or firms for such operations.\nAll expenses incurred in the printing of notes and the minting of coins shall be for the account of the Bangko Sentral."}},{"id":"PH-H6134-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Interconvertibility of Currency. - The Bangko Sentral shall exchange, on demand and without charge, Philippine currency of any denomination for Philippine notes and coins of any other denomination requested. If for any reason the Bangko Sentral is temporarily unable to provide notes or coins of the denominations requested, it shall meet its obligations by delivering notes and coins of the denominations which most nearly approximate those requested."}},{"id":"PH-H6134-A56","no":56,"noLabel":{"en":"Section 56."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Replacement of Currency Unfit for Circulation. - The Bangko Sentral shall withdraw from circulation and shall demonetize all notes and coins which for any reason whatsoever are unfit for circulation and shall replace them by adequate notes and coins: Provided, however, That the Bangko Sentral shall not replace notes and coins the identification of which is impossible, coins which show signs of filing, clipping or perforation, and notes which have lost more than two-fifths (2/5) of their surface or all of the signatures inscribed thereon. Notes and coins in such mutilated conditions shall be withdrawn from circulation and demonetized without compensation to the bearer."}},{"id":"PH-H6134-A57","no":57,"noLabel":{"en":"Section 57."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Retirement of Old Notes and Coins. - The Bangko Sentral may call in for replacement notes of any series or denomination which are more than five (5) years old and coins which are more than (10) years old.\nNotes and coins called in for replacement in accordance with this provision shall remain legal tender for a period of one (1) year from the date of call. After this period, they shall cease to be legal tender but during the following year, or for such longer period as the Monetary Board may determine, they may be exchanged at par and without charge in the Bangko Sentral and by agents duly authorized by the Bangko Sentral for this purpose. After the expiration of this latter period, the notes and coins which have not been exchanged shall cease to be a liability of the Bangko Sentral and shall be demonetized. The Bangko Sentral shall also demonetize all notes and coins which have been called in and replaced. B. DEMAND DEPOSITS"}},{"id":"PH-H6134-A58","no":58,"noLabel":{"en":"Section 58."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Definition. - For purposes of this Act, the term \"demand deposits\" means all those liabilities of the Bangko Sentral and of other banks which are denominated in Philippine currency and are subject to payment in legal tender upon demand by the presentation of checks."}},{"id":"PH-H6134-A59","no":59,"noLabel":{"en":"Section 59."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Issue of Demand Deposits. - Only banks duly authorized to do so may accept funds or create liabilities payable in pesos upon demand by the presentation of checks, and such operations shall be subject to the control of the Monetary Board in accordance with the powers granted it with respect thereto under this Act."}},{"id":"PH-H6134-A60","no":60,"noLabel":{"en":"Section 60."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Legal Character. - Checks representing demand deposits do not have legal tender power and their acceptance in the payment of debts, both public and private, is at the option of the creditor: Provided, however, That a check which has been cleared and credited to the account of the creditor shall be equivalent to a delivery to the creditor of cash in an amount equal to the amount credited to his account.\nDOMESTIC MONETARY STABILIZATION"}},{"id":"PH-H6134-A61","no":61,"noLabel":{"en":"Section 61."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Guiding Principle. - The Monetary Board shall endeavor to control any expansion or contraction in monetary aggregates which is prejudicial to the attainment or maintenance of price stability."}},{"id":"PH-H6134-A62","no":62,"noLabel":{"en":"Section 62."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Power to Define Terms. - For purposes of this article and of this Act, the Monetary Board shall formulate definitions of monetary aggregates, credit and prices and shall make public such definitions and any changes thereof."}},{"id":"PH-H6134-A63","no":63,"noLabel":{"en":"Section 63."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Action When Abnormal Movements Occur in the Monetary Aggregates, Credit, or Price Level. - Whenever abnormal movements in the monetary aggregates, in credit, or in prices endanger the stability of the Philippine economy or important sectors thereof, the Monetary Board shall:\n(a) take such remedial measures as are appropriate and within the powers granted to the Monetary Board and the Bangko Sentral under the provisions of this Act; and\n(b) submit to the President of the Philippines and the Congress, and make public, a detailed report which shall include, as a minimum, a description and analysis of:\n(1) the causes of the rise or fall of the monetary aggregates, of credit or of prices;\n(2) the extent to which the changes in the monetary aggregates, in credit, or in prices have been reflected in changes in the level of domestic output, employment, wages and economic activity in general, and the nature and significance of any such changes; and\n(3) the measures which the Monetary Board has taken and the other monetary, fiscal or administrative measures which it recommends to be adopted.\nWhenever the monetary aggregates, or the level of credit, increases or decreases by more than fifteen percent (15%), or the cost of living index increases by more than ten percent (10%), in relation to the level existing at the end of the corresponding month of the preceding year, or even though any of these quantitative guidelines have not been reached when in its judgment the circumstances so warrant, the Monetary Board shall submit the reports mentioned in this section, and shall state therein whether, in the opinion of the Board, said changes in the monetary aggregates, credit or cost of living represent a threat to the stability of the Philippine economy or of important sectors thereof.\nThe Monetary Board shall continue to submit periodic reports to the President of the Philippines and to Congress until it considers that the monetary, credit or price disturbances have disappeared or have been adequately controlled.\nINTERNATIONAL MONETARY STABILIZATION"}},{"id":"PH-H6134-A64","no":64,"noLabel":{"en":"Section 64."},"chapter":{"en":"ARTICLE II"},"text":{"en":"International Monetary Stabilization. - The Bangko Sentral shall exercise its powers under this Act to preserve the international value of the peso and to maintain its convertibility into other freely convertible currencies primarily for, although not necessarily limited to, current payments for foreign trade and invisibles."}},{"id":"PH-H6134-A65","no":65,"noLabel":{"en":"Section 65."},"chapter":{"en":"ARTICLE II"},"text":{"en":"International Reserves. - In order to maintain the international stability and convertibility of the Philippine peso, the Bangko Sentral shall maintain international reserves adequate to meet any foreseeable net demands on the Bangko Sentral for foreign currencies.\nIn judging the adequacy of the international reserves, the Monetary Board shall be guided by the prospective receipts and payments of foreign exchange by the Philippines. The Board shall give special attention to the volume and maturity of the Bangko Sentral's own liabilities in foreign currencies, to the volume and maturity of the foreign exchange assets and liabilities of other banks operating in the Philippines and, insofar as they are known or can be estimated, the volume and maturity of the foreign exchange assets and liabilities of all other persons and entities in the Philippines."}},{"id":"PH-H6134-A66","no":66,"noLabel":{"en":"Section 66."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Composition of the International Reserves. - The international reserves of the Bangko Sentral may include but shall not be limited to the following assets:\n(a) gold; and\n(b) assets in foreign currencies in the form of: documents and instruments customarily employed for the international transfer of funds; demand and time deposits in central banks, treasuries and commercial banks abroad; foreign government securities; and foreign notes and coins.\nThe Monetary Board shall endeavor to hold the foreign exchange resources of the Bangko Sentral in freely convertible currencies; moreover, the Board shall give particular consideration to the prospects of continued strength and convertibility of the currencies in which the reserve is maintained, as well as to the anticipated demands for such currencies. The Monetary Board shall issue regulations determining the other qualifications which foreign exchange assets must meet in order to be included in the international reserves of the Bangko Sentral.\nThe Bangko Sentral shall be free to convert any of the assets in its international reserves into other assets as described in subsections (a) and (b) of this section."}},{"id":"PH-H6134-A67","no":67,"noLabel":{"en":"Section 67."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Action When the International Stability of the Peso Is Threatened. - Whenever the international reserve of the Bangko Sentral falls to a level which the Monetary Board considers inadequate to meet prospective net demands on the Bangko Sentral for foreign currencies, or whenever the international reserve appears to be in imminent danger of falling to such a level, or whenever the international reserve is falling as a result of payments or remittances abroad which, in the opinion of the Monetary Board, are contrary to the national welfare, the Monetary Board shall:\n(a) take such remedial measures as are appropriate and within the powers granted to the Monetary Board and the Bangko Sentral under the provisions of this Act; and\n(b) submit to the President of the Philippines and to Congress a detailed report which shall include, as a minimum, a description and analysis of:\n(1) the nature and causes of the existing or imminent decline;\n(2) the remedial measures already taken or to be taken by the Monetary Board;\n(3) the monetary, fiscal or administrative measures further proposed; and\n(4) the character and extent of the cooperation required from other government agencies for the successful execution of the policies of the Monetary Board.\nIf the resultant actions fail to check the deterioration of the reserve position of the Bangko Sentral, or if the deterioration cannot be checked except by chronic restrictions on exchange and trade transactions or by sacrifice of the domestic objectives of a balanced and sustainable growth of the economy, the Monetary Board shall propose to the President, with appropriate notice of the Congress, such additional action as it deems necessary to restore equilibrium in the international balance of payments of the Philippines.\nThe Monetary Board shall submit periodic reports to the President and to Congress until the threat to the international monetary stability of the Philippines has disappeared.\nGENERAL CRITERION"}},{"id":"PH-H6134-A68","no":68,"noLabel":{"en":"Section 68."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Means of Action. - In order to achieve the primary objective of price stability, the Monetary Board shall rely on its moral influence and the powers granted to it under this Act for the management of monetary aggregates.\nOPERATIONS IN GOLD AND FOREIGN EXCHANGE"}},{"id":"PH-H6134-A69","no":69,"noLabel":{"en":"Section 69."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Purchases and Sales of Gold. - The Bangko Sentral may buy and sell gold in any form, subject to such regulations as the Monetary Board may issue.\nThe purchases and sales of gold authorized by this section shall be made in the national currency at the prevailing international market price as determined by the Monetary Board."}},{"id":"PH-H6134-A70","no":70,"noLabel":{"en":"Section 70."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Purchases and Sales of Foreign Exchange. - The Bangko Sentral may buy and sell foreign notes and coins, and documents and instruments of types customarily employed for the international transfer of funds. The Bangko Sentral may engage in future exchange operations.\nThe Bangko Sentral may engage in foreign exchange transactions with the following entities or persons only:\n(a) banking institutions operating in the Philippines;\n(b) the Government, its political subdivisions and instrumentalities;\n(c) foreign or international financial institutions;\n(d) foreign governments and their instrumentalities; and\n(e) other entities or persons which the Monetary Board is hereby empowered to authorize as foreign exchange dealers, subject to such rules and regulations as the Monetary Board shall prescribe.\nIn order to maintain the convertibility of the peso, the Bangko Sentral may, at the request of any banking institution operating in the Philippines, buy any quantity of foreign exchange offered, and sell any quantity of foreign exchange demanded, by such institution, provided that the foreign currencies so offered or demanded are freely convertible into gold or United States dollars. This requirement shall not apply to demands for foreign notes and coins.\nThe Bangko Sentral shall effect its exchange transactions between foreign currencies and the Philippine peso at the rates determined in accordance with the provisions of Section 74 of this Act."}},{"id":"PH-H6134-A71","no":71,"noLabel":{"en":"Section 71."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Foreign Asset Position of the Bangko Sentral. - The Bangko Sentral shall endeavor to maintain at all times a net positive foreign asset position so that its gross foreign exchange assets will always exceed its gross foreign liabilities. In the event that the equivalent amount in pesos of the foreign exchange liabilities of the Bangko Sentral exceed twice the equivalent amount in pesos of the foreign exchange assets of the bank, the Bangko Sentral shall, within sixty (60) days from the date the limit is exceeded, submit a report to the Congress stating the origin of these liabilities, and the manner in which they will be paid."}},{"id":"PH-H6134-A72","no":72,"noLabel":{"en":"Section 72."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Emergency Restrictions on Exchange Operations. - In order to achieve the primary objective of the Bangko Sentral as set forth in Section 3 of this Act, or protect the international reserves of the Bangko Sentral in the imminence of, or during an exchange crisis, or in time of national emergency and to give the Monetary Board and the Government time in which to take constructive measures to forestall, combat, or overcome such a crisis or emergency, the Monetary Board, with the concurrence of at least five (5) of its members and with the approval of the President of the Philippines, may temporarily suspend or restrict sales of exchange by the Bangko Sentral, and may subject all transactions in gold and foreign exchange to license by the Bangko Sentral, and may require that any foreign exchange thereafter obtained by any person residing or entity operating in the Philippines be delivered to the Bangko Sentral or to any bank or agent designated by the Bangko Sentral for the purpose, at the effective exchange rate or rates: Provided, however, That foreign currency deposits made under Republic Act No. 6426 shall be exempt from these requirements."}},{"id":"PH-H6134-A73","no":73,"noLabel":{"en":"Section 73."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Acquisition of Inconvertible Currencies. - The Bangko Sentral shall avoid the acquisition and holding of currencies which are not freely convertible, and may acquire such currencies in an amount exceeding the minimum balance necessary to cover current demands for said currencies only when, and to the extent that, such acquisition is considered by the Monetary Board to be in the national interest. The Monetary Board shall determine the procedures which shall apply to the acquisition and disposition by the Bangko Sentral of foreign exchange which is not freely utilizable in the international market."}},{"id":"PH-H6134-A74","no":74,"noLabel":{"en":"Section 74."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Exchange Rates. - The Monetary Board shall determine the exchange rate policy of the country.\nThe Monetary Board shall determine the rates at which the Bangko Sentral shall buy and sell spot exchange, and shall establish deviation limits from the effective exchange rate or rates as it may deem proper. The Bangko Sentral shall not collect any additional commissions or charges of any sort, other than actual telegraphic or cable costs incurred by it.\nThe Monetary Board shall similarly determine the rates for other types of foreign exchange transactions by the Bangko Sentral, including purchases and sales of foreign notes and coins, but the margins between the effective exchange rates and the rates thus established may not exceed the corresponding margins for spot exchange transactions by more than the additional costs or expenses involved in each type of transactions."}},{"id":"PH-H6134-A75","no":75,"noLabel":{"en":"Section 75."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Operations with Foreign Entities. - The Monetary Board may authorize the Bangko Sentral to grant loans to and receive loans from foreign banks and other foreign or international entities, both public and private, and may engage in such other operations with these entities as are in the national interest and are appropriate to its character as a central bank. The Bangko Sentral may also act as agent or correspondent for such entities.\nUpon authority of the Monetary Board, the Bangko Sentral may pledge any gold or other assets which it possesses as security against loans which it receives from foreign or international entities.\nREGULATION OF FOREIGN EXCHANGE OPERATIONS OF THE BANKS"}},{"id":"PH-H6134-A76","no":76,"noLabel":{"en":"Section 76."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Foreign Exchange Holdings of the Banks. - In order that the Bangko Sentral may at all times have foreign exchange resources sufficient to enable it to maintain the international stability and convertibility of the peso, or in order to promote the domestic investment of bank resources, the Monetary Board may require the banks to sell to the Bangko Sentral or to other banks all or part of their surplus holdings of foreign exchange. Such transfers may be required for all foreign currencies or for only certain of such currencies, according to the decision of the Monetary Board. The transfers shall be made at the rates established under the provisions of Section 74 of this Act.\nThe Monetary Board may, whenever warranted, determine the net assets and net liabilities of banks and shall, in making such a determination, take into account the bank's networth, outstanding liabilities, actual and contingent, or such other financial or performance ratios as may be appropriate under the circumstances. Any such determination of net assets and net liabilities shall be applied in all banks uniformly and without discrimination."}},{"id":"PH-H6134-A77","no":77,"noLabel":{"en":"Section 77."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Requirement of Balanced Currency Position. - The Monetary Board may require the banks to maintain a balanced position between their assets and liabilities in Philippine pesos or in any other currency or currencies in which they operate. The banks shall be granted a reasonable period of time in which to adjust their currency positions to any such requirement.\nThe powers granted under this section shall be exercised only when special circumstances make such action necessary, in the opinion of the Monetary Board, and shall be applied to all banks alike and without discrimination."}},{"id":"PH-H6134-A78","no":78,"noLabel":{"en":"Section 78."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Regulation of Non-spot Exchange Transactions. - In order to restrain the banks from taking speculative positions with respect to future fluctuations in foreign exchange rates, the Monetary Board may issue such regulations governing bank purchases and sales of non-spot exchange as it may consider necessary for said purpose."}},{"id":"PH-H6134-A79","no":79,"noLabel":{"en":"Section 79."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Other Exchange Profits and Losses. - The banks shall bear the risks of non-compliance with the terms of the foreign exchange documents and instruments which they buy and sell, and shall also bear any other typically commercial or banking risks, including exchange risks not assumed by the Bangko Sentral under the provisions of the preceding section."}},{"id":"PH-H6134-A80","no":80,"noLabel":{"en":"Section 80."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Information on Exchange Operations. - The banks shall report to the Bangko Sentral the volume and composition of their purchases and sales of gold and foreign exchange each day, and must furnish such additional information as the Bangko Sentral may request with reference to the movements in their accounts in foreign currencies.\nThe Monetary Board may also require other persons and entities to report to it currently all transactions or operations in gold, in any shape or form, and in foreign exchange whether entered into or undertaken by them directly or through agents, or to submit such data as may be required on operations or activities giving rise to or in connection with or relating to a gold or foreign exchange transaction. The Monetary Board shall prescribe the forms on which such declarations must be made. The accuracy of the declarations may be verified by the Bangko Sentral by whatever inspection it may deem necessary.\nLOANS TO BANKING AND OTHER FINANCIAL INSTITUTIONS\nA. CREDIT POLICY"}},{"id":"PH-H6134-A81","no":81,"noLabel":{"en":"Section 81."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Guiding Principles. - The rediscounts, discounts, loans and advances which the Bangko Sentral is authorized to extend to banking institutions under the provisions of the present article of this Act shall be used to influence the volume of credit consistent with the objective of price stability. B. NORMAL CREDIT OPERATIONS"}},{"id":"PH-H6134-A82","no":82,"noLabel":{"en":"Section 82."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Authorized Types of Operations. - Subject to the principle stated in the preceding section of this Act, the Bangko Sentral may normally and regularly carry on the following credit operations with banking institutions operating in the Philippines:\n(a) Commercial credits. - The Bangko Sentral may rediscount, discount, buy and sell bills, acceptances, promissory notes and other credit instruments with maturities of not more than one hundred eighty (180) days from the date of their rediscount, discount or acquisition by the Bangko Sentral and resulting from transactions related to:\n(1) the importation, exportation, purchase or sale of readily saleable goods and products, or their transportation within the Philippines; or\n(2) the storing of non-perishable goods and products which are duly insured and deposited, under conditions assuring their preservation, in authorized bonded warehouses or in other places approved by the Monetary Board.\n(b) Production credits. - The Bangko Sentral may rediscount, discount, buy and sell bills, acceptances, promissory notes and other credit instruments having maturities of not more than three hundred sixty (360) days from the date of their rediscount, discount or acquisition by the Bangko Sentral and resulting from transactions related to the production or processing of agricultural, animal, mineral, or industrial products. Documents or instruments acquired in accordance with this subsection shall be secured by a pledge of the respective crops or products: Provided, however, That the crops or products need not be pledged to secure the documents if the original loan granted by the Bangko Sentral is secured by a lien or mortgage on real estate property seventy percent (70%) of the appraised value of which equals or exceeds the amount of the loan granted.\n(c) Other credits. - Special credit instruments not otherwise rediscountable under the immediately preceding subsections (a) and (b) may be eligible for rediscounting in accordance with rules and regulations which the Bangko Sentral shall prescribe. Whenever necessary, the Bangko Sentral shall provide funds from non-inflationary sources: Provided, however, That the Monetary Board shall prescribe additional safeguards for disbursing these funds.\n(d) Advances. - The Bangko Sentral may grant advances against the following kinds of collaterals for fixed periods which, with the exception of advances against collateral named in clause (4) of the present subsection, shall not exceed one hundred eighty (180) days:\n(1) gold coins or bullion;\n(2) securities representing obligations of the Bangko Sentral or of other domestic institutions of recognized solvency;\n(3) the credit instruments to which reference is made in subsection (a) of this section;\n(4) the credit instruments to which reference is made in subsection (b) of this section, for periods which shall not exceed three hundred sixty (360) days;\n(5) utilized portions of advances in current amount covered by regular overdraft agreements related to operations included under subsections (a) and (b) of this section, and certified as to amount and liquidity by the institution soliciting the advance;\n(6) negotiable treasury bills, certificates of indebtedness, notes and other negotiable obligations of the Government maturing within three (3) years from the date of the advance; and\n(7) negotiable bonds issued by the Government of the Philippines, by Philippine provincial, city or municipal governments, or by any Philippine Government instrumentality, and having maturities of not more than ten (10) years from the date of advance.\nThe rediscounts, discounts, loans and advances made in accordance with the provisions of this section may not be renewed or extended unless extraordinary circumstances fully justify such renewal or extension.\nAdvances made against the collateral named in clauses (6) and (7) of subsection (d) of this section may not exceed eighty percent (80%) of the current market value of the collateral. C. SPECIAL CREDIT OPERATION"}},{"id":"PH-H6134-A83","no":83,"noLabel":{"en":"Section 83."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Loans for Liquidity Purposes. - The Bangko Sentral may extend loans and advances to banking institutions for a period of not more than seven (7) days without any collateral for the purpose of providing liquidity to the banking system in times of need. D. EMERGENCY CREDIT OPERATION"}},{"id":"PH-H6134-A84","no":84,"noLabel":{"en":"Section 84."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Emergency Loans and Advances. - In periods of national and/or local emergency or of imminent financial panic which directly threaten monetary and banking stability, the Monetary Board may, by a vote of at least five (5) of its members, authorize the Bangko Sentral to grant extraordinary loans or advances to banking institutions secured by assets as defined hereunder: Provided, That while such loans or advances are outstanding, the debtor institution shall not, except upon prior authorization by the Monetary Board, expand the total volume of its loans or investments.\nThe Monetary Board may, at its discretion, likewise authorize the Bangko Sentral to grant emergency loans or advances to banking institutions, even during normal periods, for the purpose of assisting a bank in a precarious financial condition or under serious financial pressures brought by unforeseen events, or events which, though foreseeable, could not be prevented by the bank concerned: Provided, however, That the Monetary Board has ascertained that the bank is not insolvent and has the assets defined hereunder to secure the advances: Provided, further, That a concurrent vote of at least five (5) members of the Monetary Board is obtained.\nThe amount of any emergency loan or advance shall not exceed the sum of fifty percent (50%) of total deposits and deposit substitutes of the banking institution and shall be disbursed in two (2) or more tranches. The amount of the first tranche shall be limited to twenty-five percent (25%) of the total deposit and deposit substitutes of the institution and shall be secured by government securities to the extent of their applicable loan values and other unencumbered first class collaterals which the Monetary Board may approve: Provided, That if as determined by the Monetary Board, the circumstances surrounding the emergency warrant a loan or advance greater than the amount provided hereinabove, the amount of the first tranche may exceed twenty-five percent (25%) of the bank's total deposit and deposit substitutes if the same is adequately secured by applicable loan values of government securities and unencumbered first class collaterals approved by the Monetary Board, and the principal stockholders of the institution furnish an acceptable undertaking to indemnify and hold harmless from suit a conservator whose appointment the Monetary Board may find necessary at any time.\nPrior to the release of the first tranche, the banking institution shall submit to the Bangko Sentral a resolution of its board of directors authorizing the Bangko Sentral to evaluate other assets of the banking institution certified by its external auditor to be good and available for collateral purposes should the release of the subsequent tranche be thereafter applied for.\nThe Monetary Board may, by a vote of at least five (5) of its members, authorize the release of a subsequent tranche on condition that the principal stockholders of the institution:\n(a) furnish an acceptable undertaking to indemnify and hold harmless from suit a conservator whose appointment the Monetary Board may find necessary at any time; and\n(b) provide acceptable security which, in the judgment of the Monetary Board, would be adequate to supplement, where necessary, the assets tendered by the banking institution to collateralize the subsequent tranche.\nIn connection with the exercise of these powers, the prohibitions in Section 128 of this Act shall not apply insofar as it refers to acceptance as collateral of shares and their acquisition as a result of foreclosure proceedings, including the exercise of voting rights pertaining to said shares: Provided, however, That should the Bangko Sentral acquire any of the shares it has accepted as collateral as a result of foreclosure proceedings, the Bangko Sentral shall dispose of said shares by public bidding within one (1) year from the date of consolidation of title by the Bangko Sentral.\nWhenever a financial institution incurs an overdraft in its account with the Bangko Sentral, the same shall be eliminated within the period prescribed in Section 102 of this Act. E. CREDIT TERMS"}},{"id":"PH-H6134-A85","no":85,"noLabel":{"en":"Section 85."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Interest and Rediscount. - The Bangko Sentral shall collect interest and other appropriate charges on all loans and advances it extends, the closure, receivership or liquidations of the debtor-institution notwithstanding. This provision shall apply prospectively.\nThe Monetary Board shall fix the interest and rediscount rates to be charged by the Bangko Sentral on its credit operations in accordance with the character and term of the operation, but after due consideration has been given to the credit needs of the market, the composition of the Bangko Sentral's portfolio, and the general requirements of the national monetary policy. Interest and rediscount rates shall be applied to all banks of the same category uniformly and without discrimination."}},{"id":"PH-H6134-A86","no":86,"noLabel":{"en":"Section 86."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Endorsement. - The documents rediscounted, discounted, bought or accepted as collateral by the Bangko Sentral in the course of the credit operations authorized in this article shall bear the endorsement of the institution from which they are received."}},{"id":"PH-H6134-A87","no":87,"noLabel":{"en":"Section 87."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Repayment of Credits. - Documents rediscounted, discounted or accepted as collateral by the Bangko Sentral must be withdrawn by the borrowing institution on the dates of their maturities, or upon liquidation of the obligations which they represent or to which they relate whenever said obligations have been liquidated prior to their dates of maturity.\nBanks shall have the right at any time to withdraw any documents which they have presented to the Bangko Sentral as collateral, upon payment in full of the corresponding debt to the Bangko Sentral, including interest charges."}},{"id":"PH-H6134-A88","no":88,"noLabel":{"en":"Section 88."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Other requirements. - The Monetary Board may prescribe, within the general powers granted to it under this Act, additional conditions which borrowing institutions must satisfy in order to have access to the credit of the Bangko Sentral. These conditions may refer to the rates of interest charged by the banks, to the purposes for which their loans in general are destined, and to any other clearly definable aspect of the credit policy of the bank."}},{"id":"PH-H6134-A89","no":89,"noLabel":{"en":"Section 89."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Provisional Advances to the National Government. - The Bangko Sentral may make direct provisional advances with or without interest to the National Government to finance expenditures authorized in its annual appropriation: Provided, That said advances shall be repaid before the end of three (3) months extendible by another three (3) months as the Monetary Board may allow following the date the National Government received such provisional advances and shall not, in their aggregate, exceed twenty percent (20%) of the average annual income of the borrower for the last three (3) preceding fiscal years.\nOPEN MARKET OPERATIONS FOR THE ACCOUNT OF THE BANGKO SENTRAL"}},{"id":"PH-H6134-A90","no":90,"noLabel":{"en":"Section 90."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Principles of Open Market Operations. - The open market purchases and sales of securities by the Bangko Sentral shall be made exclusively in accordance with its primary objective of achieving price stability."}},{"id":"PH-H6134-A91","no":91,"noLabel":{"en":"Section 91."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Purchases and Sales of Government Securities. - In order to achieve the objectives of the national monetary policy, the Bangko Sentral may, in accordance with the principle stated in Section 90 of this Act and with such rules and regulations as may be prescribed by the Monetary Board, buy and sell in the open market for its own account:\n(a) evidences of indebtedness issued directly by the Government of the Philippines or by its political subdivisions; and\n(b) evidences of indebtedness issued by government instrumentalities and fully guaranteed by the Government.\nThe evidences of indebtedness acquired under the provisions of this section must be freely negotiable and regularly serviced and must be available to the general public through banking institutions and local government treasuries in denominations of a thousand pesos or more."}},{"id":"PH-H6134-A92","no":92,"noLabel":{"en":"Section 92."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Issue and Negotiation of Bangko Sentral Obligations. - In order to provide the Bangko Sentral with effective instruments for open market operations, the Bangko Sentral may, subject to such rules and regulations as the Monetary Board may prescribe and in accordance with the principles stated in Section 90 of this Act, issue, place, buy and sell freely negotiable evidences of indebtedness of the Bangko Sentral: Provided, That issuance of such certificates of indebtedness shall be made only in cases of extraordinary movement in price levels. Said evidences of indebtedness may be issued directly against the international reserve of the Bangko Sentral or against the securities which it has acquired under the provisions of Section 91 of this Act, or may be issued without relation to specific types of assets of the Bangko Sentral.\nThe Monetary Board shall determine the interest rates, maturities and other characteristics of said obligations of the Bangko Sentral, and may, if it deems it advisable, denominate the obligations in gold or foreign currencies.\nSubject to the principles stated in Section 90 of this Act, the evidences of indebtedness of the Bangko Sentral to which this section refers may be acquired by the Bangko Sentral before their maturity, either through purchases in the open market or through redemptions at par and by lot if the Bangko Sentral has reserved the right to make such redemptions. The evidences of indebtedness acquired or redeemed by the Bangko Sentral shall not be included among its assets, and shall be immediately retired and cancelled.\nCOMPOSITION OF BANGKO SENTRAL'S PORTFOLIO"}},{"id":"PH-H6134-A93","no":93,"noLabel":{"en":"Section 93."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Review of the Bangko Sentral's Portfolio. - At least once every month the Monetary Board shall review the portfolio of the Bangko Sentral in relation to its future credit policy.\nIn reviewing the Bangko Sentral's portfolio, the Monetary Board shall especially consider whether a sufficiently large part of the portfolio consists of assets with early maturities, in order that a contraction in Bangko Sentral credit may be effected promptly whenever the national monetary policy so requires.\nBANK RESERVES"}},{"id":"PH-H6134-A94","no":94,"noLabel":{"en":"Section 94."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Reserve Requirements. - In order to control the volume of money created by the credit operations of the banking system, all banks operating in the Philippines shall be required to maintain reserves against their deposit liabilities: Provided, That the Monetary Board may, at its discretion, also require all banks and/or quasi-banks to maintain reserves against funds held in trust and liabilities for deposit substitutes as defined in this Act. The required reserves of each bank shall be proportional to the volume of its deposit liabilities and shall ordinarily take the form of a deposit in the Bangko Sentral. Reserve requirements shall be applied to all banks of the same category uniformly and without discrimination.\nReserves against deposit substitutes, if imposed, shall be determined in the same manner as provided for reserve requirements against regular bank deposits, with respect to the imposition, increase, and computation of reserves.\nThe Monetary Board may exempt from reserve requirements deposits and deposit substitutes with remaining maturities of two (2) years or more, as well as interbank borrowings.\nSince the requirement to maintain bank reserves is imposed primarily to control the volume of money, the Bangko Sentral shall not pay interest on the reserves maintained with it unless the Monetary Board decides otherwise as warranted by circumstances."}},{"id":"PH-H6134-A95","no":95,"noLabel":{"en":"Section 95."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Definition of Deposit Substitutes. - The term \"deposit substitutes\" is defined as an alternative form of obtaining funds from the public, other than deposits, through the issuance, endorsement, or acceptance of debt instruments for the borrower's own account, for the purpose of relending or purchasing of receivables and other obligations. These instruments may include, but need not be limited to, bankers acceptances, promissory notes, participations, certificates of assignment and similar instruments with recourse, and repurchase agreements. The Monetary Board shall determine what specific instruments shall be considered as deposit substitutes for the purposes of Section 94 of this Act: Provided, however, That deposit substitutes of commercial, industrial and other non-financial companies for the limited purpose of financing their own needs or the needs of their agents or dealers shall not be covered by the provisions of Section 94 of this Act."}},{"id":"PH-H6134-A96","no":96,"noLabel":{"en":"Section 96."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Required Reserves Against Peso Deposits. - The Monetary Board may fix and, when it deems necessary, alter the minimum reserve ratios to peso deposits, as well as to deposit substitutes, which each bank and/or quasi-bank may maintain, and such ratio shall be applied uniformly to all banks of the same category as well as to quasi-banks."}},{"id":"PH-H6134-A97","no":97,"noLabel":{"en":"Section 97."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Required Reserves Against Foreign Currency Deposits. - The Monetary Board is similarly authorized to prescribe and modify the minimum reserve ratios applicable to deposits denominated in foreign currencies."}},{"id":"PH-H6134-A98","no":98,"noLabel":{"en":"Section 98."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Reserves Against Unused Balances of Overdraft Lines. - In order to facilitate Bangko Sentral control over the volume of bank credit, the Monetary Board may establish minimum reserve requirements for unused balances of overdraft lines.\nThe powers of the Monetary Board to prescribe and modify reserve requirements against unused balances of overdraft lines shall be the same as its powers with respect to reserve requirements against demand deposits."}},{"id":"PH-H6134-A99","no":99,"noLabel":{"en":"Section 99."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Increase in Reserve Requirements. - Whenever in the opinion of the Monetary Board it becomes necessary to increase reserve requirements against existing liabilities, the increase shall be made in a gradual manner and shall not exceed four percentage points in any thirty-day period. Banks and other affected financial institutions shall be notified reasonably in advance of the date on which such increase is to become effective."}},{"id":"PH-H6134-A100","no":100,"noLabel":{"en":"Section 100."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Computation on Reserves. - The reserve position of each bank or quasi-bank shall be calculated daily on the basis of the amount, at the close of business for the day, of the institution's reserves and the amount of its liability accounts against which reserves are required to be maintained: Provided, That with reference to holidays or non-banking days, the reserve position as calculated at the close of the business day immediately preceding such holidays and non-banking days shall apply on such days.\nFor the purpose of computing the reserve position of each bank or quasi-bank, its principal office in the Philippines and all its branches and agencies located therein shall be considered as a single unit."}},{"id":"PH-H6134-A101","no":101,"noLabel":{"en":"Section 101."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Reserve Deficiencies. - Whenever the reserve position of any bank or quasi-bank, computed in the manner specified in the preceding section of this Act, is below the required minimum, the bank or quasi-bank shall pay the Bangko Sentral one-tenth of one percent (1/10 of 1%) per day on the amount of the deficiency or the prevailing ninety-one-day treasury bill rate plus three percentage points, whichever is higher: Provided, however, That banks and quasi-banks shall ordinarily be permitted to offset any reserve deficiency occurring on one or more days of the week with any excess reserves which they may hold on other days of the same week and shall be required to pay the penalty only on the average daily deficiency during the week. In cases of abuse, the Monetary Board may deny any bank or quasi-bank the privilege of offsetting reserve deficiencies in the aforesaid manner.\nIf a bank or quasi-bank chronically has a reserve deficiency, the Monetary Board may limit or prohibit the making of new loans or investments by the institution and may require that part or all of the net profits of the institution be assigned to surplus.\nThe Monetary Board may modify or set aside the reserve deficiency penalties provided in this section, for part or the entire period of a strike or lockout affecting a bank or a quasi-bank as defined in the Labor Code, or of a national emergency affecting operations of banks or quasi-banks. The Monetary Board may also modify or set aside reserved deficiency penalties for rehabilitation program of a bank."}},{"id":"PH-H6134-A102","no":102,"noLabel":{"en":"Section 102."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Interbank Settlement. - The Bangko Sentral shall establish facilities for interbank clearing under such rules and regulations as the Monetary Board may prescribe: Provided, That the Bangko Sentral may charge administrative and other fees for the maintenance of such facilities.\nThe deposit reserves maintained by the banks in the Bangko Sentral in accordance with the provisions of Section 94 of this Act shall serve as basis for the clearing of checks and the settlement of interbank balances, subject to such rules and regulations as the Monetary Board may issue with respect to such operations: Provided, That any bank which incurs on overdrawing in its deposit account with the Bangko Sentral shall fully cover said overdraft, including interest thereon at a rate equivalent to one-tenth of one percent (1/10 of 1%) per day or the prevailing ninety-one-day treasury bill rate plus three percentage points, whichever is higher, not later than the next clearing day: Provided, further, That settlement of clearing balances shall not be effected for any account which continues to be overdrawn for five (5) consecutive banking days until such time as the overdrawing is fully covered or otherwise converted into an emergency loan or advance pursuant to the provisions of Section 84 of this Act: Provided, finally, That the appropriate clearing office shall be officially notified of banks with overdrawn balances. Banks with existing overdrafts with the Bangko Sentral as of the effectivity of this Act shall, within such period as may be prescribed by the Monetary Board, either convert the overdraft into an emergency loan or advance with a plan of payment, or settle such overdrafts, and that, upon failure to so comply herewith, the Bangko Sentral shall take such action against the bank as may be warranted under this Act."}},{"id":"PH-H6134-A103","no":103,"noLabel":{"en":"Section 103."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Exemption from Attachment and Other Purposes. - Deposits maintained by banks with the Bangko Sentral as part of their reserve requirements shall be exempt from attachment, garnishments, or any other order or process of any court, government agency or any other administrative body issued to satisfy the claim of a party other than the Government, or its political subdivisions or instrumentalities.\nSELECTIVE REGULATION OF BANK OPERATIONS"}},{"id":"PH-H6134-A104","no":104,"noLabel":{"en":"Section 104."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"Guiding Principle. - The Monetary Board shall use the powers granted to it under this Act to ensure that the supply, availability and cost of money are in accord with the needs of the Philippine economy and that bank credit is not granted for speculative purposes prejudicial to the national interests. Regulations on bank operations shall be applied to all banks of the same category uniformly and without discrimination."}},{"id":"PH-H6134-A105","no":105,"noLabel":{"en":"Section 105."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"Margin Requirements Against Letters of Credit. - The Monetary Board may at any time prescribe minimum cash margins for the opening of letters of credit, and may relate the size of the required margin to the nature of the transaction to be financed."}},{"id":"PH-H6134-A106","no":106,"noLabel":{"en":"Section 106."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"Required Security Against Bank Loans. - In order to promote liquidity and solvency of the banking system, the Monetary Board may issue such regulations as it may deem necessary with respect to the maximum permissible maturities of the loans and investments which the banks may make, and the kind and amount of security to be required against the various types of credit operations of the banks."}},{"id":"PH-H6134-A107","no":107,"noLabel":{"en":"Section 107."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"Portfolio Ceilings. - Whenever the Monetary Board considers it advisable to prevent or check an expansion of bank credit, the Board may place an upper limit on the amount of loans and investments which the banks may hold, or may place a limit on the rate of increase of such assets within specified periods of time. The Monetary Board may apply such limits to the loans and investments of each bank or to specific categories thereof.\nIn no case shall the Monetary Board establish limits which are below the value of the loans or investments of the banks on the date on which they are notified of such restrictions. The restrictions shall be applied to all banks uniformly and without discrimination."}},{"id":"PH-H6134-A108","no":108,"noLabel":{"en":"Section 108."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"Minimum Capital Ratios. - The Monetary Board may prescribe minimum ratios which the capital and surplus of the banks must bear to the volume of their assets, or to specific categories thereof, and may alter said ratios whenever it deems necessary.\nCOORDINATION OF CREDIT POLICIES BY GOVERNMENT INSTITUTIONS"}},{"id":"PH-H6134-A109","no":109,"noLabel":{"en":"Section 109."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Coordination of Credit Policies. - Government-owned corporations which perform banking or credit functions shall coordinate their general credit policies with those of the Monetary Board.\nToward this end, the Monetary Board may, whenever it deems it expedient, make suggestions or recommendations to such corporations for the more effective coordination of their policies with those of the Bangko Sentral.\nFUNCTIONS AS BANKER OF THE GOVERNMENT"}},{"id":"PH-H6134-A110","no":110,"noLabel":{"en":"Section 110."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Designation of Bangko Sentral as Banker of the Government. - The Bangko Sentral shall act as a banker of the Government, its political subdivisions and instrumentalities."}},{"id":"PH-H6134-A111","no":111,"noLabel":{"en":"Section 111."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Representation with the International Monetary Fund. - The Bangko Sentral shall represent the Government in all dealings, negotiations and transactions with the International Monetary Fund and shall carry such accounts as may result from Philippine membership in, or operations with, said Fund."}},{"id":"PH-H6134-A112","no":112,"noLabel":{"en":"Section 112."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Representation with Other Financial Institutions. - The Bangko Sentral may be authorized by the Government to represent it in dealings, negotiations or transactions with the International Bank for Reconstruction and Development and with other foreign or international financial institutions or agencies. The President may, however, designate any of his other financial advisors to jointly represent the Government in such dealings, negotiations or transactions."}},{"id":"PH-H6134-A113","no":113,"noLabel":{"en":"Section 113."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Official Deposits. - The Bangko Sentral shall be the official depository of the Government, its political subdivisions and instrumentalities as well as of government-owned or controlled corporations and, as a general policy, their cash balances should be deposited with the Bangko Sentral, with only minimum working balances to be held by government-owned banks and such other banks incorporated in the Philippines as the Monetary Board may designate, subject to such rules and regulations as the Board may prescribe: Provided, That such banks may hold deposits of the political subdivisions and instrumentalities of the Government beyond their minimum working balances whenever such subdivisions or instrumentalities have outstanding loans with said banks.\nThe Bangko Sentral may pay interest on deposits of the Government or of its political subdivisions and instrumentalities, as well as on deposits of banks with the Bangko Sentral."}},{"id":"PH-H6134-A114","no":114,"noLabel":{"en":"Section 114."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Fiscal Operations. - The Bangko Sentral shall open a general cash account for the Treasurer of the Philippines, in which the liquid funds of the Government shall be deposited.\nTransfers of funds from this account to other accounts shall be made only upon order of the Treasurer of the Philippines."}},{"id":"PH-H6134-A115","no":115,"noLabel":{"en":"Section 115."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Other Banks as Agents of the Bangko Sentral. - In the performance of its functions as fiscal agent, the Bangko Sentral may engage the services of other government-owned and controlled banks and of other domestic banks for operations in localities at home or abroad in which the Bangko Sentral does not have offices or agencies adequately equipped to perform said operations: Provided, however, That for fiscal operations in foreign countries, the Bangko Sentral may engage the services of foreign banking and financial institutions."}},{"id":"PH-H6134-A116","no":116,"noLabel":{"en":"Section 116."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Remuneration for Services. - The Bangko Sentral may charge equitable rates, commissions or fees for services which it renders to the Government, its political subdivisions and instrumentalities.\nTHE MARKETING AND STABILIZATION OF SECURITIES FOR THE ACCOUNT OF THE GOVERNMENT\nA. THE ISSUE AND PLACING OF GOVERNMENT SECURITIES"}},{"id":"PH-H6134-A117","no":117,"noLabel":{"en":"Section 117."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Issue of Government Obligations. - The issue of securities representing obligations of the Government, its political subdivisions or instrumentalities, may be made through the Bangko Sentral, which may act as agent of, and for the account of, the Government or its respective subdivisions or instrumentality, as the case may be: Provided, however, That the Bangko Sentral shall not guarantee the placement of said securities, and shall not subscribe to their issue except to replace its maturing holdings of securities with the same type as the maturing securities."}},{"id":"PH-H6134-A118","no":118,"noLabel":{"en":"Section 118."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Methods of Placing Government Securities. - The Bangko Sentral may place the securities to which the preceding section refers through direct sale to financial institutions and the public.\nThe Bangko Sentral shall not be a member of any stock exchange or syndicate, but may intervene therein for the sole purpose of regulating their operations in the placing of government securities.\nThe Government, or its political subdivisions or instrumentalities, shall reimburse the Bangko Sentral for the expenses incurred in the placing of the aforesaid securities."}},{"id":"PH-H6134-A119","no":119,"noLabel":{"en":"Section 119."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Servicing and Redemption of the Public Debt. - The servicing and redemption of the public debt shall also be effected through the Bangko Sentral. B. BANGKO SENTRAL SUPPORT OF THE GOVERNMENT SECURITIES MARKET"}},{"id":"PH-H6134-A120","no":120,"noLabel":{"en":"Section 120."},"chapter":{"en":"ARTICLE II"},"text":{"en":"The Securities Stabilization Fund. - There shall be established a \"Securities Stabilization Fund\" which shall be administered by the Bangko Sentral for the account of the Government.\nThe operations of the Securities Stabilization Fund shall consist of purchases and sales, in the open market, of bonds and other evidences of indebtedness issued or fully guaranteed by the Government. The purpose of these operations shall be to increase the liquidity and stabilize the value of said securities in order thereby to promote investment in government obligations.\nThe Monetary Board shall use the resources of the Fund to prevent, or moderate, sharp fluctuations in the quotations of said government obligations, but shall not endeavor to alter movements of the market resulting from basic changes in the pattern or level of interest rates.\nThe Monetary Board shall issue such regulations as may be necessary to implement the provisions of this section."}},{"id":"PH-H6134-A121","no":121,"noLabel":{"en":"Section 121."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Resources of the Securities Stabilization Fund. - Subject to Section 132 of this Act, the resources of the Securities Stabilization Fund shall come from the balance of the fund as held by the Central Bank under Republic Act No. 265 as of the effective date of this Act."}},{"id":"PH-H6134-A122","no":122,"noLabel":{"en":"Section 122."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Profits and Losses of the Fund. - The Securities Stabilization Fund shall retain net profits which it may make on its operations, regardless of whether said profits arise from capital gains or from interest earnings. The Fund shall correspondingly bear any net losses which it may incur.\nFUNCTIONS AS FINANCIAL ADVISOR OF THE GOVERNMENT"}},{"id":"PH-H6134-A123","no":123,"noLabel":{"en":"Section 123."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Financial Advice on Official Credit Operations. - Before undertaking any credit operation abroad, the Government, through the Secretary of Finance, shall request the opinion, in writing, of the Monetary Board on the monetary implications of the contemplated action. Such opinions must similarly be requested by all political subdivisions and instrumentalities of the Government before any credit operation abroad is undertaken by them.\nThe opinion of the Monetary Board shall be based on the gold and foreign exchange resources and obligations of the nation and on the effects of the proposed operation on the balance of payments and on monetary aggregates.\nWhenever the Government, or any of its political subdivisions or instrumentalities, contemplates borrowing within the Philippines, the prior opinion of the Monetary Board shall likewise be requested in order that the Board may render an opinion on the probable effects of the proposed operation on monetary aggregates, the price level, and the balance of payments."}},{"id":"PH-H6134-A124","no":124,"noLabel":{"en":"Section 124."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Representation on the National Economic and Development Authority. - In order to assure effective coordination between the economic, financial and fiscal policies of the Government and the monetary, credit and exchange policies of the Bangko Sentral, the Deputy Governor designated by the Governor of the Bangko Sentral shall be an ex officio member of the National Economic and Development Authority Board.\nPRIVILEGES"}},{"id":"PH-H6134-A125","no":125,"noLabel":{"en":"Section 125."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Tax Exemptions. - The Bangko Sentral shall be exempt for a period of five (5) years from the approval of this Act from all national, provincial, municipal and city taxes, fees, charges and assessments.\nThe exemption authorized in the preceding paragraph of this section shall apply to all property of the Bangko Sentral, to the resources, receipts, expenditures, profits and income of the Bangko Sentral, as well as to all contracts, deeds, documents and transactions related to the conduct of the business of the Bangko Sentral: Provided, however, That said exemptions shall apply only to such taxes, fees, charges and assessments for which the Bangko Sentral itself would otherwise be liable, and shall not apply to taxes, fees, charges, or assessments payable by persons or other entities doing business with the Bangko Sentral: Provided, further, That foreign loans and other obligations of the Bangko Sentral shall be exempt, both as to principal and interest, from any and all taxes if the payment of such taxes has been assumed by the Bangko Sentral."}},{"id":"PH-H6134-A126","no":126,"noLabel":{"en":"Section 126."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Exemption from Customs Duties. - The provision of any general or special law to the contrary notwithstanding, the importation and exportation by the Bangko Sentral of notes and coins, and of gold and other metals to be used for purposes authorized under this Act, and the importation of all equipment needed for bank note production, minting of coins, metal refining and other security printing operations shall be fully exempt from all customs duties and consular fees and from all other taxes, assessments and charges related to such importation or exportation."}},{"id":"PH-H6134-A127","no":127,"noLabel":{"en":"Section 127."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Applicability of the Civil Service Law. - Appointments in the Bangko Sentral, except as to those which are policy-determining, primarily confidential or highly technical in nature, shall be made only according to the Civil Service Law and regulations: Provided, That no qualification requirements for positions in the Bangko Sentral shall be imposed other than those set by the Monetary Board: Provided, further, That, the Monetary Board or Governor, in accordance with Sections 15(c) and 17(d) of this Act, respectively, may without need of obtaining prior approval from any other government agency, appoint personnel in the Bangko Sentral whose services are deemed necessary in order not to unduly disrupt the operations of the Bangko Sentral.\nOfficers and employees of the Bangko Sentral, including all members of the Monetary Board, shall not engage directly or indirectly in partisan activities or take part in any election except to vote.\nPROHIBITIONS"}},{"id":"PH-H6134-A128","no":128,"noLabel":{"en":"Section 128."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Prohibitions. - The Bangko Sentral shall not acquire shares of any kind or accept them as collateral, and shall not participate in the ownership or management of any enterprise, either directly or indirectly.\nThe Bangko Sentral shall not engage in development banking or financing: Provided, however, That outstanding loans obtained or extended for development financing shall not be affected by the prohibition of this section."}},{"id":"PH-H6134-A129","no":129,"noLabel":{"en":"Section 129."},"chapter":{"en":"CHAPTER VII — TRANSITORY PROVISIONS"},"text":{"en":"Phase-out of Fiscal Agency Functions. - Unless circumstances warrant otherwise and approved by the Congress Oversight Committee, the Bangko Sentral shall, within a period of three (3) years but in no case longer than five (5) years from the approval of this Act, phase out all fiscal agency functions provided for in Sections 117, 118, 119, and 120 as well as in other pertinent provisions of this Act and transfer the same to the Department of Finance."}},{"id":"PH-H6134-A130","no":130,"noLabel":{"en":"Section 130."},"chapter":{"en":"CHAPTER VII — TRANSITORY PROVISIONS"},"text":{"en":"Phase-out of Regulatory Powers Over the Operations of Finance Corporations and Other Institutions Performing Similar Functions. - The Bangko Sentral shall, within a period of five (5) years from the effectivity of this Act, phase out its regulatory powers over finance companies without quasi-banking functions and other institutions performing similar functions as provided in existing laws, the same to be assumed by the Securities and Exchange Commission."}},{"id":"PH-H6134-A131","no":131,"noLabel":{"en":"Section 131."},"chapter":{"en":"CHAPTER VII — TRANSITORY PROVISIONS"},"text":{"en":"Implementing Details. - The Bangko Sentral shall be made operational by the performance of the following acts:\n(a) the President shall constitute the Monetary Board by appointing the members thereof within sixty (60) days from the effectivity of this Act; and\n(b) the transfer of such assets and liabilities from the Central Bank to the Bangko Sentral as provided in Section 132 shall be completed within ninety (90) days from the constitution of the Monetary Board.\nAll incumbent personnel in the Central Bank as of the date of the approval of this Act shall continue to exercise their duties and functions as personnel of the Bangko Sentral subject to the provisions of Section 133: Provided, That such personnel in the Central Bank as may be necessary for the purpose of implementing Section 132 may be assigned by the Bangko Sentral Monetary Board to the Central Bank."}},{"id":"PH-H6134-A132","no":132,"noLabel":{"en":"Section 132."},"chapter":{"en":"CHAPTER VII — TRANSITORY PROVISIONS"},"text":{"en":"Transfer of Assets and Liabilities. - Upon the effectivity of this Act, three (3) members of the Monetary Board, which may include the Governor, in representation of the Bangko Sentral, the Secretary of Finance and the Secretary of Budget and Management in representation of the National Government, and the Chairmen of the Committees on Banks of the Senate and the House of Representatives shall determine the assets and liabilities of the Central Bank which may be transferred to or assumed by the Bangko Sentral. The Committee shall complete its work within ninety (90) days from the constitution of the Monetary Board submitting a comprehensive report with all its findings and justification.\nThe following guidelines shall be strictly observed in the determination of which assets and liabilities shall be transferred to the Bangko Sentral:\n(a) the Monetary Board and the Secretary of Finance shall have primary responsibility for working out creative monetary and financial solutions to retire the Central Bank liabilities and losses at the least cost to the Government;\n(b) the Bangko Sentral shall remit seventy-five percent (75%) of its net profits to a special deposit account (sinking fund) until such time as the net liabilities of the Central Bank shall have been liquidated through generally accepted finance mechanisms such as, but not limited to, write-offs, set-offs, condonation, collections, reappraisal, revaluation and bond issuance by the National Government, or to the National Government as dividends;\n(c) the assets and liabilities to be transferred shall be limited to an amount that will enable the Bangko Sentral to perform its responsibilities adequately and operate on a viable basis: Provided, That the assets shall exceed the liabilities as certified by the Commission on Audit (COA), by an initial amount of Ten billion pesos (P10,000,000,000);\n(d) liabilities to be assumed by the Bangko Sentral shall include liability for notes and coins in circulation as of the effective date of this Act; and\n(e) any asset or liability of the Central Bank not transferred to the Bangko Sentral shall be retained and administered, disposed of and liquidated by the Central Bank itself which shall continue to exist as the CB Board of Liquidators only for the purposes provided in this paragraph but not later than twenty-five (25) years or until such time that liabilities have been liquidated: Provided, That the Bangko Sentral may financially assist the Central Bank of Liquidators in the liquidation of CB liabilities: Provided, finally, That upon disposition of said retained assets and liquidation of said retained liabilities, the Central Bank shall be deemed abolished.\nAll actions taken by the Bangko Sentral Monetary Board under this section shall be reported to Congress and the President within thirty (30) days."}},{"id":"PH-H6134-A133","no":133,"noLabel":{"en":"Section 133."},"chapter":{"en":"CHAPTER VII — TRANSITORY PROVISIONS"},"text":{"en":"Mandate to Organize. - The Bangko Sentral shall be organized by the Monetary Board without being subject to the provisions of Republic Act No. 7430, by adopting if it so desires, an entirely new staffing pattern on organizational structure to suit the operations of the Bangko Sentral under this Act. No preferential or priority right shall be given to or enjoyed by any personnel for appointment to any position in the new staffing pattern, nor shall any personnel be considered as having prior or vested rights with respect to retention in the Bangko Sentral or in any position which may be created in the new staffing pattern, even if he should be the incumbent of a similar position prior to organization. The formulation of the program of organization shall be completed within six (6) months after the effectivity of this Act, and shall be fully implemented within a period of six (6) months thereafter. Personnel who may not be retained are deemed separated from the service."}},{"id":"PH-H6134-A134","no":134,"noLabel":{"en":"Section 134."},"chapter":{"en":"CHAPTER VII — TRANSITORY PROVISIONS"},"text":{"en":"Separation Benefits. - Pursuant to Section 15 of this Act, the Monetary Board is authorized to provide separation incentives, and all those who shall retire or be separated from the service on account of reorganization under the preceding section shall be entitled to such incentives, which shall be in addition to all gratuities and benefits to which they may be entitled under existing laws."}},{"id":"PH-H6134-A135","no":135,"noLabel":{"en":"Section 135."},"chapter":{"en":"CHAPTER VII — TRANSITORY PROVISIONS"},"text":{"en":"Repealing Clause. - Except as may be provided for in Section 46 and 132 of this Act, Republic Act No. 265, as amended, the provisions of any other law, special charters, rule or regulation issued pursuant to said Republic Act No. 265, as amended, or parts thereof, which may be inconsistent with the provisions of this Act are hereby repealed. Presidential Decree No. 1792 is likewise repealed."}},{"id":"PH-H6134-A136","no":136,"noLabel":{"en":"Section 136."},"chapter":{"en":"CHAPTER VII — TRANSITORY PROVISIONS"},"text":{"en":"Transfer of Powers. - All powers, duties and functions vested by law in the Central Bank of the Philippines not inconsistent with the provisions of this Act shall be deemed transferred to the Bangko Sentral ng Pilipinas. All references to the Central Bank of the Philippines in any law or special charters shall be deemed to refer to the Bangko Sentral."}},{"id":"PH-H6134-A137","no":137,"noLabel":{"en":"Section 137."},"chapter":{"en":"CHAPTER VII — TRANSITORY PROVISIONS"},"text":{"en":"Separability Clause. - If any provision or section of this Act or the application thereof to any person or circumstance is held invalid, the other provisions or sections of this Act, and the application of such provision or section to other persons or circumstances, shall not be affected thereby."}},{"id":"PH-H6134-A138","no":138,"noLabel":{"en":"Section 138."},"chapter":{"en":"CHAPTER VII — TRANSITORY PROVISIONS"},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days following its publication in the Official Gazette or in two (2) national newspapers of general circulation.\nApproved: June 14, 1993"}}],"pack":"ph-p87"};
  FT["PH-H6135"] = {"id":"PH-H6135","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7654_1993.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"修订消费税税基、将增收部分拨给特定工人的紧急就业计划，为此修订经修正的《国家国内税收法典》第 142 条并为其他目的法案","en":"An Act Revising the Excise Tax Base, Allocating a Portion of the Incremental Revenue Collected for the Emergency Employment Program for Certain Workers Amending for the Purpose Section 142 of the National Internal Revenue Code, as Amended, and for Other Purposes","orig":"An Act Revising the Excise Tax Base, Allocating a Portion of the Incremental Revenue Collected for the Emergency Employment Program for Certain Workers Amending for the Purpose Section 142 of the National Internal Revenue Code, as Amended, and for Other Purposes"},"level":"law","status":"active","topics":["labor","tax"],"docNumber":"Republic Act No. 7654","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-06-14","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7654_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6135-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 142 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 142. Cigars and cigarettes. - \"(a) Cigars. - There shall be levied, assessed and collected on cigars a tax of ten percent (10%) of the constructive manufacturer's or importer's wholesale price or the actual manufacturer's or importer's wholesale price, whichever is higher.\n\"(b) Cigarettes packed by hand. - There shall be levied, assessed and collected on cigarettes packed by hand a tax of fifteen percent (15%) of the constructive manufacturer's wholesale price or the actual manufacturer's wholesale price, whichever is higher.\n\"(c) Cigarettes packed by machine. - There shall be levied, assessed and collected on cigarettes packed by machine a tax at the rates prescribed below based on the constructive manufacturer's wholesale price or the actual manufacturer's wholesale price, whichever is higher:\n\"(1) On locally manufactured cigarettes which are currently classified and taxed at fifty-five percent (55%) or the exportation of which is not authorized by contract or otherwise, fifty-five percent (55%) provided that the minimum tax shall not be less than Five pesos (₱5.00) per pack.\n\"(2) On other locally manufactured cigarettes, forty-five percent (45%) provided that the minimum tax shall not be less than Three pesos (₱3.00) per pack.\nDuly registered or existing brands of cigarettes or new brands thereof packed by machine shall only be packed in twenties.\nWhen the registered manufacturer's wholesale price or the actual manufacturer's wholesale price whichever is higher of existing brands of cigarettes, including the amounts intended to cover the taxes, of cigarettes packed in twenties does not exceed Four pesos and eighty centavos (₱4.80) per pack, the rate shall be twenty percent (20%).\n\"(d) Imported cigarettes. — If the cigarettes are of foreign manufacture, regardless of the contents per pack, there shall be levied, assessed and collected a tax of fifty-five percent (55%) of the constructive importer's wholesale price or the actual importer's wholesale price, whichever is higher.\n\"For purposes of this section, the term 'constructive manufacturer's or importer's wholesale price' shall mean the price including the amount intended to cover the tax imposed in paragraphs (a), (b), (c) or (d) hereof and the amount intended to cover the value-added tax imposed under Title IV of this Code at which locally manufactured or imported cigars or cigarettes are offered for sale to the wholesalers or distributors as fixed by the manufacturer or importer and registered with the Bureau of Internal Revenue plus a mark up of twenty percent (20%) of such price. The term 'actual manufacturer's or importer's wholesale price' shall mean the price at which the purchaser actually pays or is obligated to pay to the manufacturer or importer in consideration of the sale, barter, or exchange of cigars and cigarettes.\n\"The twenty percent (20%) mark up and the minimum taxes provided in this section shall be automatically increased in 1996 by ten percent (10%).\n\"Manufacturers and importers of cigars and cigarettes shall, within thirty (30) days from the effectivity of this Act, submit to the Commissioner of Internal Revenue a sworn statement of the manufacturer's or importer's wholesale price of each particular brand of their products, and periodically thereafter, a sworn written notification of any change thereof.\n\"Any downward reclassification of present categories, for tax purposes, of existing brands of cigars or cigarettes duly registered with the Bureau of Internal Revenue at the time of the effectivity of this Act or any reduction or undervaluation of the manufacturer's or importer's registered wholesale price or any violation of this section which will reduce the tax imposed herein, or the payment thereof, shall be prohibited.\n\"Any manufacturer or importer who, in violation of this section, knowingly misdeclares or misrepresents in his or its sworn statement herein required any pertinent data or information or reduces or undervalues or downgrades the classification of any existing brand of cigars and cigarettes duly registered with the Bureau of Internal Revenue at the time of the effectivity of this Act shall, upon discovery, be penalized by a summary cancellation or withdrawal of his or its permit to engage in business as manufacturer or importer of cigars or cigarettes.\n\"Any corporation, association, or partnership liable for any of the acts or omissions in violation of this section shall be fined treble the amount of deficiency taxes, surcharges, and interests which may be assessed pursuant to this section.\n\"Any person liable for any of the acts or omissions prohibited under this section shall be criminally liable and penalized under Section 253 of this Code. Any person who willfully aids or abets in the commission of any such act or omission shall be criminally liable in the same manner as the principal.\n\"If the offender is not a citizen of the Philippines, he shall be deported immediately after serving the sentence without further proceedings for deportation.\""}},{"id":"PH-H6135-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The wholesale price of cigars and cigarettes at which they are offered for sale to the wholesalers or distributors and registered with the Bureau of Internal Revenue as of December 31, 1992 shall be deemed the manufacturer's or importer's registered wholesale price until the submission by the manufacturer or importer of the sworn statement as required under Section 1 of this Act: Provided, That a variant of an existing brand of cigars or cigarettes that shall be manufactured after the effectivity of this Act shall be taxed at the same level as the main brand regardless of its declared wholesale price: Provided, further, That to prevent any underpayment of taxes, any new brand of cigars or cigarettes with comparable quality, blend, cost of production and other relevant facts as brands with a registered wholesale price of Three pesos (P3.00) or more per pack, and which shall be manufactured after the effectivity of this Act, shall be taxed at the highest rate regardless of its declared wholesale price. For the purpose of this section, cigars or cigarettes registered with the Bureau of Internal Revenue after May 31, 1993 shall be treated as new brands."}},{"id":"PH-H6135-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Fifty percent (50%) of the increment in total revenue collected under this Act for a period of one (1) year from its effectivity shall be allocated and disbursed solely for purposes of providing emergency productive employment to workers displaced by the present electricity power crisis. For this purpose, the Secretary of Labor and Employment, in consultation with the Secretary of Finance, shall promulgate the necessary rules and regulations for the effective implementation of this section.\nProvided, likewise, That twenty-five percent (25%) of the increment in total revenue collected under this Act in 1995 shall be collected and segregated as a trust fund to be disbursed solely for funding the national health insurance program as may be hereafter mandated by law."}},{"id":"PH-H6135-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The incremental revenue collected under this Act shall be excluded from the revenue base as provided under Republic Act No. 7171."}},{"id":"PH-H6135-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Secretary of Finance shall, upon the recommendation of the Commissioner of Internal Revenue, promulgate the necessary rules and regulations within six (6) months from the effectivity of this Act."}},{"id":"PH-H6135-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Bureau of Internal Revenue shall adopt any or all of the following measures:\n1. Affixture of internal revenue fuson stamps. — Internal revenue fuson stamps without denomination or class, shall be firmly and conspicuously affixed on any part of the packages containing the cigarettes as the manufacturer may deem it fit before said packages are packed in cases for removal from the factory. The affixture must be done in such a manner that will prevent said fuson stamps from being removed and re-used by washing or any other means and from covering any warning that may be hereafter required by law to be printed on cigarette packages.\n2. Control of cigarette paper. —\na. No person shall be permitted to import or manufacture cigarette paper without first securing the required permit therefore from the Commissioner of Internal Revenue;\nb. Only duly registered cigarette manufacturers are authorized to buy from a permittee for use in their factories, but before effecting a sale, it shall be obligatory upon the seller of the cigarette paper to secure a written authority from the Commissioner of Internal Revenue, accompanied by a written confirmation of the buyer;\nc. All cigarette manufacturers shall keep a manufacturer's cigarette paper registry book showing the following information:\n1. Debit Entries:\ni. The date the cigarette paper is received; ii. The date of the authority issued by the Commissioner of Internal Revenue; iii. The name and address of the person from whom received; and iv. The number, brand, and color of bobbins or rolls received, showing also the length in meters of each.\n2. Credit Entries:\ni. The date of disposal or use; and ii. The number, brand, and color of bobbins or rolls disposed of or used, showing also the length in meters of each.\n3. Keeping of subsidiary books. - Local manufacturers of cigars and cigarettes shall keep and maintain subsidiary books covering the following:\na. Inventories of imported leaf tobacco showing its volume and value;\nb. Inventories of local leaf tobacco showing its volume and value;\nc. Cost of manufacture for each brand of cigarette; and\nd. Inventories of cigarettes produced on a per brand basis showing their respective volumes and values.\nThe amount that may be needed to implement this provision relative to the monitoring of production and volume of removals of cigarette paper and the printing of fuson stamps shall be included in the General Appropriations Act."}},{"id":"PH-H6135-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Separability Clause . — If any provision of this Act is subsequently declared unconstitutional, the validity of the remaining provisions hereof shall remain in full force and effect."}},{"id":"PH-H6135-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Repealing Clause . — All laws, decrees, executive orders, rules and regulations, and other issuances inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6135-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Effectivity Clause. — This Act shall take effect after fifteen (15) days from its publication in the Official Gazette or in at least two (2) national newspapers of general circulation whichever comes earlier.\nApproved, June 14, 1993."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Revising the Excise Tax Base, Allocating a Portion of the Incremental Revenue Collected for the Emergency Employment Program for Certain Workers Amending for the Purpose Section 142 of the National Internal Revenue Code, as Amended, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6136"] = {"id":"PH-H6136","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7655_1993.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"提高家庭帮佣最低工资，为此修订第442号总统法令第143条的法案","en":"An Act Increasing the Minimum Wage of Househelpers, Amending for the Purpose Article 143 of Presidential Decree No. 442, as Amended","orig":"An Act Increasing the Minimum Wage of Househelpers, Amending for the Purpose Article 143 of Presidential Decree No. 442, as Amended"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 7655","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-08-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7655_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6136-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subparagraphs (1), (2) and (3), Article 143 of Presidential Decree No. 442, as amended, otherwise known as the \"Labor Code of the Philippines,\" are hereby amended to read as follows:\n\"Art. 143. Minimum wage. - (a) Househelpers shall be paid the following minimum wage rates:\n1. Eight hundred pesos (₱800) a month for househelpers in Manila, Quezon, Pasay and Caloocan cities and municipalities of Makati, San Juan, Mandaluyong, Muntinlupa, Navotas, Malabon, Parañaque, Las Piñas, Pasig, Marikina, Valenzuela, Taguig and Pateros in Metro Manila and in highly urbanized cities;\n2. Six hundred fifty pesos (₱650) a month for those in other chartered cities and first class municipalities; and\n3. Five hundred fifty pesos (₱550) a month for those in other municipalities.\nProvided, That the employers shall review the employment contracts of their househelpers every three (3) years with the end in view of improving the terms and conditions thereof.\nProvided, further, That those househelpers who are receiving at least One thousand pesos (₱1,000) shall be covered by the Social Security System (SSS) and be entitled to all the benefits provided thereunder.\""}},{"id":"PH-H6136-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Any violation of any provision of this Act shall be punished with an imprisonment of not more than three (3) months or a fine of not more than Two thousand pesos (₱2,000), or both, at the discretion of the court."}},{"id":"PH-H6136-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Any law, executive order, letter of instruction, or any part thereof, which is inconsistent with any of the provisions of this Act is hereby repealed or amended accordingly."}},{"id":"PH-H6136-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in at least two (2) national newspapers of general circulation, whichever comes earlier.\nApproved, August 19, 1993."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Minimum Wage of Househelpers, Amending for the Purpose Article 143 of Presidential Decree No. 442, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6137"] = {"id":"PH-H6137","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7656_1993.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"要求政府拥有或控制的公司在特定条件下向国家政府宣告分红并为其他目的法案","en":"An Act Requiring Government-Owned or Controlled Corporations to Declare Dividends Under Certain Conditions to the National Government, and for Other Purposes","orig":"An Act Requiring Government-Owned or Controlled Corporations to Declare Dividends Under Certain Conditions to the National Government, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7656","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-11-09","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7656_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6137-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy . — It is hereby declared the policy of the State that in order for the National Government to realize additional revenues, government-owned or controlled corporations, without impairing their viability and the purposes for which they have been established, shall share a substantial amount of their net earnings to the National Government."}},{"id":"PH-H6137-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Definition of Terms. — As used in this Act, the term:\na. \"National Government\" refers to the entire machinery of the central government, as distinguished from the different forms of local governments.\nb. \"Government-owned or controlled corporations\" refer to corporations organized as a stock or non-stock corporation vested with functions relating to public needs, whether governmental or proprietary in nature, and owned by the Government directly or through its instrumentalities either wholly or, where applicable as in the case of stock corporations, to the extent of at least fifty-one percent (51%) of its capital stock. This term shall also include financial institutions, owned or controlled by the National Government, but shall exclude acquired asset corporations, as defined in the next paragraph, state universities, and colleges.\nc. \"Acquired asset corporation\" refers to a corporation: (1) which is under private ownership, the voting or outstanding shares of which were: (i) conveyed to the Government or to a government agency, instrumentality or corporation in satisfaction of debts whether by foreclosure or otherwise, or (ii) duly acquired by the Government through final judgment in a sequestration proceeding; or (2) which is subsidiary of a government corporation organized exclusively to own and manage, or lease, or operate specific physical assets acquired by a government financial institution in satisfaction of debts incurred therewith, and which in any case by law or by enunciated policy is required to be disposed of to private ownership within a specified period of time.\nd. \"Net earnings\" shall mean income derived from whatever source, whether exempt or subject to tax, net of deductions allowed under Section 29 of the National Internal Revenue Code, as amended, and income tax and other taxes paid thereon, but in no case shall any reserve for whatever purpose be allowed as a deduction from net earnings."}},{"id":"PH-H6137-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Dividends. — All government-owned or controlled corporations shall declare and remit at least fifty percent (50%) of their annual net earnings as cash, stock or property dividends to the National Government. This section shall also apply to those government-owned or controlled corporations whose profit distribution is provided by their respective charters or by special law, but shall exclude those enumerated in Section 4 hereof: Provided, That such dividends accruing to the National Government shall be received by the National Treasury and recorded as income of the General Fund."}},{"id":"PH-H6137-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Exemptions. — The provisions of the preceding section notwithstanding, government-owned or controlled corporations created or organized by law to administer real or personal properties or funds held in trust for the use and the benefit of its members, shall not be covered by this Act such as, but not limited to: the Government Service Insurance System, the Home Development Mutual Fund, the Employees Compensation Commission, the Overseas Workers Welfare Administration, and the Philippine Medical Care Commission."}},{"id":"PH-H6137-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Flexible Clause. — In the interest of national economy and general welfare, the percentage of annual net earnings that shall be declared by a government-owned or controlled corporation may be adjusted by the"}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Requiring Government-Owned or Controlled Corporations to Declare Dividends Under Certain Conditions to the National Government, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6138"] = {"id":"PH-H6138","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7657_1993.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"修订第 7637 号共和国法（即《为 Pinatubo 火山喷发灾民拨付一百亿比索用于救助、安置、重建与生计服务及基础设施支持、设立该火山援助、安置与发展委员会的法案》）","en":"An Act to Amend Republic Act Numbered Seventy-Six Hundred Thirty-Seven Entitled \"An Act Appropriating the Sum of Ten Billion Pesos for the Aid, Relief, Resettlement, Rehabilitation and Livelihood Services as Well as Infrastructure Support for the Victims of the Eruption of Mt. Pinatubo, Creating the Mt. Pinatubo Assistance, Resettlement and Development Commission, and for Other Purposes","orig":"An Act to Amend Republic Act Numbered Seventy-Six Hundred Thirty-Seven Entitled \"An Act Appropriating the Sum of Ten Billion Pesos for the Aid, Relief, Resettlement, Rehabilitation and Livelihood Services as Well as Infrastructure Support for the Victims of the Eruption of Mt. Pinatubo, Creating the Mt. Pinatubo Assistance, Resettlement and Development Commission, and for Other Purposes"},"level":"law","status":"active","topics":["company"],"docNumber":"Republic Act No. 7657","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-11-09","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7657_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6138-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 5 of Republic Act Numbered Seventy-six hundred thirty-seven is hereby amended to read as follows:\n\"Section 5. Appropriations Clause. - To carry out the purposes of this Act, the sum of Ten billion pesos (₱10,000,000,000) is hereby appropriated out of any available funds in the National Treasury not otherwise appropriated.\n\"Disbursement of said Ten billion pesos (₱10,000,000,000) shall be programmed as follows:\n“(a) From the approval of this Act to December 31,1993, the sum of Six billion five hundred million pesos (₱500,000,000), Three and a half billion pesos (₱3,500,000,000) of which shall be for resettlement and livelihood projects and Three billion pesos (₱3,000,000,000) for vital infrastructure: Provided, That not more than One billion five hundred million pesos (₱1,500,000,000) shall be spent on dikes.\n“(b) For the year 1994, the sum of Two billion pesos (₱2,000,000,000), one billion pesos of which shall be for resettlement and livelihood projects and One billion pesos (₱1,000,000,000) for vital infrastructure.\n“(c) For the year 1995, the sum of One billion five hundred million pesos (₱1,500,000,000), Five hundred million pesos (₱500,000,000) of which shall be for resettlement and livelihood projects and One billion pesos (₱1,000,000,000) for vital infrastructure.”"}},{"id":"PH-H6138-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 7 (b) and (c) of the same Act is hereby amended to read as follows:\n\"(b) To make a determination of the areas where the lahar flow may be diverted to spare communities and/or minimize damage to lives, habitation, infrastructure, agricultural and other resources upon thorough consultation with lahar experts, scientists, and other technical consultants and personnel;\n\"(c) To prioritize, coordinate and supervise the implementation of the various programs and projects of the Commission;\""}},{"id":"PH-H6138-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"A new paragraph is hereby inserted in Section 7 to read as follows:\n\"(j) Any provision of law to the contrary notwithstanding, the Commission is authorized to re-loan repayments of loans of victim families under the various programs of the Commission, for the purpose of expanding the benefits to other victims who have not availed of said benefits from the funds administered by the Commission;\""}},{"id":"PH-H6138-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 7 (j) of the same Act is amended to read as Section 7(k)."}},{"id":"PH-H6138-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"A new paragraph is hereby inserted after the first paragraph of Section 10 to read as follows:\n\"Any provision of law to the contrary notwithstanding, the public bidding for the award of contracts for infrastructure under this Act shall be conducted by a separate pre-qualification bids and awards committee (PBAC) to be composed of the Chairman of the Mt. Pinatubo Commission as Chairman, one (1) representative each from the Department of Public Works and Highways (DPWH) and the Department of Social Welfare and Development (DSWD), two (2) representatives from the nongovernment sector (NGO) as members, and in case of resettlement projects, a representative of the National Housing Authority (NHA), all to be appointed by the Chairman of the Mt. Pinatubo Commission.\""}},{"id":"PH-H6138-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Separability Clause . - If, for any reason or reasons, any part or provision of this Act shall be declared as unconstitutional or invalid, other parts or provisions hereof which are not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H6138-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Effectivity Clause. - This Act shall take effect upon its publication in at least two (2) national newspapers of general circulation.\nApproved, November 9, 1993."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Republic Act Numbered Seventy-Six Hundred Thirty-Seven Entitled \"An Act Appropriating the Sum of Ten Billion Pesos for the Aid, Relief, Resettlement, Rehabilitation and Livelihood Services as Well as Infrastructure Support for the Victims of the Eruption of Mt. Pinatubo, Creating the Mt. Pinatubo Assistance, Resettlement and Development Commission, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6139"] = {"id":"PH-H6139","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7658_1993.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"禁止公私营单位雇用15岁以下儿童，为此修订第7610号共和国法第七章第12条的法案","en":"An Act Prohibiting the Employment of Children Below 15 Years of Age in Public and Private Undertakings, Amending for This Purpose Section 12, Article VIIi of R.A. 7610","orig":"An Act Prohibiting the Employment of Children Below 15 Years of Age in Public and Private Undertakings, Amending for This Purpose Section 12, Article VIIi of R.A. 7610"},"level":"law","status":"active","topics":["labor","civil"],"docNumber":"Republic Act No. 7658","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-11-09","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7658_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6139-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 12, Article VIII of R.A. No. 7610 otherwise known as the \"Special Protection of Children Against Child Abuse, Exploitation and Discrimination Act\" is hereby amended to read as follows:\n\"Section 12. Employment of Children. - Children below fifteen (15) years of age shall not be employed except:\n1. When a child works directly under the sole responsibility of his parents or legal guardian and where only members of the employer's family are employed: Provided, however, That his employment neither endangers his life, safety, health and morals, nor impairs his normal development: Provided, further, That the parent or legal guardian shall provide the said minor child with the prescribed primary and/or secondary education; or\n2. Where a child's employment or participation in public entertainment or information through cinema, theater, radio or television is essential: Provided, The employment contract is concluded by the child's parents or legal guardian, with the express agreement of the child concerned, if possible, and the approval of the Department of Labor and Employment: and Provided, That the following requirements in all instances are strictly complied with:\na. The employer shall ensure the protection, health, safety, morals and normal development of the child;\nb. The employer shall institute measures to prevent the child's exploitation or discrimination taking into account the system and level of remuneration, and the duration and arrangement of working time; and\nc. The employer shall formulate and implement, subject to the approval and supervision of competent authorities, a continuing program for training and skills acquisition of the child.\nIn the above exceptional cases where any such child may be employed, the employer shall first secure, before engaging such child, a work permit from the Department of Labor and Employment which shall ensure observance of the above requirements.\nThe Department of Labor and Employment shall promulgate rules and regulations necessary for the effective implementation of this Section.\""}},{"id":"PH-H6139-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All laws, decrees, executive orders, rules and regulations or parts thereof contrary to, or inconsistent with this Act are hereby modified or repealed accordingly."}},{"id":"PH-H6139-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after complete publication in the Official Gazette or in at least two (2) national newspapers of general circulation whichever comes earlier.\nApproved, November 9, 1993."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Prohibiting the Employment of Children Below 15 Years of Age in Public and Private Undertakings, Amending for This Purpose Section 12, Article VIIi of R.A. 7610","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6140"] = {"id":"PH-H6140","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7659_1993.html","fetchedAt":"2026-10-06","articleCount":28,"structureMode":"ARTICLE","title":{"zh":"对特定重罪处以死刑、为此修订经修正的修正刑法典及其他特别刑法并为其他目的法案","en":"An Act to Impose the Death Penalty on Certain Heinous Crimes, Amending for that Purpose the Revised Penal Laws, as Amended, Other Special Penal Laws, and for Other Purposes","orig":"An Act to Impose the Death Penalty on Certain Heinous Crimes, Amending for that Purpose the Revised Penal Laws, as Amended, Other Special Penal Laws, and for Other Purposes"},"level":"law","status":"active","topics":["criminal"],"docNumber":"Republic Act No. 7659","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-12-13","completenessNote":"全文，共 28 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7659_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6140-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy. - It is hereby declared the policy of the State to foster and ensure not only obedience to its authority, but also to adopt such measures as would effectively promote the maintenance of peace and order, the protection of life, liberty and property, and the promotion of the general welfare which are essential for the enjoyment by all the people of the blessings of democracy in a just and humane society;"}},{"id":"PH-H6140-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Article 114 of the Revised Penal Code, as amended, is hereby amended to read as follows:\n\"Art. 114. Treason. - Any Filipino citizen who levies war against the Philippines or adheres to her enemies giving them aid or comfort within the Philippines or elsewhere, shall be punished by reclusion perpetua to death and shall pay a fine not to exceed 100,000 pesos.\"\nNo person shall be convicted of treason unless on the testimony of two witnesses at least to the same overt act or on confession of the accused in open court.\nLikewise, an alien, residing in the Philippines, who commits acts of treason as defined in paragraph 1 of this Article shall be punished by reclusion temporal to death and shall pay a fine not to exceed 100,000 pesos.\""}},{"id":"PH-H6140-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section Three, Chapter One, Title One of Book Two of the same Code is hereby amended to read as follows:\n\"Section Three. - Piracy and mutiny on the high seas or in the Philippine waters Art. 122. Piracy in general and mutiny on the high seas or in Philippine waters. - The penalty of reclusion perpetua shall be inflicted upon any person who, on the high seas, or in Philippine waters, shall attack or seize a vessel or, not being a member of its complement nor a passenger, shall seize the whole or part of the cargo of said vessel, its equipment or passengers.\nThe same penalty shall be inflicted in case of mutiny on the high seas or in Philippine waters.\"\nArt. 123. Qualified piracy. - The penalty of reclusion perpetua to death shall be imposed upon those who commit any of the crimes referred to in the preceding article, under any of the following circumstances:\n1. Whenever they have seized a vessel by boarding or firing upon the same;\n2. Whenever the pirates have abandoned their victims without means of saving themselves or;\n3. Whenever the crime is accompanied by murder, homicide, physical injuries or rape.\""}},{"id":"PH-H6140-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"There shall be incorporated after Article 211 of the same Code a new article to read as follows:\n\"Art. 211-A. Qualified Bribery. - If any public officer is entrusted with law enforcement and he refrains from arresting or prosecuting an offender who has committed a crime punishable by reclusion perpetua and/or death in consideration of any offer, promise, gift or present, he shall suffer the penalty for the offense which was not prosecuted.\nIf it is the public officer who asks or demands such gift or present, he shall suffer the penalty of death.\""}},{"id":"PH-H6140-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The penalty of death for parricide under Article 246 of the same Code is hereby restored, so that it shall read as follows:\n\"Art. 246. Parricide. - Any person who shall kill his father, mother, or child, whether legitimate of illegitimate, or any of his ascendants, or descendants, or his spouse, shall be guilty of parricide and shall be punished by the penalty of reclusion perpetua to death.\""}},{"id":"PH-H6140-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Article 248 of the same Code is hereby amended to read as follows:\n\"Art. 248. Murder. - Any person who, not falling within the provisions of Article 246 shall kill another, shall be guilty of murder and shall be punished by reclusion perpetua, to death if committed with any of the following attendant circumstances:\n1. With treachery, taking advantage of superior strength, with the aid of armed men, or employing means to weaken the defense or of means or persons to insure or afford impunity.\n2. In consideration of a price, reward or promise.\n3. By means of inundation, fire, poison, explosion, shipwreck, stranding of a vessel, derailment or assault upon a railroad, fall of an airship, or by means of motor vehicles, or with the use of any other means involving great waste and ruin.\n4. On occasion of any of the calamities enumerated in the preceding paragraph, or of an earthquake, eruption of a volcano, destructive cyclone, epidemic or other public calamity.\n5. With evident premeditation.\n6. With cruelty, by deliberately and inhumanly augmenting the suffering of the victim, or outraging or scoffing at his person or corpse.\""}},{"id":"PH-H6140-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Article 255 of the same Code is hereby amended to read as follows:\n\"Art. 255. Infanticide. - The penalty provided for parricide in Article 246 and for murder in Article 248 shall be imposed upon any person who shall kill any child less than three days of age.\nIf any crime penalized in this Article be committed by the mother of the child for the purpose of concealing her dishonor, she shall suffer the penalty of prision mayor in its medium and maximum periods, and if said crime be committed for the same purpose by the maternal grandparents or either of them, the penalty shall be reclusion temporal.\""}},{"id":"PH-H6140-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Article 267 of the same Code is hereby amended to read as follows:\n\"Art. 267. Kidnapping and serious illegal detention. - Any private individual who shall kidnap or detain another, or in any other manner deprive him of his liberty, shall suffer the penalty of reclusion perpetua to death:\n1. If the kidnapping or detention shall have lasted more than three days.\n2. If it shall have been committed simulating public authority.\n3. If any serious physical injuries shall have been inflicted upon the person kidnapped or detained; or if threats to kill him shall have been made.\n4. If the person kidnapped or detained shall be a minor, except when the accused is any of the parents, female or a public officer.\nThe penalty shall be death penalty where the kidnapping or detention was committed for the purpose of extorting ransom from the victim or any other person, even if none of the circumstances above-mentioned were present in the commission of the offense.\nWhen the victim is killed or dies as a consequence of the detention or is raped, or is subjected to torture or dehumanizing acts, the maximum penalty shall be imposed.\""}},{"id":"PH-H6140-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Article 294 of the same Code is hereby amended to read as follows:\n\"Art. 294. Robbery with violence against or intimidation of persons - Penalties. - Any person guilty of robbery with the use of violence against or intimidation of any person shall suffer:\n1. The penalty of reclusion perpetua to death, when by reason or on occasion of the robbery, the crime of homicide shall have been committed, or when the robbery shall have been accompanied by rape or intentional mutilation or arson.\n2. The penalty of reclusion temporal in its medium period to reclusion perpetua, when or if by reason or on occasion of such robbery, any of the physical injuries penalized in subdivision I of Article 263 shall have been inflicted.\n3. The penalty of reclusion temporal, when by reason or on occasion of the robbery, any of the physical injuries penalized in subdivision 2 of the article mentioned in the next preceding paragraph, shall have been inflicted.\n4. The penalty of prision mayor in its maximum period to reclusion temporal in its medium period, if the violence or intimidation employed in the commission of the robbery shall have been carried to a degree clearly unnecessary for the commission of the crime, or when in the course of its execution, the offender shall have inflicted upon any person not responsible for its commission any of the physical injuries covered by subdivisions 3 and 4 of said Article 263.\n5. The penalty of prision correccional in its maximum period to prision mayor in its medium period in other cases.\""}},{"id":"PH-H6140-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Article 320 of the same Code is hereby amended to read as follows:\n\"Art. 320. Destructive Arson. - The penalty of reclusion perpetua to death shall be imposed upon any person who shall burn:\n1. One (1) or more buildings or edifices, consequent to one single act of burning, or as a result of simultaneous burnings, committed on several or different occasions.\n2. Any building of public or private ownership, devoted to the public in general or where people usually gather or congregate for a definite purpose such as, but not limited to, official governmental function or business, private transaction, commerce, trade, workshop, meetings and conferences, or merely incidental to a definite purpose such as but not limited to hotels, motels, transient dwellings, public conveyances or stops or terminals, regardless of whether the offender had knowledge that there are persons in said building or edifice at the time it is set on fire and regardless also of whether the building is actually inhabited or not.\n3. Any train or locomotive, ship or vessel, airship or airplane, devoted to transportation or conveyance, or for public use, entertainment or leisure.\n4. Any building, factory, warehouse installation and any appurtenances thereto, which are devoted to the service of public utilities.\n5. Any building the burning of which is for the purpose of concealing or destroying evidence of another violation of law, or for the purpose of concealing bankruptcy or defrauding creditors or to collect from insurance.\nIrrespective of the application of the above enumerated qualifying circumstances, the penalty of reclusion perpetua to death shall likewise be imposed when the arson is perpetrated or committed by two (2) or more persons or by a group of persons, regardless of whether their purpose is merely to burn or destroy the building or the burning merely constitutes an overt act in the commission or another violation of law.\nThe penalty of reclusion perpetua to death shall also be imposed upon any person who shall burn:\n1. Any arsenal, shipyard, storehouse or military powder or fireworks factory, ordnance, storehouse, archives or general museum of the Government.\n2. In an inhabited place, any storehouse or factory of inflammable or explosive materials.\nIf as a consequence of the commission of any of the acts penalized under this Article, death results, the mandatory penalty of death shall be imposed.\""}},{"id":"PH-H6140-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Article 335 of the same Code is hereby amended to read as follows:\n\"Art. 335. When and how rape is committed. - Rape is committed by having carnal knowledge of a woman under any of the following circumstances:\n1. By using force or intimidation;\n2. When the woman is deprived of reason or otherwise unconscious; and\n3. When the woman is under twelve years of age or is demented.\nThe crime of rape shall be punished by reclusion perpetua.\nWhenever the crime of rape is committed with the use of a deadly weapon or by two or more persons, the penalty shall be reclusion perpetua to death.\nWhen by reason or on the occasion of the rape, the victim has become insane, the penalty shall be death.\nWhen the rape is attempted or frustrated and a homicide is committed by reason or on the occasion thereof, the penalty shall be reclusion perpetua to death.\nWhen by reason or on the occasion of the rape, a homicide is committed, the penalty shall be death.\nThe death penalty shall also be imposed if the crime of rape is committed with any of the following attendant circumstances:\n1. when the victim is under eighteen (18) years of age and the offender is a parent, ascendant, step-parent, guardian, relative by consanguinity or affinity within the third civil degree, or the common-law-spouse of the parent of the victim.\n2. when the victim is under the custody of the police or military authorities.\n3. when the rape is committed in full view of the husband, parent, any of the children or other relatives within the third degree of consanguinity.\n4. when the victim is a religious or a child below seven (7) years old.\n5. when the offender knows that he is afflicted with Acquired Immune Deficiency Syndrome (AIDS) disease.\n6. when committed by any member of the Armed Forces of the Philippines or the Philippine National Police or any law enforcement agency.\n7. when by reason or on the occasion of the rape, the victim has suffered permanent physical mutilation.\""}},{"id":"PH-H6140-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section 2 of Republic Act No. 7080 (An Act Defining and Penalizing the Crime of Plunder) is hereby amended to read as follows:\n\"Sec. 2. Definition of the Crime of Plunder; Penalties. - Any public officer who, by himself or in connivance with members of his family, relatives by affinity or consanguinity, business associates, subordinates or other persons, amasses, accumulates or acquires ill-gotten wealth through a combination or series of overt criminal acts as described in Section 1 (d) hereof in the aggregate amount or total value of at least Fifty million pesos (P50,000,000.00) shall be guilty of the crime of plunder and shall be punished by reclusion perpetua to death. Any person who participated with the said public officer in the commission of an offense contributing to the crime of plunder shall likewise be punished for such offense. In the imposition of penalties, the degree of participation and the attendance of mitigating and extenuating circumstances, as provided by the Revised Penal Code, shall be considered by the court. The court shall declare any and all ill-gotten wealth and their interests and other incomes and assets including the properties and shares of stocks derived from the deposit or investment thereof forfeited in favor of the State.\""}},{"id":"PH-H6140-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Sections 3, 4, 5, 7, 8 and 9, of Article II of Republic Act No. 6425, as amended, known as the Dangerous Drugs Act 1972, are hereby amended to read as follows:\n\"Sec. 3. Importation of Prohibited Drugs. - The penalty of reclusion perpetua to death and a fine ranging from five hundred thousand pesos to ten million pesos shall be imposed upon any person who, unless authorized by law, shall import or bring into the Philippines any prohibited drug.\n\"Sec. 4. Sale, Administration, Delivery, Distribution and Transportation of Prohibited Drugs. - The penalty of reclusion perpetua to death and a fine from five hundred thousand pesos to ten million pesos shall be imposed upon any person who, unless authorized by law, shall sell, administer, deliver, give away to another, distribute, dispatch in transit or transport any prohibited drug, or shall act as a broker in any of such transactions.\nNotwithstanding the provisions of Section 20 of this Act to the contrary, if the victim of the offense is a minor, or should a prohibited drug involved in any offense under this Section be the proximate cause of the death of a victim thereof, the maximum penalty herein provided shall be imposed.\n\"Sec. 5. Maintenance of a Den, Dive or Resort for Prohibited Drug Users. - The penalty of reclusion perpetua to death and a fine ranging from five hundred thousand pesos to ten million pesos shall be imposed upon any person or group of persons who shall maintain a den, dive or resort where any prohibited drug is used in any form or where such prohibited drugs in quantities specified in Section 20, Paragraph 1 of this Act are found.\nNotwithstanding the provisions of Section 20 of this Act to the contrary, the maximum of the penalty shall be imposed in every case where a prohibited drug is administered, delivered or sold to a minor who is allowed to use the same in such place.\nShould a prohibited drug be the proximate cause of the death of a person using the same in such den, dive or resort, the maximum penalty herein provided shall be imposed on the maintainer notwithstanding the provisions of Section 20 of this Act to the contrary.\n\"Sec. 7. Manufacture of Prohibited Drug. - The penalty of reclusion perpetua to death and fine ranging from five hundred thousand pesos to ten million pesos shall be imposed upon any person who, unless authorized by law, shall engage in the manufacture of any prohibited drug.\n\"Sec. 8. Possession or Use of Prohibited Drugs. - The penalty of reclusion perpetua to death and a fine ranging from five hundred thousand pesos to ten million pesos shall be imposed upon any person who, unless authorized by law, shall possess or use any prohibited drug subject to the provisions of Section 20 hereof.\n\"Sec. 9. Cultivation of Plants which are Sources of Prohibited Drugs. - The penalty of reclusion perpetua to death and a fine ranging from five hundred thousand pesos to ten million pesos shall be imposed upon any person who shall plant, cultivate or culture any medium Indian hemp, opium poppy (papaver somniferum), or any other plant which is or may hereafter be classified as dangerous drug or from which any dangerous drug may be manufactured or derived.\nThe land or portions hereof, and/or greenhouses on which any of said plants is cultivated or cultured shall be confiscated and escheated to the State, unless the owner thereof can prove that he did not know such cultivation or culture despite the exercise of due diligence on his part.\nIf the land involved in is part of the public domain, the maximum of the penalties herein provided shall be imposed upon the offender.\""}},{"id":"PH-H6140-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Sections 14, 14-A, and 15 of Article III of Republic Act No. 6425, as amended, known as the Dangerous Drugs Act of 1972, are hereby amended to read as follows:\n\"Sec. 14. Importation of Regulated Drugs. - The penalty of reclusion perpetua to death and a fine ranging from five hundred thousand pesos to ten million pesos shall be imposed upon any person who, unless authorized by law, shall import or bring any regulated drug in the Philippines.\n\"Sec. 14-A. Manufacture of Regulated Drugs. - The penalty of reclusion perpetua to death and a fine ranging from five hundred thousand pesos to ten million pesos shall be imposed upon any person who, unless authorized by law, shall engage in the manufacture of any regulated drug.\n\"Sec. 15. Sale, Administration, Dispensation, Delivery, Transportation and Distribution of Regulated Drugs. - The penalty of reclusion perpetua to death and a fine ranging from five hundred thousand pesos to ten million pesos shall be imposed upon any person who, unless authorized by law, shall sell, dispense, deliver, transport or distribute any regulated drug.\nNotwithstanding the provisions of Section 20 of this Act to the contrary, if the victim of the offense is a minor, or should a regulated drug involved in any offense under this Section be the proximate cause of the death of a victim thereof, the maximum penalty herein provided shall be imposed.\""}},{"id":"PH-H6140-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"There shall be incorporated after Section 15 of Article III of Republic Act No. 6425, as amended, known as the Dangerous Drug Act of 1972, a new section to read as follows:\n\"Sec. 15-a. Maintenance of a den, dive or resort for regulated drug users. - The penalty of reclusion perpetua to death and a fine ranging from five hundred thousand pesos to ten million pesos shall be imposed upon any person or group of persons who shall maintain a den, dive or resort where any regulated drugs is used in any form, or where such regulated drugs in quantities specified in Section 20, paragraph 1 of this Act are found.\nNotwithstanding the provisions of Section 20 of this Act to the contrary, the maximum penalty herein provided shall be imposed in every case where a regulated drug is administered, delivered or sold to a minor who is allowed to use the same in such place.\nShould a regulated drug be the proximate cause of the death of a person using the same in such den, dive or resort, the maximum penalty herein provided shall be imposed on the maintainer notwithstanding the provisions of Section 20 of this Act to the contrary.\""}},{"id":"PH-H6140-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Section 16 of Article III of Republic Act No. 6425, as amended, known as the Dangerous Drugs Act of 1972, is amended to read as follows:\n\"Sec. 16. Possession or Use of Regulated Drugs. - The penalty of reclusion perpetua to death and a fine ranging from five hundred thousand pesos to ten million pesos shall be imposed upon any person who shall possess or use any regulated drug without the corresponding license or prescription, subject to the provisions of Section 20 hereof.\""}},{"id":"PH-H6140-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Section 20, Article IV of Republic Act No. 6425, as amended, known as the Dangerous Drugs Act of 1972, is hereby amended to read as follows:\nSec. 20. Application of Penalties, Confiscation and Forfeiture of the Proceeds or Instruments of the Crime. - The penalties for offenses under Section 3, 4, 7, 8 and 9 of Article II and Sections 14, 14-A, 15 and 16 of Article III of this Act shall be applied if the dangerous drugs involved is in any of the following quantities :\n1. 40 grams or more of opium;\n2. 40 grams or more of morphine;\n3. 200 grams or more of shabu or methylamphetamine hydrochloride;\n4. 40 grams or more of heroin;\n5. 750 grams or more of indian hemp or marijuana;\n6. 50 grams or more of marijuana resin or marijuana resin oil;\n7. 40 grams or more of cocaine or cocaine hydrochloride; or\n8. In the case of other dangerous drugs, the quantity of which is far beyond therapeutic requirements, as determined and promulgated by the Dangerous Drugs Board, after public consultations/hearings conducted for the purpose.\nOtherwise, if the quantity involved is less than the foregoing quantities, the penalty shall range from prision correccional to reclusion perpetua depending upon the quantity.\nEvery penalty imposed for the unlawful importation, sale, administration, delivery, transportation or manufacture of dangerous drugs, the cultivation of plants which are sources of dangerous drugs and the possession of any opium pipe and other paraphernalia for dangerous drugs shall carry with it the confiscation and forfeiture, in favor of the Government, of all the proceeds of the crime including but not limited to money and other obtained thereby and the instruments or tools with which it was committed, unless they are the property of a third person not liable for the offense, but those which are not of lawful commerce shall be ordered destroyed without delay. Dangerous drugs and plant sources of such drugs as well as the proceeds or instruments of the crime so confiscated and forfeited in favor of the Government shall be turned over to the Board for proper disposal without delay.\nAny apprehending or arresting officer who misappropriates or misapplies or fails to account for seized or confiscated dangerous drugs or plant-sources of dangerous drugs or proceeds or instruments of the crime as are herein defined shall after conviction be punished by the penalty of reclusion perpetua to death and a fine ranging from five hundred thousand pesos to ten million pesos.\""}},{"id":"PH-H6140-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"There shall be incorporated after Section 20 of Republic Act No. 6425, as amended, known as the Dangerous Drugs Act of 1972, a new section to read as follows:\n\"Sec. 20-A. Plea-bargaining Provisions. - Any person charged under any provision of this Act where the imposable penalty is reclusion perpetua to death shall not be allowed to avail of the provision on plea bargaining.\""}},{"id":"PH-H6140-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Section 24 of Republic Act No. 6425, as amended, known as the Dangerous Drugs Act of 1972, is hereby amended to read as follows :\n\"Sec. 24. Penalties for Government Official and Employees and Officers and Members of Police Agencies and the Armed Forces, 'Planting' of Evidence. - The maximum penalties provided for Section 3, 4(1), 5(1), 6, 7, 8, 9, 11, 12 and 13 of Article II and Sections 14, 14-A, 15(1), 16 and 19 of Article III shall be imposed, if those found guilty of any of the said offenses are government officials, employees or officers, including members of police agencies and the armed forces.\nAny such above government official, employee or officer who is found guilty of \"planting\" any dangerous drugs punished in Sections 3, 4, 7, 8, 9 and 13 of Article II and Sections 14, 14-A, 15 and 16 of Article III of this Act in the person or in the immediate vicinity of another as evidence to implicate the latter, shall suffer the same penalty as therein provided.\""}},{"id":"PH-H6140-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Sec. 14 of Republic Act No. 6539, as amended, known as the Anti-Carnapping Act of 1972, is hereby amended to read as follows:\n\"Sec. 14. Penalty for Carnapping. - Any person who is found guilty of carnapping, as this term is defined in Section Two of this Act, shall, irrespective of the value of motor vehicle taken, be punished by imprisonment for not less than fourteen years and eight months and not more than seventeen years and four months, when the carnapping is committed without violence or intimidation of persons, or force upon things; and by imprisonment for not less than seventeen years and four months and not more than thirty years, when the carnapping is committed by means of violence against or intimidation of any person, or force upon things; and the penalty of reclusion perpetua to death shall be imposed when the owner, driver or occupant of the carnapped motor vehicle is killed or raped in the course of the commission of the carnapping or on the occasion thereof.\""}},{"id":"PH-H6140-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Article 27 of the Revised Penal Code, as amended, is hereby amended to read as follows:\n\"Art. 27. Reclusion perpetua. - The penalty of reclusion perpetua shall be from twenty years and one day to forty years.\nReclusion temporal. - The penalty of reclusion temporal shall be from twelve years and one day to twenty years.\nPrision mayor and temporary disqualification. - The duration of the penalties of prision mayor and temporary disqualification shall be from six years and one day to twelve years, except when the penalty of disqualification is imposed as an accessory penalty, in which case, it shall be that of the principal penalty.\nPrision correccional, suspension, and destierro. - The duration of the penalties of prision correccional, suspension, and destierro shall be from six months and one day to six years, except when the suspension is imposed as an accessory penalty, in which case, its duration shall be that of the principal penalty.\nArresto mayor. - The duration of the penalty of arresto mayor shall be from one month and one day to six months.\nArresto menor. - The duration of the penalty of arresto menor shall be from one day to thirty days.\nBond to keep the peace. - The bond to keep the peace shall be required to cover such period of time as the court may determine.\""}},{"id":"PH-H6140-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Article 47 of the same Code is hereby amended to read as follows:\nArt. 47. In what cases the death penalty shall not be imposed; Automatic review of the Death Penalty Cases. - The death penalty shall be imposed in all cases in which it must be imposed under existing laws, except when the guilty person is below eighteen (18) years of age at the time of the commission of the crime or is more than seventy years of age or when upon appeal or automatic review of the case by the Supreme Court, the required majority vote is not obtained for the imposition of the death penalty, in which cases the penalty shall be reclusion perpetua.\nIn all cases where the death penalty is imposed by the trial court, the records shall be forwarded to the Supreme Court for automatic review and judgment by the Court en banc, within twenty (20) days but not earlier than fifteen (15) days after promulgation of the judgment or notice of denial of any motion for new trial or reconsideration. The transcript shall also be forwarded within ten (10) days from the filing thereof by the stenographic reporter.\""}},{"id":"PH-H6140-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Article 62 of the same Code, as amended, is hereby amended to read as follows :\n\"Art. 62. Effects of the attendance of mitigating or aggravating circumstances and of habitual delinquency. - Mitigating or aggravating circumstances and habitual delinquency shall be taken into account for the purpose of diminishing or increasing the penalty in conformity with the following rules:\n1. Aggravating circumstances which in themselves constitute a crime specially punishable by law or which are included by the law in defining a crime and prescribing the penalty therefor shall not be taken into account for the purpose of increasing the penalty.\n1(a). When in the commission of the crime, advantage was taken by the offender of his public position, the penalty to be imposed shall be in its maximum regardless of mitigating circumstances.\nThe maximum penalty shall be imposed if the offense was committed by any group who belongs to an organized/syndicated crime group.\nAn organized/syndicated crime group means a group of two or more persons collaborating, confederating or mutually helping one another for purposes of gain in the commission of any crime.\n2. The same rule shall apply with respect to any aggravating circumstances inherent in the crime to such a degree that it must of necessity accompany the commission thereof.\n3. Aggravating or mitigating circumstances which arise from the moral attributes of the offender, or from his private relations with the offended party, or from any other personal cause, shall only serve to aggravate or mitigate the liability of the principals, accomplices and accessories as to whom such circumstances are attendant.\n4. The circumstances which consist in the material execution of the act, or in the means employed to accomplish it, shall serve to aggravate or mitigate the liability of those persons only who had knowledge of them at the time of the execution of the act or their cooperation therein.\n5. Habitual delinquency shall have the following effects :\n(a) Upon a third conviction the culprit shall be sentenced to the penalty provided by law for the last crime of which he be found guilty and to the additional penalty of prision correccional in its medium and maximum periods;\n(b) Upon a fourth conviction, the culprit shall be sentenced to the penalty provided for the last crime of which he be found guilty and to the additional penalty of prision mayor in its minimum and medium periods; and\n(c) Upon a fifth or additional conviction, the culprit shall be sentenced to the penalty provided for the last crime of which he be found guilty and to the additional penalty of prision mayor in its maximum period to reclusion temporal in its minimum period.\nNotwithstanding the provisions of this article, the total of the two penalties to be imposed upon the offender, in conformity herewith, shall in no case exceed 30 years.\nFor purposes of this article, a person shall be deemed to be a habitual delinquent, if within a period of ten years from the date of his release or last conviction of the crimes of serious or less serious physical injuries, robo, hurto, estafa or falsification, he is found guilty of any of said crimes a third time or oftener."}},{"id":"PH-H6140-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Article 81 of the same Code, as amended, is hereby amended to read as follows :\n\"Art. 81. When and how the death penalty is to be executed. - The death sentence shall be executed with preference to any other and shall consist in putting the person under sentence to death by electrocution. The death sentence shall be executed under the authority of the Director of Prisons, endeavoring so far as possible to mitigate the sufferings of the person under the sentence during electrocution as well as during the proceedings prior to the execution.\nIf the person under sentence so desires, he shall be anaesthetized at the moment of the execution.\nAs soon as facilities are provided by the Bureau of Prisons, the method of carrying out the sentence shall be changed to gas poisoning.\nThe death sentence shall be carried out not later than one (1) year after the judgment has become final.\""}},{"id":"PH-H6140-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Article 83 of the same Code is hereby amended to read as follows:\n\"Art. 83. Suspension of the execution of the death sentence. - The death sentence shall not be inflicted upon a woman while she is pregnant or within one (1) year after delivery, nor upon any person over seventy years of age. In this last case, the death sentence shall be commuted to the penalty of reclusion perpetua with the accessory penalties provided in Article 40.\nIn all cases where the death sentence has become final, the records of the case shall be forwarded immediately by the Supreme Court to the Office of the President for possible exercise of the pardoning power.\""}},{"id":"PH-H6140-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"All laws, presidential decrees and issuances, executive orders, rules and regulations or parts thereof inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6140-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"If, for any reason or reasons, any part of the provision of this Act shall be held to be unconstitutional or invalid, other parts or provisions hereof which are not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H6140-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in two (2) national newspapers of general circulation. The publication shall not be later than seven (7) days after the approval hereof.\nApproved: December 13, 1993"}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Impose the Death Penalty on Certain Heinous Crimes, Amending for that Purpose the Revised Penal Laws, as Amended, Other Special Penal Laws, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6141"] = {"id":"PH-H6141","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7660_1993.html","fetchedAt":"2026-10-06","articleCount":26,"structureMode":"ARTICLE","title":{"zh":"进一步理顺文件印花税的结构与管理、为此修订经修正的国家国内税收法典若干条款、为特定项目分配资金并为其他目的法案","en":"An Act Rationalizing Further the Structure and Administration of the Documentary Stamp Tax, Amending for the Purpose Certain Provisions of the National Internal Revenue Code, as Amended, Allocating Funds for Specific Programs, and for Other Purposes","orig":"An Act Rationalizing Further the Structure and Administration of the Documentary Stamp Tax, Amending for the Purpose Certain Provisions of the National Internal Revenue Code, as Amended, Allocating Funds for Specific Programs, and for Other Purposes"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 7660","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-12-23","completenessNote":"全文，共 26 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7660_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6141-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 173 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 173. Stamp taxes upon documents, instruments, loan agreements, and papers. - Upon documents, instruments, loan agreements, and papers, and upon acceptances, assignments, sales, and transfers of the obligation, right, or property incident thereto, there shall be levied, collected and paid for, and in respect of the transaction so had or accomplished, the corresponding documentary stamp taxes prescribed in the following sections of this Title , by the person making, signing, issuing, accepting, or transferring the same wherever the document is made, signed, issued, accepted, or transferred when the obligation or right arises from Philippine sources or the property is situated in the Philippines, and at the same time such act is done or transaction had: Provided, That whenever one party to the taxable document enjoys exemption from the tax herein imposed, the other party thereto who is not exempt shall be the one directly liable for the tax.\""}},{"id":"PH-H6141-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 174 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 174. Stamp tax on bonds, debentures, and certificates of indebtedness. - On all bonds, debentures, and certificates of indebtedness issued by any association, company, or corporation, there shall be collected a documentary stamp tax of One peso and fifty centavos (P1.50) on each two hundred pesos, or fractional part thereof, of the face value of such documents.\""}},{"id":"PH-H6141-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 175 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 175. Stamp tax on original issue of certificates of stock. - On every original issue, whether on organization, reorganization or for any lawful purpose, of certificates of stock by any association, company, or corporations, there shall be collected a documentary stamp tax of Two pesos (P2.00) on each two hundred pesos, or fractional part thereof, of the par value of such certificates: Provided, That in the case of the original issue of stock without par value the amount of the documentary stamp tax herein prescribed shall be based upon the actual consideration received by the association, company, or corporation for the issuance of such stock, and in the case of stock dividends on the actual value represented by each share.\""}},{"id":"PH-H6141-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 176 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 176. Stamp tax on sales, agreements to sell, memoranda of sales, deliveries or transfer of due-bills, certificates of obligation, or shares or certificates of stock. - On all sales, or agreements to sell, or memoranda of sales, or deliveries, or transfer of due-bills, certificates of obligation, or shares or certificates of stock in any association, company or corporation, or transfer of such securities by assignment in blank, or by delivery, or by any paper or agreement, or memorandum or other evidences of transfer or sale whether entitling the holder in any manner to the benefit of such due-bills, certificates of obligation or stock, or to secure the future payment of money, or for the future transfer of any due-bill, certificates of obligation or stock, there shall be collected a documentary stamp tax of One peso (P1.00) on each two hundred pesos, or fractional part thereof, of the par value of such due-bill, certificates of obligation or stock: Provided, That only one tax shall be collected on each sale or transfer of stock or securities from one person to another, regardless of whether or not a certificate of stock or obligation is issued, endorsed, or delivered in pursuance of such sale or transfer: and Provided, further, That in the case of stock without par value the amount of the documentary stamp herein prescribed shall be equivalent to twenty-five per centum of the documentary stamp tax paid upon the original issue of said stock: Provided, furthermore, That the tax herein imposed shall be increased to One peso and fifty centavos (P1.50) beginning 1996.\""}},{"id":"PH-H6141-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 178 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 178. Stamp tax on certificates of profits or interests in property or accumulations. - On all certificates of profits, or any certificate or memorandum showing interest in the property or accumulations of any association, company, or corporation, and on all transfers of such certificates or memoranda, there shall be collected a documentary stamp tax of Fifty centavos (P0.50) on each two hundred pesos, or fractional part thereof, of the face value of such certificate or memorandum.\""}},{"id":"PH-H6141-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section 179 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 179. Stamp tax on bank checks, drafts, certificates of deposit not bearing interest, and other instruments. - On each bank check, draft, or certificate of deposit not drawing interest, or order for the payment of any sum of money drawn upon or issued by any bank, trust company, or any person or persons, companies or corporations, at sight or on demand, there shall be collected a documentary stamp tax of One peso and twenty-five centavos (P1.25): Provided, That the tax herein imposed shall be increased to One peso and fifty centavos (P1.50) beginning 1996.\""}},{"id":"PH-H6141-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section 180 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 180. Stamp tax on all loan agreements, promissory notes, bills of exchange, drafts, instruments and securities issued by the government or any of its instrumentalities, certificates of deposit bearing interest and others not payable on sight or demand. - On all loan agreements signed abroad wherein the object of the contract is located or used in the Philippines; bills of exchange (between points within the Philippines), drafts, instruments and securities issued by the Government or any of its instrumentalities or certificates of deposits drawing interest, or orders for the payment of any sum of money otherwise than at sight or on demand, or on all promissory notes, whether negotiable or non-negotiable, except bank notes issued for circulation, and on each renewal of any such note, there shall be collected a documentary stamp tax of Thirty centavos (P0.30) on each two hundred pesos, or fractional part thereof, of the face value of any such agreement, bill of exchange, draft, certificate of deposit, or note: Provided, That only one documentary stamp tax shall be imposed on either loan agreement, or promissory notes issued to secure such loan, whichever will yield a higher tax: Provided, however, That loan agreements or promissory notes the aggregate of which does not exceed Two hundred fifty thousand pesos (P250,000) executed by an individual for his purchase on installment for his personal use or that of his family and not for business, resale, barter or hire of a house, lot, motor vehicle, appliance or furniture shall be exempt from the payment of the documentary stamp tax provided under this section.\""}},{"id":"PH-H6141-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section 184 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 184. Stamp tax on policies of insurance upon property. - On all policies of insurance or other instruments by whatever name the same may be called, by which insurance shall be made or renewed upon property of any description, including rents or profits, against peril by sea or on inland waters, or by fire or lightning, there shall be collected a documentary stamp tax of Fifty centavos (P0.50) on each four pesos, or fractional part thereof, of the amount of premium charged: Provided, however, That no documentary stamp tax shall be collected on reinsurance contracts or on any instrument by which cession or acceptance of insurance risks under any reinsurance agreement is effected or recorded.\""}},{"id":"PH-H6141-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section 185 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 185. Stamp tax on fidelity bonds and other insurance policies. - On all policies of insurance or bonds or obligations of the nature of indemnity for loss, damage, or liability made or renewed by any person, association, company or corporation transacting the business of accident, fidelity, employer's liability, plate, glass, steam boiler, burglar, elevator, automatic sprinkler, or other branch of insurance (except life, marine, inland, and fire insurance), and all bonds, undertakings, or recognizances, conditioned for the performance of the duties of any office or position, for the doing or not doing of anything therein specified, and on all obligations guaranteeing the validity or legality of any bonds or other obligations issued by any province, city, municipality, or other public body or organization, and on all obligations guaranteeing the title to any real estate, or guaranteeing any mercantile credits, which may be made or renewed by any such person, company or corporation, there shall be collected a documentary stamp tax of Fifty centavos (P0.50) on each four pesos, or fractional part thereof of the premium charged.\""}},{"id":"PH-H6141-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section 186 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 186. Stamp tax on policies of annuities and pre-need plans. - On all policies of annuities, or other instruments by whatever name the same may be called, whereby an annuity may be made, transferred, or redeemed, there shall be collected a documentary stamp tax of One peso and fifty centavos (P1.50), on each two hundred pesos, or fractional part thereof, of the capital of the annuity, or should this be unknown, then on each two hundred pesos, or fractional part thereof, of thirty-three and one-third times the annual income. On pre-need plans, the documentary stamp tax shall be at Fifty centavos (P0.50) on each Five hundred pesos (P500.00), or fractional part thereof, of the value or amount of the plan.\""}},{"id":"PH-H6141-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section 187 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 187. Stamp tax on indemnity bonds. - On all bonds for indemnifying any person, firm or corporation who shall become bound or engaged as surety for the payment of any sum of money or for the due execution or performance of the duties of any office or position or to account for money received by virtue thereof, and on all other bonds of any description, except such as may be required in legal proceedings, or are otherwise provided for herein, there shall be collected a documentary stamp tax of Ten centavos (P0. 10) on each four pesos or fractional part thereof of the premium charge: Provided, That the tax herein imposed shall be increased to Thirty centavos (P0.30) on each four pesos or fractional part thereof of the premium charged beginning 1996.\""}},{"id":"PH-H6141-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section 188 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 188. Stamp tax on certificates. - On each certificate of damage or otherwise, and on every other certificate or document issued by any customs officer, marine surveyor, or other person acting as such, and on each certificate issued by a notary public, and on each certificate of any description required by law or by rules or regulations of a public office, or which is issued for the purpose of giving information, or establishing proof of a fact, and not otherwise specified herein, there shall be collected a documentary stamp tax of Ten pesos (P10.00): Provided, That the tax herein imposed shall be increased to Fifteen pesos (P15.00) beginning 1996.\""}},{"id":"PH-H6141-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Section 189 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 189. Stamp tax on warehouse receipts. - On each warehouse receipt for property held in storage in a public or private warehouse or yard for any other person other than the proprietor of such warehouse or yard, there shall be collected a documentary stamp tax of Ten pesos (P10.00): Provided, That no tax shall be collected on each warehouse receipt issued to any one of person in any one calendar month covering property the value of which does not exceed two hundred pesos: Provided, further, That the tax herein imposed shall be increased to Fifteen pesos (P15.00) beginning 1996.\""}},{"id":"PH-H6141-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Section 190 of the National Internal Revenue Code, as amended by Sec. 2 of Executive Order No. 194 series of 1987, is hereby further amended to read as follows:\n\"Section 190. Stamp tax onjai-alai, horse race tickets, lotto, or other authorized numbers games. - On each jai-alai, horse race tickets, lotto, or other authorized numbers games, there shall be collected a documentary stamp tax of Ten centavos (P0.10): Provided, That if the cost of the ticket exceeds One peso (P1.00) , an additional tax of Ten centavos (P0.10) on every One peso (P1.00) or fractional part thereof shall be collected.\""}},{"id":"PH-H6141-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Section 191 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 191. Stamp tax on bills of lading or receipts. - On each set of bills of lading or receipts (except charter party) for any goods, merchandise, or effects shipped from one port or place in the Philippines to another port or place in the Philippines (except on ferries across rivers), or to any foreign port, there shall be collected a documentary stamp tax of One peso (P1.00), if the value of such goods exceed One hundred pesos (P100.00), and does not exceed One thousand pesos (P1,000.00); Ten pesos (P10.00) if the value exceeds One thousand pesos (P1,000.00): Provided, however, That freight tickets covering goods, merchandise or effects carried as accompanied baggage of passengers on land and water carriers primarily engaged in the transportation of passengers are hereby exempt.\""}},{"id":"PH-H6141-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Section 192 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 192. Stamp tax on proxies. - On each proxy for voting at any election for officers of any company or association, or for any other purpose, except proxies issued affecting the affairs of associations or corporations organized for religious, charitable, or literary purposes, there shall be collected a documentary stamp tax of Ten pesos (P10.00): Provided, That the tax herein imposed shall be increased to Fifteen pesos (P15.00) beginning 1996.\""}},{"id":"PH-H6141-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Section 193 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 193. Stamp tax on powers of attorney. - On each power of attorney to perform any act whatsoever, except acts connected with the collection of claims due from or accruing to the Government of the Republic of the Philippines, or the government of any province, city or municipality, there shall be collected a documentary stamp tax of Five pesos (P5.00).\""}},{"id":"PH-H6141-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Section 194 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 194. Stamp tax on leases and other hiring agreements. - On each lease, agreement, memorandum, or contract for hire, use or rent of any lands or tenements, or portions thereof, there shall be collected a documentary stamp of Three pesos (P3.00) for the first Two thousand pesos (P2,000.00), or fractional part thereof, and an additional One peso (P1.00) for every One thousand pesos (P1,000.00) or fractional part thereof in excess of the first Two thousand pesos (P2,000.00) for each year of the term of said contracts or agreement.\""}},{"id":"PH-H6141-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Section 195 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 195. Stamp tax on mortgages, pledges, and deeds of trust. - On every mortgage or pledge of lands, estate, or property, real or personal, heritable or movable, whatsoever, where the same shall be made as a security for the payment of any definite and certain sum of money lent at the time or previously due and owing or forborne to be paid being payable, and on any conveyance of land, estate, or property whatsoever, in trust or to be sold, or otherwise converted into money which shall be and intended only as security, either by express stipulation or otherwise, there shall be collected a documentary stamp tax at the following rates:\n\"(a) When the amount secured does not exceed five thousand pesos, Twenty pesos (P20.00);\n\"(b) On each five thousand pesos, or fractional part thereof in excess of five thousand pesos, an additional tax of Ten pesos (P10.00).\n\"On any mortgage, pledge, or deed of trust, where the same shall be made as a security for the payment of a fluctuating account or future advances without fixed limit, the documentary stamp tax on such mortgage, pledge or deed of trust shall be computed on the amount actually loaned or given at the time of the execution of the mortgage, pledge, or deed of trust. However, if subsequent advances are made on such mortgage, pledge or deed of trust, additional documentary stamp tax shall be paid which shall be computed on the basis of the amount advanced or loaned at the rates specified above: Provided, however, That if the full amount of the loan or credit, granted under the mortgage, pledge or deed of trust is specified in such mortgage, pledge or deed of trust, the documentary stamp tax prescibed in this section shall be paid and computed on the full amount of the loan or credit granted.\""}},{"id":"PH-H6141-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Section 196 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 196. Stamp tax on deeds of sale and conveyance of real property. - On all conveyances, deeds, instruments, or writings, other than grants, patents, or original certificates of adjudication issued by the Government, whereby any lands, tenements or other realty sold shall be granted, assigned, transferred, or otherwise conveyed to the purchaser, or purchasers, or to any other person or persons designated by such purchaser or purchasers, there shall be collected a documentary stamp tax at the following rates:\n\"(a) When the consideration, or value received or contracted to be paid for such realty, after making proper allowance of any encumbrance, does not exceed one thousand pesos, Fifteen pesos (P15.00).\n\"(b) For each additional one thousand pesos, or fractional part thereof in excess of one thousand pesos of such consideration or value, Fifteen pesos (P15.00).\n\"When it appears that the amount of the documentary stamp tax payable hereunder has been reduced by an incorrect statement, of the consideration in any conveyance, deed, instrument, or writing subject to such tax the Commissioner, provincial or city treasurer, or other revenue officer shall from the assessment rolls or other reliable source of information, assess the property of its true market value and collect the proper tax thereon.\""}},{"id":"PH-H6141-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Section 197 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 197. Stamp tax on charter parties and similar instruments. - On every charter party, contract, or agreement for the charter of any ship, vessel, or steamer, or any letter or memorandum or other writing between the captain, master, or owner, or other person acting as agent of any ship, vessel, or steamer and any other person or persons for or relating to the charter of any such ship, vessel, or steamer, and on any renewal or transfer of such charter, contract, agreement, letter or memorandum, there shall be collected a documentary stamp tax at the following rates:\n\"(a) If the registered gross tonnage of the ship, vessel, or steamer does not exceed one thousand tons, and the duration of the charter or contract does not exceed six months, Five hundred pesos (P500.00); and for each month or fraction of a month in excess of six months, an additional tax of Fifty pesos (P50.00) shall be paid.\n\"(b) If the registered gross tonnage exceeds one thousand tons and does not exceed ten thousand tons, and the duration of the charter or contract does not exceed six months, One thousand pesos (P1,000.00); and for each month or fraction of a month in excess of six months, an additional tax of One hundred pesos (P100.00) shall be paid.\n\"(c) If the registered gross tonnage exceeds ten thousand tons and the duration of the charter or contract does not exceed six months, One thousand five hundred pesos (P1,500.00); and for each month or fraction of a month in excess of six months, an additional tax of One hundred fifty pesos (P150) shall be paid.\""}},{"id":"PH-H6141-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"The incremental revenues from the increase in the documentary stamp taxes under this Act shall be set aside for the following purposes:\n(a) In 1994 and 1995, twenty-five percent (25%) thereof respectively, shall accrue to the Unified Home-Lending Program under Executive Order No. 90 particularly for mass-socialized housing program to be allocated as follows: fifty percent (50%) for mass-socialized housing; thirty percent (30%) for the community mortgage program; and twenty percent (20%) for land banking and development to be administered by the National Housing Authority: Provided, That not more than one percent (1%) of the respective allocations hereof shall be used for administrative expenses;\n(b) In 1996, twenty-five percent (25%) thereof to be utilized for the National Health Insurance Program that hereafter may be mandated by law; and\n(c) In 1994 and every year thereafter, twenty-five percent (25%) thereof shall accrue to a Special Education Fund to be administered by the Department of Education, Culture and Sports for the construction and repair of school facilities, training of teachers, and procurement or production of instructional materials and teaching aids;\n(d) In 1994 and every year thereafter, fifty percent (50%) thereof shall accrue to a Special Infrastructure Fund for the construction and repair of roads, bridges, dams and irrigation, seaports, and hydroelectric and other indigenous power projects: Provided, however, That for the years 1994 and 1995, thirty percent (30%), and for the years 1996, 1997 and 1998, twenty percent (20%), of this fund shall be allocated for depressed provinces as declared by the President as of the time of the effectivity of this Act: Provided, further, That availments under this fund shall be determined by the President on the basis of equity.\nProvided, finally, That in paragraphs b, c, and d of this section not more than one percent (1%) of the allocated funds thereof shall be used for administrative expenses by the implementing agencies."}},{"id":"PH-H6141-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"The Secretary of Finance shall, upon the recommendation of the Commissioner of Internal Revenue, promulgate the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H6141-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"All laws, decrees, orders, rules and regulations, or any part thereof, which are inconsistent with this Act, are hereby repealed or modified accordingly."}},{"id":"PH-H6141-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"If for any reason, any section or provision of this Act is declared to be unconstitutional, the other sections or provisions hereof which are not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H6141-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazzette or in at least two (2) national newspapers of general circulation whichever comes earlier."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Rationalizing Further the Structure and Administration of the Documentary Stamp Tax, Amending for the Purpose Certain Provisions of the National Internal Revenue Code, as Amended, Allocating Funds for Specific Programs, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6142"] = {"id":"PH-H6142","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7661_1993.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"延长私有化委员会与资产私有化信托存续期限的法案","en":"An Act Extending the Life of the Committee on Privatization and Asset Privatization Trust","orig":"An Act Amending Republic Act Numbered Seven Thousand One Hundred and Eighty-One, Entitled \"An Act Extending the Life of the Committee on Privatization and Asset Privatization Trust\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7661","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-12-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7661_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6142-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 1 of Republic Act No. 7181 is hereby amended to read as follows:\n\"Section 1. The term of the Committee on Privatization and the Asset Privatization Trust created by Proclamation No. 50 'Proclaiming and Launching a Program for the Expeditious Disposition and Privatization of Certain Government Corporations and/or the Assets thereof, and Creating the Committee on Privatization and the Asset Privatization Trust' is hereby extended from December 31,1993 to June 30,1995: Provided, That prior to the beginning of its extended term on January 1, 1994, the President may appoint new members of the Asset Privatization Trust.\n\"During the said extension period, the Committee on Privatization and the Asset Privatization Trust shall continue to exercise the powers, duties and responsibilities provided under Proclamation No. 50, as amended: Provided, That all disposition of any and all assets shall be primarily for cash: Provided however, That the use of government financial instruments and sales by installment may be allowed: Provided, further, That the Committee on Privatization shall serve as the central agency of the privatization program and, accordingly, is further empowered:\n\"(a) To designate the disposition entity for all assets intended for privatization, including all assets and properties recovered by the Presidential Commission on Good Government (PCGG) and government idle properties; and \"(b) When necessary, to appoint a representative to the governing board of a government corporation or corporation with government transferred assets which has been identified for privatization who shall, for the purpose of facilitating privatization, have the powers and privileges of a member of such board, except the right to vote: Provided, That such appointee shall not receive any additional salary or emolument by reason of such appointment: Provided, further, That the appointee shall not be eligible for employment in any capacity whatsoever in the said corporation within two (2) years after privatization.\n\"Upon the effectivity of this Act, all receipts from the sale of assets of the Asset Privatization Trust shall be remitted to the National Treasury in the following proportion: sixty percent (60%) to the special account of the Agrarian Reform Fund and forty percent (40%) to the general fund: Provided, however, That within the ten-year period of implementation of the Comprehensive Agrarian Reform Program the total initial amount of Fifty billion pesos (₱50,000,000,000) shall be satisfied and completed from all sources pursuant to the pertinent provisions of Republic Act No. 6657 and Executive Order No. 229, dated July 1987: Provided, further, That except for subsidiaries of the Government Service Insurance System and the Social Security System, all government-owned or controlled corporations shall remit to the National Government at least fifty percent (50%) of the net proceeds derived from the sale of shares or assets effective October 1, 1992: Provided, finally, That net proceeds shall mean gross proceeds less related liabilities and selling expenses.\n\"All assets held by the Asset Privatization Trust, all moneys and other properties belonging to it, and all its liabilities outstanding upon the expiration of its term shall revert to and be assumed by the National Government. The President of the Philippines shall designate by an executive order the government office or entity to which the assets and liabilities of the Asset Privatization Trust shall be transferred.\n\"All cash advances and all unsettled obligations incurred after the effectivity of this law by the officers and employees of the Committee on Privatization or the Asset Privatization Trust, as finally determined by the proper agency or court of law, must be liquidated on or before June 30, 1995.\""}},{"id":"PH-H6142-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 2 of the same Act is hereby amended to read as follows:\n\"Section 2. The following conditions shall be adhered to in privatization:\n\"(a) In the disposition of assets in corporate form, there shall be no undue dislocation of labor unless all benefits as provided by existing laws or Collective Bargaining Agreements (CBA) shall be complied with: and Provided, That the old qualified personnel shall be given preference in the hiring of new personnel by the new owners.\n\"(b) Assets for disposal shall not revert to previous owners who after final judgment by the proper agency or a court of law, have been found to have mismanaged or diverted the resources of the assets which resulted in loss and bankruptcy: Provided, That if assets are to be reverted back to the previous owner, the price shall not be less than the original transfer price.\n\"(c) Privatization of government assets classified as a strategic industry by the National Economic and Development Authority (NEDA) shall first be approved by the"}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Extending the Life of the Committee on Privatization and Asset Privatization Trust","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6143"] = {"id":"PH-H6143","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1993/ra_7662_1993.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"1993 年法律教育改革法","en":"Legal Education Reform Act of 1993","orig":"Legal Education Reform Act of 1993 An Act Providing for Rreforms in the Legal Education, Creating for the Purpose, a Legal Eeducation Board and for Other purposes."},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7662","issuingBody":"Congress of the Philippines","promulgatedDate":"1993-12-23","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1993/ra_7662_1993.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6143-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. - This Act shall be known as the \"Legal Education Reform Act of 1993.\""}},{"id":"PH-H6143-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policies. - It is hereby declared the policy of the State to uplift the standards of legal education in order to prepare law students for advocacy, counselling, problem-solving, and decision-making, to infuse in them the ethics of the legal profession; to impress on them the importance, nobility and dignity of the legal profession as an equal and indispensable partner of the Bench in the administration of justice and to develop social competence.\nTowards this end, the State shall undertake appropriate reforms in the legal education system, require proper selection of law students, maintain quality among law schools, and require legal apprenticeship and continuing legal education."}},{"id":"PH-H6143-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"General and Specific Objective of Legal Education. - (a) Legal education in the Philippines is geared to attain the following objectives:\n(1) to prepare students for the practice of law;\n(2) to increase awareness among members of the legal profession of the needs of the poor, deprived and oppressed sectors of society;\n(3) to train persons for leadership;\n(4) to contribute towards the promotion and advancement of justice and the improvement of its administration, the legal system and legal institutions in the light of the historical and contemporary development of law in the Philippines and in other countries.\n(b) Legal education shall aim to accomplish the following specific objectives:\n(1) to impart among law students a broad knowledge of law and its various fields and of legal institutions;\n(2) to enhance their legal research abilities to enable them to analyze, articulate and apply the law effectively, as well as to allowthem to have a holistic approach to legal problems and issues;\n(3) to prepare law students for advocacy, counselling, problem-solving and decision-making, and to develop their ability to deal with recognized legal problems of the present and the future;\n(4) to develop competence in any field of law as is necessary for gainful employment or sufficient as a foundation for future training beyond the basic professional degree, and to develop in them the desire and capacity for continuing study and self-improvement;\n(5) to inculcate in them the ethics and responsibilities of the legal profession; and\n(6) to produce lawyers who conscientiously pursue the lofty goals of their profession and to fully adhere to its ethical norms."}},{"id":"PH-H6143-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Legal Education Board; Creation and Composition. - To carry out the purpose of this Act, there is hereby created the Legal Education Board, hereinafter referred to as the Board, attached solely for budgetary purposes and administrative support to the Department of Education, Culture and Sports.\nThe Board shall be composed of a Chairman, who shall preferably be a former justice of the Supreme Court or Court of Appeals, and the following as regular members: a representative of the Integrated Bar of the Philippines (IBP); a representative of the Philippine Association of Law Schools (PALS); a representative from the ranks of active law practitioners; and, a representative from the law students' sector. The Secretary of the Department of Education, Culture and Sports, or his representative, shall be an ex officio member of the Board.\nWith the exception of the representative of the law students' sector, the Chairman and regular members of the Board must be natural-born citizen of the Philippines and members of the Philippine Bar, who have been engaged for at least ten (10) years in the practice of law, as well as in the teaching of law in a duly authorized or recognized law school."}},{"id":"PH-H6143-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Term of Office; Compensation. - The Chairman and regular members of the Board shall be appointed by the President for a term of five (5) years without reappointment from a list of at least three (3) nominees prepared, with prior authorization from the Supreme Court, by the Judicial and Bar Council, for every position or vacancy, and no such appointment shall need confirmation by the Commission on Appointments. Of those first appointed, the Chairman and the representative of the IBP shall hold office for five (5) years, the representatives of the PALS and the PALP, for three (3) years; and the representative from the ranks of active law practitioners and the representative of the law students' sector, for one (1) year, without reappointment. Appointments to any vacancy shall be only for the unexpire portion of the term of the predecessor.\nThe Chairman and regular members of the Board shall have the same salary and rank as the Chairman and members, respectively, of the Constitutional Commissions: Provided, That their salaries shall not be diminished during their term of office."}},{"id":"PH-H6143-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Office and Staff Support. - The Department of Education, Culture and Sports shall provide the necessary office and staff support to the Board, with a principal office to be located in Metropolitan Manila.\nThe Board may appoint such other officers and employees it may deem necessary in the performanceof its powers and functions."}},{"id":"PH-H6143-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Powers and Functions. - For the purpose of achieving the objectives of this Act, the Board shall havethe following powers and functions:\n(a) to administer the legal education system in the country in a manner consistent with the provisions of this Act;\n(b) to supervise the law schools in the country, consistent with its powers and functions as herein enumerated;\n(c) to set the standards of accreditation for law schools taking into account, among others, the size of enrollment, the qualifications of the members of the faculty, the library and other facilities, without encroaching upon the academic freedom of institutions of higher learning;\n(d) to accredit law schools that meet the standards of accreditation;\n(e) to prescribe minimum standards for law admission and minimum qualifications and compensation of faculty members;\n(f) to prescribe the basic curricula for the course of study aligned to the requirements for admission to the Bar, law practice and social consciousness, and such other courses of study as may be prescribed by the law schools and colleges under the different levels of accreditation status;\n(g) to establish a law practice internship as a requirement for taking the Bar which a law student shall undergo with any duly accredited private or public law office or firm or legal assistance group anytime during the law course for a specific period that the Board may decide, but not to exceed a total of twelve (12) months. For this purpose, the Board shall prescribe the necessary guidelines for such accreditation and the specifications of such internship which shall include the actual work of a new member of the Bar.\n(h) to adopt a system of continuing legal education. For this purpose, the Board may provide for the mandatory attendance of practicing lawyers in such courses and for such duration as the Board may deem necessary; and\n(i) to perform such other functions and prescribe such rules and regulations necessary for the attainment of the policies and objectives of this Act."}},{"id":"PH-H6143-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Accreditation of Law Schools. - Educational institutions may not operate a law school unless accredited by the Board. Accreditation of law schools may be granted only to educational institutions recognized by the Government."}},{"id":"PH-H6143-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Withdrawal or Downgrading of Accreditation. - The Board may withdraw or downgrade the accreditation status of a law school if it fails to maintain the standards set for its accreditation status."}},{"id":"PH-H6143-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Effectivity of Withdrawal or Downgrading of Accreditation. - The withdrawal or downgrading of accreditation status shall be effetive after the lapse ofthe semester or trimester following the receipt by the school of the notice of withdrawal or downgrading unless, in the meantime, the school meets and/or upgrades the standards or corrects the deficiencies upon which the withdrawal or downgrading of the accreditation status is based."}},{"id":"PH-H6143-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Legal Education Fund. - There is hereby created a special endowment fund, to be known as the Legal Education Fund, which shall be under the control of the Board, and administered as a separate fund by the Social Security System (SSS) which shall invest the same with due and prudent regard to its solvency, safety and liquidity.\nThe Legal Education Fund shall be established out of, and maintained from, the amounts appropriated pursuant to paragraph 2, Section 13 hereof, and from sixty percent (60%) of the privilege tax paid by every lawyer effective Fiscal Year 1994; and from such donations, legacies, grant-in-aid and other forms of contributions received by the Board for the purposes of this Act.\nBeing a special endowment fund, only the interests earned on the Legal Education Fund shall be used exclusively for the purposes of this Act, including support for faculty development grants, professorial chairs, library improvements and similar programs for the advancement of law teaching and education in accredited law schools.\nThe Fund shall also be used for the operation of the Board. For this purpose, an amount not exceeding ten percent (10%) of the interest on the Fund shall be utilized.\nThe Board, in consultation with the SSS, shall issue the necessary rules and regulations for the collection, administration and utilization of the Fund."}},{"id":"PH-H6143-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Coverage. - The provisions of this Act shall apply to all schools and colleges of law which are presently under the supervision of the Department of Education, Culture and Sports. Hereafter, said supervision shall be transferred to the Board. Law schools and colleges which shall be established following the approval of this Act shall likewise be covered."}},{"id":"PH-H6143-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Appropriation. - The amount of One Million Pesos (P1,000,000.00) is hereby authorized to be charged against the current year's appropriation of the Contingent Fund for the initial expenses of the Board.\nTo form part of the Legal Education Fund, there shall be appropriated annually, under the budget of the Department of Education, Culture and Sports, the amount of Ten Million Pesos (P10,000,000.00) for a period of ten (10) years effective Fiscal Year 1994."}},{"id":"PH-H6143-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Separability Clause. - If any provision of this Act is declared unconstitutional or the application thereof to any person, circumstance or transaction is held invalid, the validity of the remaining provisions of this Act and the applicability of such provisions to other persons, circumstances and transactions shall not be affected thereby."}},{"id":"PH-H6143-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Repealing Clause. - All laws, decrees, executie orders, rules and regulations, issuances or parts thereof inconsistent with this Act is hereby repealed or amended accordingly."}},{"id":"PH-H6143-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity. - This Act shall take effect after fifteen (15) days following the completion of its publication in the Official Gazette or in any two (2) newspapers of general circulation."}}],"pack":"ph-p87","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Legal Education Reform Act of 1993","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
